<script>
  const svg = document.getElementById('svm-svg');
  const pointsLayer = document.getElementById('points-layer');
  const hyperplane = document.getElementById('hyperplane');
  const marginPlus = document.getElementById('margin-plus');
  const marginMinus = document.getElementById('margin-minus');
  const marginPoly = document.getElementById('margin-poly');
  const cSlider = document.getElementById('c-slider');
  const cValDisplay = document.getElementById('c-val');
  const resetBtn = document.getElementById('reset-btn');

  let points = [];
  let w = [0, 0];
  let b = 0;
  let C = 1.0;

  function generateData() {
    points = [];
    // Class 1 (Red)
    for (let i = 0; i < 12; i++) {
      points.push({
        x: 50 + Math.random() * 120,
        y: 50 + Math.random() * 120,
        label: 1
      });
    }
    // Class -1 (Blue)
    for (let i = 0; i < 12; i++) {
      points.push({
        x: 230 + Math.random() * 120,
        y: 230 + Math.random() * 120,
        label: -1
      });
    }
    // Add some noise/overlap points
    points.push({ x: 180 + Math.random() * 40, y: 180 + Math.random() * 40, label: 1 });
    points.push({ x: 180 + Math.random() * 40, y: 180 + Math.random() * 40, label: -1 });

    update();
  }

  // Simple Pegasos-inspired subgradient descent for Linear SVM
  function trainSVM() {
    w = [0.01, 0.01];
    b = 0;
    const lr = 0.01;
    const iterations = 1500;

    // Normalize coordinates for stability
    const normPoints = points.map(p => ({
      x: (p.x - 200) / 100,
      y: (p.y - 200) / 100,
      label: p.label
    }));

    for (let i = 1; i <= iterations; i++) {
      const p = normPoints[Math.floor(Math.random() * normPoints.length)];
      const condition = p.label * (w[0] * p.x + w[1] * p.y + b);

      if (condition < 1) {
        w[0] = w[0] - lr * ( (1/i) * w[0] - C * p.label * p.x );
        w[1] = w[1] - lr * ( (1/i) * w[1] - C * p.label * p.y );
        b = b + lr * C * p.label;
      } else {
        w[0] = w[0] - lr * (1/i) * w[0];
        w[1] = w[1] - lr * (1/i) * w[1];
      }
    }
  }

  function draw() {
    pointsLayer.innerHTML = '';

    // Draw line: w0*x + w1*y + b = 0  => y = (-w0*x - b) / w1
    // In SVG space: x_svg = x*100 + 200, y_svg = y*100 + 200
    const getYSvg = (x_svg, offset = 0) => {
      const x_norm = (x_svg - 200) / 100;
      const y_norm = (offset - b - w[0] * x_norm) / w[1];
      return y_norm * 100 + 200;
    };

    const x1 = 0, x2 = 400;
    const y1 = getYSvg(x1, 0), y2 = getYSvg(x2, 0);
    const yp1 = getYSvg(x1, 1), yp2 = getYSvg(x2, 1);
    const ym1 = getYSvg(x1, -1), ym2 = getYSvg(x2, -1);

    hyperplane.setAttribute('x1', x1);
    hyperplane.setAttribute('y1', y1);
    hyperplane.setAttribute('x2', x2);
    hyperplane.setAttribute('y2', y2);

    marginPlus.setAttribute('x1', x1);
    marginPlus.setAttribute('y1', yp1);
    marginPlus.setAttribute('x2', x2);
    marginPlus.setAttribute('y2', yp2);

    marginMinus.setAttribute('x1', x1);
    marginMinus.setAttribute('y1', ym1);
    marginMinus.setAttribute('x2', x2);
    marginMinus.setAttribute('y2', ym2);

    // Margin polygon
    marginPoly.setAttribute('d', `M ${x1} ${yp1} L ${x2} ${yp2} L ${x2} ${ym2} L ${x1} ${ym1} Z`);

    // Points
    points.forEach(p => {
      const x_norm = (p.x - 200) / 100;
      const y_norm = (p.y - 200) / 100;
      const dist = p.label * (w[0] * x_norm + w[1] * y_norm + b);
      const isSV = dist <= 1.01;

      if (isSV) {
        const ring = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        ring.setAttribute('cx', p.x);
        ring.setAttribute('cy', p.y);
        ring.setAttribute('r', 8);
        ring.setAttribute('class', 'support-vector-ring');
        pointsLayer.appendChild(ring);
      }

      const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      circle.setAttribute('cx', p.x);
      circle.setAttribute('cy', p.y);
      circle.setAttribute('r', 5);
      circle.setAttribute('fill', p.label === 1 ? '#E24B4A' : '#378ADD');
      circle.setAttribute('stroke', 'white');
      circle.setAttribute('stroke-width', '1');
      pointsLayer.appendChild(circle);
    });
  }

  function update() {
    trainSVM();
    draw();
  }

  cSlider.addEventListener('input', (e) => {
    const val = parseFloat(e.target.value);
    C = Math.pow(10, val);
    cValDisplay.textContent = C.toFixed(2);
    update();
  });

  resetBtn.addEventListener('click', generateData);

  // Initial
  generateData();
</script>
