<script>
  const stages = [
    {
      name: "传统公共行政 (PA)",
      period: "1880s - 1970s",
      tag: "效率与官僚制",
      desc: "自上而下的层级控制模式",
      theory: "官僚制理论、政治行政二分法。代表人物：威尔逊 (Wilson)、韦伯 (Weber)、古利克 (Gulick)。",
      metrics: [90, 85, 20, 15, 30], // 效率, 稳定性, 民主, 市场化, 协同
      nodes: [
        { id: 'gov', label: '政府 (官僚机构)', x: 200, y: 60, color: '#3b82f6', size: 25 },
        { id: 'citizen', label: '公民 (被动管理者)', x: 200, y: 180, color: '#94a3b8', size: 20 }
      ],
      links: [{ from: 'gov', to: 'citizen', label: '指令与控制' }]
    },
    {
      name: "新公共管理 (NPM)",
      period: "1980s - 1990s",
      tag: "效率与市场化",
      desc: "以市场为导向的绩效模式",
      theory: "公共选择理论、委托代理理论、交易成本理论。代表人物：胡德 (Hood)、奥斯本 (Osborne)。",
      metrics: [95, 40, 35, 90, 45],
      nodes: [
        { id: 'gov', label: '政府 (掌舵者)', x: 100, y: 80, color: '#3b82f6', size: 22 },
        { id: 'market', label: '市场 (服务提供)', x: 300, y: 80, color: '#f59e0b', size: 22 },
        { id: 'citizen', label: '公民 (顾客)', x: 200, y: 180, color: '#94a3b8', size: 20 }
      ],
      links: [
        { from: 'gov', to: 'market', label: '合同外包' },
        { from: 'market', to: 'citizen', label: '服务选择' }
      ]
    },
    {
      name: "新公共服务 (NPS)",
      period: "2000s - 2010s",
      tag: "民主与公民权",
      desc: "以公民为中心的服务模式",
      theory: "民主公民权理论、社区与公民社会理论。代表人物：登哈特夫妇 (Denhardt & Denhardt)。",
      metrics: [60, 65, 95, 30, 75],
      nodes: [
        { id: 'citizen', label: '公民 (中心)', x: 200, y: 120, color: '#f43f5e', size: 28 },
        { id: 'gov', label: '政府 (服务者)', x: 200, y: 40, color: '#3b82f6', size: 20 },
        { id: 'society', label: '社会组织', x: 200, y: 200, color: '#14b8a6', size: 20 }
      ],
      links: [
        { from: 'gov', to: 'citizen', label: '对话与服务' },
        { from: 'society', to: 'citizen', label: '赋能' }
      ]
    },
    {
      name: "新公共治理 (NPG)",
      period: "2010s - 至今",
      tag: "网络化与协同",
      desc: "多中心参与的协同治理网络",
      theory: "网络治理理论、多中心治理、社会资本理论。代表人物：奥斯特罗姆 (Ostrom)、罗茨 (Rhodes)。",
      metrics: [75, 55, 85, 65, 95],
      nodes: [
        { id: 'gov', label: '政府', x: 200, y: 60, color: '#3b82f6', size: 22 },
        { id: 'market', label: '企业', x: 320, y: 140, color: '#f59e0b', size: 20 },
        { id: 'society', label: '社会组织', x: 80, y: 140, color: '#14b8a6', size: 20 },
        { id: 'citizen', label: '公民', x: 200, y: 200, color: '#f43f5e', size: 20 }
      ],
      links: [
        { from: 'gov', to: 'market', label: '' },
        { from: 'market', to: 'citizen', label: '' },
        { from: 'citizen', to: 'society', label: '' },
        { from: 'society', to: 'gov', label: '' },
        { from: 'gov', to: 'citizen', label: '协同' }
      ]
    }
  ];

  let radarChart;
  const ctx = document.getElementById('radarChart').getContext('2d');

  function initChart() {
    radarChart = new Chart(ctx, {
      type: 'radar',
      data: {
        labels: ['效率', '稳定性', '民主参与', '市场化', '协同性'],
        datasets: [{
          data: stages[0].metrics,
          backgroundColor: 'rgba(59, 130, 246, 0.2)',
          borderColor: '#3b82f6',
          borderWidth: 2,
          pointBackgroundColor: '#3b82f6',
          pointRadius: 3
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          r: {
            min: 0,
            max: 100,
            beginAtZero: true,
            ticks: { display: false },
            grid: { color: 'rgba(148, 163, 184, 0.2)' },
            angleLines: { color: 'rgba(148, 163, 184, 0.2)' },
            pointLabels: { font: { size: 11 }, color: '#64748b' }
          }
        },
        plugins: { legend: { display: false } }
      }
    });
  }

  function updatePowerMap(index) {
    const stage = stages[index];
    const nodesGroup = document.getElementById('nodes-group');
    const linksGroup = document.getElementById('links-group');

    nodesGroup.innerHTML = '';
    linksGroup.innerHTML = '';

    // Draw Links
    stage.links.forEach(link => {
      const from = stage.nodes.find(n => n.id === link.from);
      const to = stage.nodes.find(n => n.id === link.to);

      const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
      line.setAttribute("x1", from.x);
      line.setAttribute("y1", from.y);
      line.setAttribute("x2", to.x);
      line.setAttribute("y2", to.y);
      line.setAttribute("stroke", "var(--color-border-primary)");
      line.setAttribute("stroke-width", "1.5");
      line.setAttribute("marker-end", "url(#arrow)");
      linksGroup.appendChild(line);

      if (link.label) {
        const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
        text.setAttribute("x", (from.x + to.x) / 2 + 5);
        text.setAttribute("y", (from.y + to.y) / 2 - 5);
        text.setAttribute("fill", "var(--color-text-secondary)");
        text.setAttribute("font-size", "10");
        text.textContent = link.label;
        linksGroup.appendChild(text);
      }
    });

    // Draw Nodes
    stage.nodes.forEach(node => {
      const g = document.createElementNS("http://www.w3.org/2000/svg", "g");

      const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
      circle.setAttribute("cx", node.x);
      circle.setAttribute("cy", node.y);
      circle.setAttribute("r", node.size);
      circle.setAttribute("fill", node.color);
      circle.setAttribute("stroke", "#fff");
      circle.setAttribute("stroke-width", "2");

      const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
      text.setAttribute("x", node.x);
      text.setAttribute("y", node.y + node.size + 15);
      text.setAttribute("text-anchor", "middle");
      text.setAttribute("fill", "var(--color-text-primary)");
      text.setAttribute("class", "node-label");
      text.textContent = node.label;

      g.appendChild(circle);
      g.appendChild(text);
      nodesGroup.appendChild(g);
    });
  }

  function setStage(index) {
    const stage = stages[index];
    document.getElementById('stage-slider').value = index;

    // Update Text Content
    document.getElementById('stage-name').innerText = stage.name;
    document.getElementById('stage-period').innerText = stage.period;
    document.getElementById('stage-tag').innerText = stage.tag;
    document.getElementById('structure-desc').innerText = stage.desc;
    document.getElementById('theory-text').innerText = stage.theory;

    // Update Active Label
    const labels = document.querySelectorAll('#slider-labels span');
    labels.forEach((l, i) => l.className = i == index ? 'active' : '');

    // Update Charts
    radarChart.data.datasets[0].data = stage.metrics;
    radarChart.update();
    updatePowerMap(index);
  }

  document.getElementById('stage-slider').addEventListener('input', (e) => {
    setStage(parseInt(e.target.value));
  });

  // Init
  initChart();
  setStage(0);
</script>
