<div class="sim-container">
  <canvas id="moonCanvas"></canvas>

  <div class="hud">
    <div class="metric-card">
      <div class="metric-label">高度 (m)</div>
      <div class="metric-value" id="alt-val">450.0</div>
    </div>
    <div class="metric-card">
      <div class="metric-label">垂直速度 (m/s)</div>
      <div class="metric-value" id="vel-val">0.0</div>
    </div>
    <div class="metric-card">
      <div class="metric-label">燃料 (%)</div>
      <div class="metric-value" id="fuel-val">100.0</div>
    </div>
    <div class="metric-card">
      <div class="metric-label">重力 (G)</div>
      <div class="metric-value">1.62</div>
    </div>
  </div>

  <div id="statusOverlay" class="status-overlay">
    <div id="statusTitle" class="status-title">任务结束</div>
    <div id="statusMsg" class="status-msg"></div>
    <button class="reset-btn" onclick="resetSim()">重新开始</button>
  </div>

  <div class="controls">
    <div class="control-group">
      <label style="font-size: 13px; color: rgba(255,255,255,0.6)">推力强度</label>
      <input type="range" id="thrustPower" min="2" max="5" step="0.1" value="3.5">
    </div>

    <button id="thrustBtn" class="thrust-btn">喷火 (空格键)</button>

    <button class="reset-btn" onclick="resetSim()">重置</button>
  </div>
</div>

<script>
  const canvas = document.getElementById('moonCanvas');
  const ctx = canvas.getContext('2d');
  const altEl = document.getElementById('alt-val');
  const velEl = document.getElementById('vel-val');
  const fuelEl = document.getElementById('fuel-val');
  const statusOverlay = document.getElementById('statusOverlay');
  const statusTitle = document.getElementById('statusTitle');
  const statusMsg = document.getElementById('statusMsg');
  const thrustBtn = document.getElementById('thrustBtn');
  const thrustPowerInput = document.getElementById('thrustPower');

  // 物理常量
  const G = 1.62; // 月球重力
  const SAFE_VELOCITY = 5.0; // 安全着陆速度
  const INITIAL_ALT = 450;
  const DT = 1/60;

  // 状态变量
  let state = {
    y: 50, // 屏幕坐标
    altitude: INITIAL_ALT,
    velocity: 0,
    fuel: 100,
    thrusting: false,
    gameOver: false,
    stars: []
  };

  // 初始化星星
  for(let i=0; i<100; i++) {
    state.stars.push({
      x: Math.random() * 1000,
      y: Math.random() * 400,
      size: Math.random() * 2
    });
  }

  function resetSim() {
    state.altitude = INITIAL_ALT;
    state.velocity = 0;
    state.fuel = 100;
    state.thrusting = false;
    state.gameOver = false;
    statusOverlay.style.display = 'none';
  }

  // 输入监听
  const setThrust = (val) => { if(!state.gameOver) state.thrusting = val; };
  window.addEventListener('keydown', (e) => { if(e.code === 'Space') { e.preventDefault(); setThrust(true); } });
  window.addEventListener('keyup', (e) => { if(e.code === 'Space') setThrust(false); });
  thrustBtn.addEventListener('mousedown', () => setThrust(true));
  thrustBtn.addEventListener('mouseup', () => setThrust(false));
  thrustBtn.addEventListener('touchstart', (e) => { e.preventDefault(); setThrust(true); });
  thrustBtn.addEventListener('touchend', (e) => { e.preventDefault(); setThrust(false); });

  function update() {
    if (state.gameOver) return;

    const maxThrust = parseFloat(thrustPowerInput.value);
    let accel = G;

    if (state.thrusting && state.fuel > 0) {
      accel -= maxThrust;
      state.fuel -= 0.15;
      if (state.fuel < 0) state.fuel = 0;
    }

    state.velocity += accel * DT;
    state.altitude -= state.velocity * DT * 10; // 缩放系数以便视觉展示

    // 边界判定
    if (state.altitude <= 0) {
      state.altitude = 0;
      state.gameOver = true;
      checkLanding();
    }

    if (state.altitude > 1000) {
        state.altitude = 1000;
        state.velocity = 0;
    }

    // 更新UI
    altEl.textContent = Math.max(0, state.altitude).toFixed(1);
    velEl.textContent = state.velocity.toFixed(1);
    velEl.className = `metric-value ${Math.abs(state.velocity) > SAFE_VELOCITY ? 'danger-text' : 'success-text'}`;
    fuelEl.textContent = state.fuel.toFixed(1);
  }

  function checkLanding() {
    statusOverlay.style.display = 'block';
    if (Math.abs(state.velocity) <= SAFE_VELOCITY) {
      statusTitle.textContent = "着陆成功！";
      statusTitle.className = "status-title success-text";
      statusMsg.textContent = `完美的软着陆。最终速度: ${state.velocity.toFixed(2)} m/s`;
    } else {
      statusTitle.textContent = "飞船坠毁";
      statusTitle.className = "status-title danger-text";
      statusMsg.textContent = `速度过快导致结构损毁。最终速度: ${state.velocity.toFixed(2)} m/s`;
    }
  }

  function draw() {
    const w = canvas.width = canvas.offsetWidth;
    const h = canvas.height = canvas.offsetHeight;
    ctx.clearRect(0, 0, w, h);

    // 画星星
    ctx.fillStyle = "white";
    state.stars.forEach(s => {
      ctx.beginPath();
      ctx.arc((s.x % w), s.y, s.size, 0, Math.PI*2);
      ctx.fill();
    });

    // 画月表
    ctx.fillStyle = "#222";
    ctx.beginPath();
    ctx.moveTo(0, h - 40);
    for(let i=0; i<=w; i+=20) {
        ctx.lineTo(i, h - 40 + Math.sin(i*0.05)*5);
    }
    ctx.lineTo(w, h);
    ctx.lineTo(0, h);
    ctx.fill();

    ctx.strokeStyle = "#444";
    ctx.lineWidth = 2;
    ctx.stroke();

    // 计算火箭位置
    // 映射 altitude (0-450) 到 屏幕高度 (h-60 到 40)
    const rocketY = (h - 60) - (state.altitude / INITIAL_ALT) * (h - 100);
    const rocketX = w / 2;

    // 画火焰
    if (state.thrusting && state.fuel > 0 && !state.gameOver) {
      ctx.fillStyle = "#f0997b";
      ctx.beginPath();
      ctx.moveTo(rocketX - 6, rocketY + 15);
      ctx.lineTo(rocketX + 6, rocketY + 15);
      ctx.lineTo(rocketX, rocketY + 15 + Math.random() * 30);
      ctx.fill();

      ctx.fillStyle = "#ef9f27";
      ctx.beginPath();
      ctx.moveTo(rocketX - 4, rocketY + 15);
      ctx.lineTo(rocketX + 4, rocketY + 15);
      ctx.lineTo(rocketX, rocketY + 15 + Math.random() * 15);
      ctx.fill();
    }

    // 画火箭 (简单矢量)
    ctx.save();
    ctx.translate(rocketX, rocketY);

    // 船体
    ctx.fillStyle = state.gameOver && Math.abs(state.velocity) > SAFE_VELOCITY ? "#444" : "#ddd";
    ctx.beginPath();
    ctx.moveTo(0, -20);
    ctx.lineTo(10, 0);
    ctx.lineTo(10, 15);
    ctx.lineTo(-10, 15);
    ctx.lineTo(-10, 0);
    ctx.closePath();
    ctx.fill();

    // 窗户
    ctx.fillStyle = "#378add";
    ctx.beginPath();
    ctx.arc(0, -5, 4, 0, Math.PI*2);
    ctx.fill();

    // 起落架
    ctx.strokeStyle = "#999";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-10, 10); ctx.lineTo(-18, 20); ctx.lineTo(-22, 20);
    ctx.moveTo(10, 10); ctx.lineTo(18, 20); ctx.lineTo(22, 20);
    ctx.stroke();

    ctx.restore();

    update();
    requestAnimationFrame(draw);
  }

  draw();
</script>
