      g = 0.16;
    } else { // Landing
      const ratio = (progress - 900) / 100;
      speed = 1.6 * (1 - ratio);
      alt = 100 * (1 - ratio);
      fuel = 65 - ratio * 15;
      g = 0.16 + ratio * 0.84;
    }

    document.getElementById('val-speed').textContent = speed.toFixed(2);
