    ctx.setLineDash([]);

    // Rocket on trajectory
    const t = ratio;
    const qx = (1-t)*(1-t)*80 + 2*(1-t)*t*(w/2) + t*t*(w-80);
    const qy = (1-t)*(1-t)*(h/2) + 2*(1-t)*t*(h/2 - 100) + t*t*(h/2);

    // Angle calculation
    const dx = 2*(1-t)*(w/2 - 80) + 2*t*(w - 80 - w/2);
    const dy = 2*(1-t)*(h/2 - 100 - h/2) + 2*t*(h/2 - (h/2 - 100));
    const angle = Math.atan2(dy, dx);

    drawRocket(qx, qy, angle, false);
