  function drawRocket(x, y, angle, thrust) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);

    // Flame
    if (thrust) {
      ctx.beginPath();
      ctx.moveTo(-4, 10);
      ctx.lineTo(0, 10 + Math.random() * 15);
      ctx.lineTo(4, 10);
      ctx.fillStyle = '#EF9F27';
      ctx.fill();
    }

    // Body
    ctx.fillStyle = '#eee';
    ctx.beginPath();
    ctx.moveTo(0, -12);
    ctx.lineTo(6, 8);
    ctx.lineTo(-6, 8);
    ctx.closePath();
    ctx.fill();

    // Window
    ctx.fillStyle = '#333';
    ctx.beginPath();
    ctx.arc(0, -2, 2, 0, Math.PI*2);
    ctx.fill();

    ctx.restore();
  }

