      if (progress > 1000) progress = 1000;
      slider.value = progress;
      updateUI();
      requestAnimationFrame(animate);
    } else {
      isPlaying = false;
      playBtn.textContent = "播放";
    }
  }

  // Init
  setTimeout(() => {
    resize();
    updateUI();
  }, 0);
</script>
