<script>
const { useState, useMemo, useEffect, useRef } = React;

const COLORS = {
  0: { bg: '#EEEDFE', dot: '#534AB7', boundary: 'rgba(83, 74, 183, 0.2)' }, // Purple
  1: { bg: '#E1F5EE', dot: '#0F6E56', boundary: 'rgba(15, 110, 86, 0.2)' }, // Teal
  2: { bg: '#FAECE7', dot: '#993C1D', boundary: 'rgba(153, 60, 29, 0.2)' }  // Coral
};

const KNNWidget = () => {
  const [k, setK] = useState(3);
  const [testPoint, setTestPoint] = useState(null);
  const canvasRef = useRef(null);
  const containerRef = useRef(null);

  // Generate random data
  const data = useMemo(() => {
    const points = [];
    const centers = [
      { x: 0.3, y: 0.3, label: 0 },
      { x: 0.7, y: 0.7, label: 1 },
      { x: 0.7, y: 0.3, label: 2 }
    ];

    centers.forEach(center => {
      for (let i = 0; i < 15; i++) {
        points.push({
          x: center.x + (Math.random() - 0.5) * 0.35,
          y: center.y + (Math.random() - 0.5) * 0.35,
          label: center.label,
          id: Math.random()
        });
      }
    });
    return points;
  }, []);

  const getNeighbors = (x, y, kVal) => {
    return data
      .map(p => ({
        ...p,
        dist: Math.sqrt(Math.pow(p.x - x, 2) + Math.pow(p.y - y, 2))
      }))
      .sort((a, b) => a.dist - b.dist)
      .slice(0, kVal);
  };

  const classify = (x, y, kVal) => {
    const neighbors = getNeighbors(x, y, kVal);
    const counts = {};
    neighbors.forEach(n => {
      counts[n.label] = (counts[n.label] || 0) + 1;
    });
    let maxCount = -1;
    let winner = 0;
    for (const label in counts) {
      if (counts[label] > maxCount) {
        maxCount = counts[label];
        winner = parseInt(label);
      }
    }
    return winner;
  };

  // Draw decision boundary
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const size = 100; // Grid resolution
    canvas.width = size;
    canvas.height = size;

    const imageData = ctx.createImageData(size, size);
    for (let i = 0; i < size; i++) {
      for (let j = 0; j < size; j++) {
        const x = i / size;
        const y = j / size;
        const label = classify(x, y, k);
        const color = COLORS[label].dot;

        // Convert hex to RGB for imageData
        const r = parseInt(color.slice(1, 3), 16);
        const g = parseInt(color.slice(3, 5), 16);
        const b = parseInt(color.slice(5, 7), 16);

        const idx = (j * size + i) * 4;
        imageData.data[idx] = r;
        imageData.data[idx + 1] = g;
        imageData.data[idx + 2] = b;
        imageData.data[idx + 3] = 40; // Low opacity for boundary
      }
    }
    ctx.putImageData(imageData, 0, 0);
  }, [k, data]);

  const handleCanvasClick = (e) => {
