<script>
  const canvas = document.getElementById('knnCanvas');
  const ctx = canvas.getContext('2d');
  const kSlider = document.getElementById('kSlider');
  const kValueDisplay = document.getElementById('kValueDisplay');
  const resetBtn = document.getElementById('resetBtn');
  const predictionText = document.getElementById('predictionText');
  const votesADisplay = document.getElementById('votesA');
  const votesBDisplay = document.getElementById('votesB');
  const resultCard = document.getElementById('resultCard');

  // Internal resolution
  const W = 800;
  const H = 600;
  canvas.width = W;
  canvas.height = H;

  let points = [];
  let testPoint = { x: W / 2, y: H / 2 };
  let k = parseInt(kSlider.value);

  function initData() {
    points = [];
    // Generate two clusters
    for (let i = 0; i < 20; i++) {
      points.push({
        x: 100 + Math.random() * 350,
        y: 100 + Math.random() * 400,
        label: 'A'
      });
      points.push({
        x: 350 + Math.random() * 350,
        y: 100 + Math.random() * 400,
        label: 'B'
      });
    }
    update();
  }

  function getDist(p1, p2) {
    return Math.sqrt((p1.x - p2.x) ** 2 + (p1.y - p2.y) ** 2);
  }

  function update() {
    // Calculate distances
    const distances = points.map(p => ({
      ...p,
      dist: getDist(testPoint, p)
    }));

    // Sort and pick K nearest
    distances.sort((a, b) => a.dist - b.dist);
    const neighbors = distances.slice(0, k);

    // Vote
    let countA = 0;
    let countB = 0;
    neighbors.forEach(n => {
      if (n.label === 'A') countA++;
      else countB++;
    });

    const winner = countA >= countB ? 'A' : 'B';

    // Update UI
    kValueDisplay.textContent = k;
    votesADisplay.textContent = countA;
    votesBDisplay.textContent = countB;
    predictionText.textContent = `类别 ${winner}`;
    predictionText.style.color = winner === 'A' ? 'var(--color-class-a)' : 'var(--color-class-b)';
    resultCard.style.setProperty('--border-color', winner === 'A' ? 'var(--color-class-a)' : 'var(--color-class-b)');

    draw(neighbors, winner);
  }

  function draw(neighbors, winner) {
    ctx.clearRect(0, 0, W, H);

    // Draw lines to neighbors
    ctx.setLineDash([5, 5]);
    ctx.lineWidth = 1;
    neighbors.forEach(n => {
      ctx.beginPath();
      ctx.moveTo(testPoint.x, testPoint.y);
      ctx.lineTo(n.x, n.y);
      ctx.strokeStyle = n.label === 'A' ? 'rgba(226, 75, 74, 0.4)' : 'rgba(55, 138, 221, 0.4)';
      ctx.stroke();
    });
    ctx.setLineDash([]);

    // Draw points
    points.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, 6, 0, Math.PI * 2);
      ctx.fillStyle = p.label === 'A' ? '#E24B4A' : '#378ADD';
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.8)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
    });

    // Draw test point halo
    ctx.beginPath();
    ctx.arc(testPoint.x, testPoint.y, 12, 0, Math.PI * 2);
    ctx.fillStyle = winner === 'A' ? 'rgba(226, 75, 74, 0.2)' : 'rgba(55, 138, 221, 0.2)';
    ctx.fill();

    // Draw test point
    ctx.beginPath();
    ctx.arc(testPoint.x, testPoint.y, 8, 0, Math.PI * 2);
    ctx.fillStyle = '#1D9E75';
    ctx.fill();
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  // Interaction
  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = W / rect.width;
    const scaleY = H / rect.height;
    testPoint.x = (e.clientX - rect.left) * scaleX;
    testPoint.y = (e.clientY - rect.top) * scaleY;
    update();
  });

  kSlider.addEventListener('input', () => {
    k = parseInt(kSlider.value);
    update();
  });

  resetBtn.addEventListener('click', initData);

  // Initial run
  initData();
</script>
