  const canvas = document.getElementById('svmCanvas');
  const ctx = canvas.getContext('2d');
  const container = document.getElementById('canvas-container');

  let width, height;
  let points = [];
  let currentClass = 1;
  let svmModel = new svm.SVM();

  // Initial state: some random separable points
  function initData() {
    points = [
      {x: 0.2, y: 0.3, label: 1}, {x: 0.3, y: 0.2, label: 1}, {x: 0.25, y: 0.4, label: 1},
      {x: 0.7, y: 0.8, label: -1}, {x: 0.8, y: 0.7, label: -1}, {x: 0.75, y: 0.6, label: -1}
    ];
    updateParams();
  }

