    document.getElementById('btn-blue').classList.toggle('active', c === -1);
  }

  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / width;
    const y = (e.clientY - rect.top) / height;
    points.push({x, y, label: currentClass});
    updateParams();
  });

  function clearData() {
    points = [];
    updateParams();
  }

  function updateParams() {
    const kernel = document.getElementById('kernel-select').value;
    const cExp = parseFloat(document.getElementById('c-slider').value);
    const C = Math.pow(10, cExp);
    const gExp = parseFloat(document.getElementById('gamma-slider').value);
    const gamma = Math.pow(10, gExp);

    document.getElementById('c-val').textContent = C.toFixed(2);
    document.getElementById('gamma-val').textContent = gamma.toFixed(3);
    document.getElementById('gamma-group').style.display = kernel === 'rbf' ? 'flex' : 'none';
    document.getElementById('count-pts').textContent = points.length;

    if (points.length > 1) {
      const data = points.map(p => [p.x, p.y]);
      const labels = points.map(p => p.label);

      svmModel = new svm.SVM();
      svmModel.train(data, labels, {
        kernel: kernel,
        rbfsigma: kernel === 'rbf' ? 1 / Math.sqrt(2 * gamma) : 0.1,
        C: C
      });

      // Count support vectors
      const svCount = svmModel.alpha.filter(a => Math.abs(a) > 1e-5).length;
      document.getElementById('count-sv').textContent = svCount;
    } else {
      document.getElementById('count-sv').textContent = '0';
    }

    draw();
  }

  function draw() {
    if (!width || !height) return;
    ctx.clearRect(0, 0, width, height);

    // Draw decision boundary background
    if (points.length > 1) {
      const res = 10; // Grid resolution
      for (let i = 0; i < width; i += res) {
        for (let j = 0; j < height; j += res) {
          const score = svmModel.predict([[i / width, j / height]])[0];

          if (Math.abs(score) <= 1.0) {
            // Margin area
            ctx.fillStyle = 'var(--color-background-secondary)';
          } else if (score > 0) {
            ctx.fillStyle = 'var(--color-red-light)';
          } else {
            ctx.fillStyle = 'var(--color-blue-light)';
          }
          ctx.fillRect(i, j, res, res);
        }
      }

      // Draw boundary line (contour)
      ctx.beginPath();
      ctx.lineWidth = 1.5;
      ctx.strokeStyle = 'var(--color-border-primary)';
      // Simple contouring could be added here, but for now we rely on the color change
    }

    // Draw points
    points.forEach((p, idx) => {
      const px = p.x * width;
      const py = p.y * height;

      // Check if it's a support vector
      const isSV = points.length > 1 && Math.abs(svmModel.alpha[idx]) > 1e-5;

      if (isSV) {
        ctx.beginPath();
        ctx.arc(px, py, 8, 0, Math.PI * 2);
        ctx.strokeStyle = 'var(--color-text-primary)';
        ctx.lineWidth = 1;
        ctx.stroke();
      }

      ctx.beginPath();
      ctx.arc(px, py, 5, 0, Math.PI * 2);
      ctx.fillStyle = p.label === 1 ? 'var(--color-red)' : 'var(--color-blue)';
      ctx.fill();
    });
  }

  initData();
</script>
