<script>
  const state = {
    points: [],
    testPoint: null,
    k: 3,
    neighbors: [],
    prediction: null
  };

  const svg = document.getElementById('knn-plot');
  const kRange = document.getElementById('k-range');
  const kValue = document.getElementById('k-value');
  const resetBtn = document.getElementById('reset-btn');
  const predResult = document.getElementById('pred-result');
  const neighborSplit = document.getElementById('neighbor-split');

  // Initialize random points in two clusters
  function initPoints() {
    const pts = [];
    // Cluster A (Top-Leftish)
    for (let i = 0; i < 12; i++) {
      pts.push({
        x: 150 + Math.random() * 300,
        y: 100 + Math.random() * 200,
        label: 'A'
      });
    }
    // Cluster B (Bottom-Rightish)
    for (let i = 0; i < 12; i++) {
      pts.push({
        x: 550 + Math.random() * 300,
        y: 250 + Math.random() * 200,
        label: 'B'
      });
    }
    state.points = pts;
  }

  function calculateKNN() {
    if (!state.testPoint) return;

    const distances = state.points.map((p, index) => ({
      index,
      dist: Math.hypot(p.x - state.testPoint.x, p.y - state.testPoint.y),
      label: p.label
    }));

    distances.sort((a, b) => a.dist - b.dist);
    state.neighbors = distances.slice(0, state.k);

    const counts = state.neighbors.reduce((acc, curr) => {
      acc[curr.label] = (acc[curr.label] || 0) + 1;
      return acc;
    }, {});

    state.prediction = (counts['A'] || 0) >= (counts['B'] || 0) ? 'A' : 'B';
    if (counts['A'] === counts['B']) state.prediction = '平局';
  }

  function render() {
    svg.innerHTML = '';

    // Draw background grid
    for(let i=0; i<=1000; i+=100) {
      const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
      line.setAttribute("x1", i); line.setAttribute("y1", 0);
      line.setAttribute("x2", i); line.setAttribute("y2", 562.5);
      line.setAttribute("stroke", "var(--color-border-tertiary)");
      line.setAttribute("stroke-width", "0.5");
      svg.appendChild(line);
    }
    for(let i=0; i<=562.5; i+=100) {
      const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
      line.setAttribute("x1", 0); line.setAttribute("y1", i);
      line.setAttribute("x2", 1000); line.setAttribute("y2", i);
      line.setAttribute("stroke", "var(--color-border-tertiary)");
      line.setAttribute("stroke-width", "0.5");
      svg.appendChild(line);
    }

    // Draw lines to neighbors
    if (state.testPoint && state.neighbors.length > 0) {
      state.neighbors.forEach(n => {
        const p = state.points[n.index];
        const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
        line.setAttribute("x1", state.testPoint.x);
        line.setAttribute("y1", state.testPoint.y);
        line.setAttribute("x2", p.x);
        line.setAttribute("y2", p.y);
        line.setAttribute("stroke", "var(--color-text-tertiary)");
        line.setAttribute("stroke-width", "1.5");
        line.setAttribute("stroke-dasharray", "4 2");
        svg.appendChild(line);
      });
    }

    // Draw data points
    state.points.forEach((p, idx) => {
      const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
      circle.setAttribute("cx", p.x);
      circle.setAttribute("cy", p.y);
      circle.setAttribute("r", "8");
      circle.setAttribute("fill", p.label === 'A' ? "var(--color-a)" : "var(--color-b)");

      // Highlight if neighbor
      const isNeighbor = state.neighbors.some(n => n.index === idx);
      if (isNeighbor) {
        circle.setAttribute("stroke", "var(--color-text-primary)");
        circle.setAttribute("stroke-width", "3");
        circle.setAttribute("r", "10");
      }
      svg.appendChild(circle);
    });

    // Draw test point
    if (state.testPoint) {
      const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
      circle.setAttribute("cx", state.testPoint.x);
      circle.setAttribute("cy", state.testPoint.y);
      circle.setAttribute("r", "12");
      circle.setAttribute("fill", "var(--color-test)");
      circle.setAttribute("stroke", "white");
      circle.setAttribute("stroke-width", "3");
      svg.appendChild(circle);
    }

    // Update UI text
    kValue.textContent = state.k;
    if (state.testPoint) {
      predResult.textContent = `类别 ${state.prediction}`;
      predResult.style.color = state.prediction === 'A' ? 'var(--color-a)' : (state.prediction === 'B' ? 'var(--color-b)' : 'var(--color-text-primary)');
      const aCount = state.neighbors.filter(n => n.label === 'A').length;
      const bCount = state.neighbors.filter(n => n.label === 'B').length;
      neighborSplit.textContent = `${aCount} : ${bCount}`;
    } else {
      predResult.textContent = "请点击图表";
      predResult.style.color = "var(--color-text-tertiary)";
      neighborSplit.textContent = "—";
    }
  }

  svg.addEventListener('click', (e) => {
    const rect = svg.getBoundingClientRect();
    const scaleX = 1000 / rect.width;
    const scaleY = 562.5 / rect.height;
    state.testPoint = {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY
    };
    calculateKNN();
    render();
  });

  kRange.addEventListener('input', (e) => {
    state.k = parseInt(e.target.value);
    if (state.testPoint) calculateKNN();
    render();
  });

  resetBtn.addEventListener('click', () => {
    state.testPoint = null;
    state.neighbors = [];
    state.prediction = null;
    render();
  });

  // Initial setup
  initPoints();
  render();
</script>
