<script>
  const canvas = document.getElementById('svmCanvas');
  const ctx = canvas.getContext('2d');

  let state = {
    points: [
      {x: 0.3, y: 0.3, label: -1},
      {x: 0.7, y: 0.7, label: 1}
    ],
    C: 1.0,
    kernel: 'linear',
    gamma: 1.0,
    activeLabel: 1,
    alphas: [],
    b: 0,
    svIndices: []
  };

  function setActiveLabel(l) {
    state.activeLabel = l;
    document.getElementById('btn-red').classList.toggle('active', l === 1);
    document.getElementById('btn-blue').classList.toggle('active', l === -1);
  }

  function updateKernel() {
    state.kernel = document.getElementById('param-kernel').value;
    document.getElementById('gamma-group').style.display = state.kernel === 'rbf' ? 'flex' : 'none';
    solveAndRender();
  }

  function clearPoints() {
    state.points = [];
    solveAndRender();
  }

  // SVM Solver (Simplified SMO)
  function kernelFunc(p1, p2) {
    if (state.kernel === 'linear') {
      return p1.x * p2.x + p1.y * p2.y;
    } else {
      const distSq = Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2);
      return Math.exp(-state.gamma * distSq * 10); // Scale for visual effect
    }
  }

  function solveSVM() {
    const N = state.points.length;
    if (N < 2) {
      state.alphas = [];
      state.b = 0;
      state.svIndices = [];
      return;
    }

    let alphas = new Array(N).fill(0);
    let b = 0;
    const C = state.C;
    const tol = 0.01;
    const maxPasses = 20;
    let passes = 0;

    while (passes < maxPasses) {
      let numChangedAlphas = 0;
      for (let i = 0; i < N; i++) {
        const Ei = getDecisionValue(state.points[i], alphas, b) - state.points[i].label;
        if ((state.points[i].label * Ei < -tol && alphas[i] < C) || (state.points[i].label * Ei > tol && alphas[i] > 0)) {
          let j = Math.floor(Math.random() * (N - 1));
          if (j >= i) j++;

          const Ej = getDecisionValue(state.points[j], alphas, b) - state.points[j].label;
          const oldAi = alphas[i];
          const oldAj = alphas[j];

          let L, H;
          if (state.points[i].label !== state.points[j].label) {
            L = Math.max(0, alphas[j] - alphas[i]);
            H = Math.min(C, C + alphas[j] - alphas[i]);
          } else {
            L = Math.max(0, alphas[i] + alphas[j] - C);
            H = Math.min(C, alphas[i] + alphas[j]);
          }

          if (L === H) continue;

          const eta = 2 * kernelFunc(state.points[i], state.points[j]) - kernelFunc(state.points[i], state.points[i]) - kernelFunc(state.points[j], state.points[j]);
          if (eta >= 0) continue;

          alphas[j] -= (state.points[j].label * (Ei - Ej)) / eta;
          alphas[j] = Math.min(H, Math.max(L, alphas[j]));

          if (Math.abs(alphas[j] - oldAj) < 0.00001) continue;

          alphas[i] += state.points[i].label * state.points[j].label * (oldAj - alphas[j]);

          const b1 = b - Ei - state.points[i].label * (alphas[i] - oldAi) * kernelFunc(state.points[i], state.points[i]) - state.points[j].label * (alphas[j] - oldAj) * kernelFunc(state.points[i], state.points[j]);
          const b2 = b - Ej - state.points[i].label * (alphas[i] - oldAi) * kernelFunc(state.points[i], state.points[j]) - state.points[j].label * (alphas[j] - oldAj) * kernelFunc(state.points[j], state.points[j]);

          if (alphas[i] > 0 && alphas[i] < C) b = b1;
          else if (alphas[j] > 0 && alphas[j] < C) b = b2;
          else b = (b1 + b2) / 2;

          numChangedAlphas++;
        }
      }
      if (numChangedAlphas === 0) passes++;
      else passes = 0;
    }

    state.alphas = alphas;
    state.b = b;
    state.svIndices = alphas.map((a, idx) => a > 0.001 ? idx : -1).filter(idx => idx !== -1);
  }

  function getDecisionValue(p, alphas, b) {
    let sum = b;
    for (let i = 0; i < state.points.length; i++) {
      sum += alphas[i] * state.points[i].label * kernelFunc(p, state.points[i]);
    }
    return sum;
  }

  function render() {
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    // Draw background heatmap
    if (state.points.length >= 2) {
      const step = 8;
      for (let x = 0; x < w; x += step) {
        for (let y = 0; y < h; y += step) {
          const val = getDecisionValue({x: x / w, y: y / h}, state.alphas, state.b);
          if (Math.abs(val) < 0.1) {
             ctx.fillStyle = 'rgba(0,0,0,0.05)';
          } else {
             ctx.fillStyle = val > 0 ? 'rgba(226, 75, 74, 0.1)' : 'rgba(55, 138, 221, 0.1)';
          }
          ctx.fillRect(x, y, step, step);
        }
      }

      // Draw decision boundary and margins
      // We use a simple contouring approach by checking grid values
      ctx.lineWidth = 1.5;
      for (let x = 0; x < w; x += 4) {
        for (let y = 0; y < h; y += 4) {
          const v = getDecisionValue({x: x / w, y: y / h}, state.alphas, state.b);
          // Zero contour (Boundary)
          if (Math.abs(v) < 0.04) {
            ctx.fillStyle = 'var(--color-text-primary)';
            ctx.fillRect(x, y, 2, 2);
          }
          // Margin contours
          if (Math.abs(v - 1) < 0.04 || Math.abs(v + 1) < 0.04) {
            ctx.fillStyle = 'rgba(0,0,0,0.2)';
            ctx.fillRect(x, y, 1.5, 1.5);
          }
        }
      }
    }

    // Draw points
    state.points.forEach((p, idx) => {
      const px = p.x * w;
      const py = p.y * h;

      // Highlight support vectors
      if (state.svIndices.includes(idx)) {
        ctx.beginPath();
        ctx.arc(px, py, 10, 0, Math.PI * 2);
        ctx.strokeStyle = 'var(--color-text-primary)';
        ctx.setLineDash([2, 2]);
        ctx.stroke();
        ctx.setLineDash([]);
      }

      ctx.beginPath();
      ctx.arc(px, py, 6, 0, Math.PI * 2);
      ctx.fillStyle = p.label === 1 ? 'var(--primary-red)' : 'var(--primary-blue)';
      ctx.fill();
      ctx.strokeStyle = 'white';
      ctx.lineWidth = 2;
      ctx.stroke();
    });

    // Update stats
    document.getElementById('stat-points').textContent = state.points.length;
    document.getElementById('stat-sv').textContent = state.svIndices.length;
  }

  function solveAndRender() {
    solveSVM();
    render();
  }

  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = (e.clientY - rect.top) / rect.height;
    state.points.push({x, y, label: state.activeLabel});
    solveAndRender();
  });

  document.getElementById('param-c').addEventListener('input', (e) => {
    state.C = Math.pow(10, parseFloat(e.target.value));
    document.getElementById('c-val').textContent = state.C.toFixed(2);
    solveAndRender();
  });

  document.getElementById('param-gamma').addEventListener('input', (e) => {
    state.gamma = Math.pow(10, parseFloat(e.target.value));
    document.getElementById('gamma-val').textContent = state.gamma.toFixed(2);
    solveAndRender();
  });

  // Initial solve
  solveAndRender();

  // Handle resize
  window.addEventListener('resize', render);
</script>
