<script>
  // --- SVM Solver (Simplified SMO) ---
  class SVM {
    constructor(kernel = 'linear', C = 1.0, gamma = 1.0) {
      this.kernelType = kernel;
      this.C = C;
      this.gamma = gamma;
      this.points = [];
      this.alpha = [];
      this.b = 0;
      this.eps = 1e-3;
    }

    kernel(x1, x2) {
      if (this.kernelType === 'linear') {
        return x1.x * x2.x + x1.y * x2.y;
      } else {
        const distSq = Math.pow(x1.x - x2.x, 2) + Math.pow(x1.y - x2.y, 2);
        return Math.exp(-this.gamma * distSq);
      }
    }

    train(points, maxIter = 50) {
      this.points = points;
      const n = points.length;
      this.alpha = new Array(n).fill(0);
      this.b = 0;
      if (n < 2) return;

      let iter = 0;
      while (iter < maxIter) {
        let numChangedAlphas = 0;
        for (let i = 0; i < n; i++) {
          const Ei = this.predictScore(points[i]) - points[i].l;
          if ((points[i].l * Ei < -this.eps && this.alpha[i] < this.C) ||
              (points[i].l * Ei > this.eps && this.alpha[i] > 0)) {

            let j = Math.floor(Math.random() * (n - 1));
            if (j >= i) j++;

            const Ej = this.predictScore(points[j]) - points[j].l;
            const oldAlphaI = this.alpha[i];
            const oldAlphaJ = this.alpha[j];

            let L, H;
            if (points[i].l !== points[j].l) {
              L = Math.max(0, this.alpha[j] - this.alpha[i]);
              H = Math.min(this.C, this.C + this.alpha[j] - this.alpha[i]);
            } else {
              L = Math.max(0, this.alpha[i] + this.alpha[j] - this.C);
              H = Math.min(this.C, this.alpha[i] + this.alpha[j]);
            }

            if (L === H) continue;

            const eta = 2 * this.kernel(points[i], points[j]) - 
                        this.kernel(points[i], points[i]) - 
                        this.kernel(points[j], points[j]);
            if (eta >= 0) continue;

            this.alpha[j] -= (points[j].l * (Ei - Ej)) / eta;
            this.alpha[j] = Math.max(L, Math.min(H, this.alpha[j]));

            if (Math.abs(this.alpha[j] - oldAlphaJ) < 1e-5) continue;

            this.alpha[i] += points[i].l * points[j].l * (oldAlphaJ - this.alpha[j]);

            const b1 = this.b - Ei - points[i].l * (this.alpha[i] - oldAlphaI) * this.kernel(points[i], points[i]) -
                       points[j].l * (this.alpha[j] - oldAlphaJ) * this.kernel(points[i], points[j]);
            const b2 = this.b - Ej - points[i].l * (this.alpha[i] - oldAlphaI) * this.kernel(points[i], points[j]) -
                       points[j].l * (this.alpha[j] - oldAlphaJ) * this.kernel(points[j], points[j]);

            if (this.alpha[i] > 0 && this.alpha[i] < this.C) this.b = b1;
            else if (this.alpha[j] > 0 && this.alpha[j] < this.C) this.b = b2;
            else this.b = (b1 + b2) / 2;

            numChangedAlphas++;
          }
        }
        if (numChangedAlphas === 0) iter++;
        else iter = 0;
      }
    }

    predictScore(p) {
      let score = this.b;
      for (let i = 0; i < this.points.length; i++) {
        score += this.alpha[i] * this.points[i].l * this.kernel(this.points[i], p);
      }
      return score;
    }
  }

  // --- UI Logic ---
  const state = {
    points: [
      {x: 25, y: 25, l: -1}, {x: 35, y: 45, l: -1}, {x: 20, y: 50, l: -1},
      {x: 75, y: 75, l: 1}, {x: 65, y: 55, l: 1}, {x: 80, y: 50, l: 1}
    ],
    kernel: 'linear',
    C: 1.0,
    gamma: 0.1,
    activeClass: 1,
    draggingIdx: -1
  };

  const svg = document.getElementById('svm-svg');
  const pointsGroup = document.getElementById('points-group');
  const marginsGroup = document.getElementById('margins-group');
  const boundaryPath = document.getElementById('decision-boundary');
  const solver = new SVM();

  function updateSolver() {
    solver.kernelType = state.kernel;
    solver.C = state.C;
    solver.gamma = state.gamma;
    solver.train(state.points);
    render();
  }

  function render() {
    // Render points
    pointsGroup.innerHTML = '';
    let correct = 0;
    let svCount = 0;

    state.points.forEach((p, i) => {
      const isSV = solver.alpha[i] > 1e-4;
      if (isSV) svCount++;

      const score = solver.predictScore(p);
      if ((score >= 0 && p.l === 1) || (score < 0 && p.l === -1)) correct++;

      const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      circle.setAttribute('cx', p.x);
      circle.setAttribute('cy', p.y);
      circle.setAttribute('r', isSV ? 2.5 : 2);
      circle.setAttribute('class', `point class-${p.l} ${isSV ? 'support-vector' : ''}`);
      circle.addEventListener('mousedown', (e) => {
        e.stopPropagation();
        state.draggingIdx = i;
      });
      pointsGroup.appendChild(circle);
    });

    document.getElementById('sv-count').textContent = svCount;
    document.getElementById('accuracy').textContent = state.points.length ? Math.round((correct / state.points.length) * 100) + '%' : '0%';

    // Render Boundary and Margins
    if (state.points.length < 2) {
      boundaryPath.setAttribute('d', '');
      marginsGroup.innerHTML = '';
      return;
    }

    if (state.kernel === 'linear') {
      renderLinearBoundary();
    } else {
      renderContourBoundary();
    }
  }

  function renderLinearBoundary() {
    marginsGroup.innerHTML = '';
    const paths = generateContours(0, 1, -1);
    boundaryPath.setAttribute('d', paths[0]);

    const m1 = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    m1.setAttribute('d', paths[1]);
    m1.setAttribute('class', 'margin');
    marginsGroup.appendChild(m1);

    const m2 = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    m2.setAttribute('d', paths[2]);
    m2.setAttribute('class', 'margin');
    marginsGroup.appendChild(m2);
  }

  function renderContourBoundary() {
    marginsGroup.innerHTML = '';
    const paths = generateContours(0, 1, -1);
    boundaryPath.setAttribute('d', paths[0]);

    [paths[1], paths[2]].forEach(d => {
      const m = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      m.setAttribute('d', d);
      m.setAttribute('class', 'margin');
      marginsGroup.appendChild(m);
    });
  }

  // Marching Squares for boundary generation
  function generateContours(...thresholds) {
    const res = 40;
    const step = 100 / res;
    const grid = [];
    for (let i = 0; i <= res; i++) {
      grid[i] = [];
      for (let j = 0; j <= res; j++) {
        grid[i][j] = solver.predictScore({x: j * step, y: i * step});
      }
    }

    return thresholds.map(t => {
      let d = "";
      for (let i = 0; i < res; i++) {
        for (let j = 0; j < res; j++) {
          const v1 = grid[i][j], v2 = grid[i][j+1], v3 = grid[i+1][j+1], v4 = grid[i+1][j];
          const code = (v1 > t ? 8 : 0) | (v2 > t ? 4 : 0) | (v3 > t ? 2 : 0) | (v4 > t ? 1 : 0);

          const x = j * step, y = i * step;
          const midX = (v, v_next, start) => start + step * (t - v) / (v_next - v);

          const top = [midX(v1, v2, x), y];
          const right = [x + step, midX(v2, v3, y)];
          const bottom = [midX(v4, v3, x), y + step];
          const left = [x, midX(v1, v4, y)];

          const line = (p1, p2) => `M${p1[0].toFixed(2)},${p1[1].toFixed(2)}L${p2[0].toFixed(2)},${p2[1].toFixed(2)}`;

          switch(code) {
            case 1: case 14: d += line(left, bottom); break;
            case 2: case 13: d += line(right, bottom); break;
            case 3: case 12: d += line(left, right); break;
            case 4: case 11: d += line(top, right); break;
            case 5: d += line(top, left) + line(right, bottom); break;
            case 10: d += line(top, right) + line(left, bottom); break;
            case 6: case 9: d += line(top, bottom); break;
            case 7: case 8: d += line(top, left); break;
          }
        }
      }
      return d;
    });
  }

  // --- Event Listeners ---
  svg.addEventListener('mousedown', (e) => {
    if (state.draggingIdx !== -1) return;
    const rect = svg.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width * 100;
    const y = (e.clientY - rect.top) / rect.height * 100;
    state.points.push({x, y, l: state.activeClass});
    updateSolver();
  });

  window.addEventListener('mousemove', (e) => {
    if (state.draggingIdx === -1) return;
    const rect = svg.getBoundingClientRect();
    state.points[state.draggingIdx].x = Math.max(0, Math.min(100, (e.clientX - rect.left) / rect.width * 100));
    state.points[state.draggingIdx].y = Math.max(0, Math.min(100, (e.clientY - rect.top) / rect.height * 100));
    updateSolver();
  });

  window.addEventListener('mouseup', () => {
    state.draggingIdx = -1;
  });

  document.getElementById('kernel-type').addEventListener('change', (e) => {
    state.kernel = e.target.value;
    document.getElementById('gamma-group').style.display = state.kernel === 'rbf' ? 'flex' : 'none';
    updateSolver();
  });

  document.getElementById('c-param').addEventListener('input', (e) => {
    state.C = Math.pow(10, parseFloat(e.target.value));
    document.getElementById('c-val').textContent = state.C.toFixed(1);
    updateSolver();
  });

  document.getElementById('gamma-param').addEventListener('input', (e) => {
    state.gamma = Math.pow(10, parseFloat(e.target.value)) * 0.1;
    document.getElementById('gamma-val').textContent = state.gamma.toFixed(2);
    updateSolver();
  });

  document.getElementById('btn-class-pos').addEventListener('click', () => {
    state.activeClass = 1;
    document.getElementById('btn-class-pos').classList.add('active');
    document.getElementById('btn-class-neg').classList.remove('active');
  });

  document.getElementById('btn-class-neg').addEventListener('click', () => {
    state.activeClass = -1;
    document.getElementById('btn-class-neg').classList.add('active');
    document.getElementById('btn-class-pos').classList.remove('active');
  });

  document.getElementById('btn-clear').addEventListener('click', () => {
    state.points = [];
    updateSolver();
  });

  // Initial run
  updateSolver();
</script>
