<script>
  // --- State ---
  let points = [
    {x: 30, y: 30, label: 1},
    {x: 70, y: 70, label: -1},
    {x: 35, y: 45, label: 1},
    {x: 65, y: 55, label: -1}
  ];
  let kernelType = 'linear';
  let cParam = 1.0;
  let gamma = 1.0;
  let activeLabel = 1;
  let alphas = [];
  let b = 0;

  // --- SVM Solver (Simplified SMO) ---
  function kernel(x1, y1, x2, y2) {
    if (kernelType === 'linear') {
      return (x1 * x2 + y1 * y2) / 1000; // Scaling for stability
    } else {
      const distSq = (Math.pow(x1 - x2, 2) + Math.pow(y1 - y2, 2)) / 1000;
      return Math.exp(-gamma * distSq);
    }
  }

  function solveSVM() {
    const n = points.length;
    alphas = new Array(n).fill(0);
    b = 0;
    if (n < 2) return;

    const maxIter = 50;
    const tol = 1e-3;

    for (let iter = 0; iter < maxIter; iter++) {
      let numChangedAlphas = 0;
      for (let i = 0; i < n; i++) {
        const Ei = decisionFunction(points[i].x, points[i].y) - points[i].label;
        if ((points[i].label * Ei < -tol && alphas[i] < cParam) || (points[i].label * Ei > tol && alphas[i] > 0)) {
          let j = Math.floor(Math.random() * (n - 1));
          if (j >= i) j++;

          const Ej = decisionFunction(points[j].x, points[j].y) - points[j].label;
          const oldAi = alphas[i];
          const oldAj = alphas[j];

          let L, H;
          if (points[i].label !== points[j].label) {
            L = Math.max(0, alphas[j] - alphas[i]);
            H = Math.min(cParam, cParam + alphas[j] - alphas[i]);
          } else {
            L = Math.max(0, alphas[i] + alphas[j] - cParam);
            H = Math.min(cParam, alphas[i] + alphas[j]);
          }

          if (L === H) continue;

          const eta = 2 * kernel(points[i].x, points[i].y, points[j].x, points[j].y) - 
                      kernel(points[i].x, points[i].y, points[i].x, points[i].y) - 
                      kernel(points[j].x, points[j].y, points[j].x, points[j].y);
          if (eta >= 0) continue;

          alphas[j] -= (points[j].label * (Ei - Ej)) / eta;
          alphas[j] = Math.min(H, Math.max(L, alphas[j]));

          if (Math.abs(alphas[j] - oldAj) < 1e-5) continue;

          alphas[i] += points[i].label * points[j].label * (oldAj - alphas[j]);

          const b1 = b - Ei - points[i].label * (alphas[i] - oldAi) * kernel(points[i].x, points[i].y, points[i].x, points[i].y) - 
                     points[j].label * (alphas[j] - oldAj) * kernel(points[i].x, points[i].y, points[j].x, points[j].y);
          const b2 = b - Ej - points[i].label * (alphas[i] - oldAi) * kernel(points[i].x, points[i].y, points[j].x, points[j].y) - 
                     points[j].label * (alphas[j] - oldAj) * kernel(points[j].x, points[j].y, points[j].x, points[j].y);

          if (alphas[i] > 0 && alphas[i] < cParam) b = b1;
          else if (alphas[j] > 0 && alphas[j] < cParam) b = b2;
          else b = (b1 + b2) / 2;

          numChangedAlphas++;
        }
      }
      if (numChangedAlphas === 0) iter++; // Early exit if stable
    }
  }

  function decisionFunction(x, y) {
    let sum = b;
    for (let i = 0; i < points.length; i++) {
      sum += alphas[i] * points[i].label * kernel(points[i].x, points[i].y, x, y);
    }
    return sum;
  }

  // --- Rendering ---
  function update() {
    solveSVM();
    render();
  }

  function render() {
    const pointsLayer = document.getElementById('pointsLayer');
    const contours = document.getElementById('contours');
    pointsLayer.innerHTML = '';
    contours.innerHTML = '';

    // Draw Decision Boundary and Margins
    if (points.length >= 2) {
      const gridSize = 40;
      const step = 100 / gridSize;
      const grid = [];
      for (let i = 0; i <= gridSize; i++) {
        grid[i] = [];
        for (let j = 0; j <= gridSize; j++) {
          grid[i][j] = decisionFunction(i * step, j * step);
        }
      }

      // Draw contours for 0, 1, -1
      [0, 1, -1].forEach(level => {
        const pathData = generateContour(grid, level, step);
        if (pathData) {
          const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
          path.setAttribute('d', pathData);
          path.setAttribute('class', level === 0 ? 'boundary' : 'margin');
          contours.appendChild(path);
        }
      });
    }

    // Draw Points
    points.forEach((p, idx) => {
      const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');

      // Support vector highlight
      if (alphas[idx] > 0.01) {
        const sv = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        sv.setAttribute('cx', p.x);
        sv.setAttribute('cy', p.y);
        sv.setAttribute('r', 3.5);
        sv.setAttribute('class', 'sv-highlight');
        g.appendChild(sv);
      }

      const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      c.setAttribute('cx', p.x);
      c.setAttribute('cy', p.y);
      c.setAttribute('r', 2.5);
      c.setAttribute('fill', p.label === 1 ? 'var(--svm-red)' : 'var(--svm-blue)');
      g.appendChild(c);

      pointsLayer.appendChild(g);
    });
  }

  // Basic Marching Squares for SVG Path
  function generateContour(grid, level, step) {
    let d = "";
    for (let i = 0; i < grid.length - 1; i++) {
      for (let j = 0; j < grid[0].length - 1; j++) {
        const x = i * step;
        const y = j * step;
        const v1 = grid[i][j] - level;
        const v2 = grid[i+1][j] - level;
        const v3 = grid[i+1][j+1] - level;
        const v4 = grid[i][j+1] - level;

        let code = 0;
        if (v1 > 0) code |= 1;
        if (v2 > 0) code |= 2;
        if (v3 > 0) code |= 4;
        if (v4 > 0) code |= 8;

        const p1 = [x + step * (0 - v1) / (v2 - v1), y];
        const p2 = [x + step, y + step * (0 - v2) / (v3 - v2)];
        const p3 = [x + step * (1 - (0 - v4) / (v3 - v4)), y + step];
        const p4 = [x, y + step * (1 - (0 - v1) / (v4 - v1))];

        switch (code) {
          case 1: case 14: d += `M${p1[0]},${p1[1]} L${p4[0]},${p4[1]} `; break;
          case 2: case 13: d += `M${p1[0]},${p1[1]} L${p2[0]},${p2[1]} `; break;
          case 4: case 11: d += `M${p2[0]},${p2[1]} L${p3[0]},${p3[1]} `; break;
          case 8: case 7:  d += `M${p3[0]},${p3[1]} L${p4[0]},${p4[1]} `; break;
          case 3: case 12: d += `M${p2[0]},${p2[1]} L${p4[0]},${p4[1]} `; break;
          case 6: case 9:  d += `M${p1[0]},${p1[1]} L${p3[0]},${p3[1]} `; break;
          case 5: d += `M${p1[0]},${p1[1]} L${p4[0]},${p4[1]} M${p2[0]},${p2[1]} L${p3[0]},${p3[1]} `; break;
          case 10: d += `M${p1[0]},${p1[1]} L${p2[0]},${p2[1]} M${p3[0]},${p3[1]} L${p4[0]},${p4[1]} `; break;
        }
      }
    }
    return d;
  }

  // --- Interactions ---
  function setActiveLabel(val) {
    activeLabel = val;
    document.getElementById('btn-red').classList.toggle('active', val === 1);
    document.getElementById('btn-blue').classList.toggle('active', val === -1);
  }

  const svg = document.getElementById('svmSvg');
  svg.addEventListener('mousedown', (e) => {
    const rect = svg.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width * 100;
    const y = (e.clientY - rect.top) / rect.height * 100;
    points.push({x, y, label: activeLabel});
    update();
  });

  document.getElementById('kernelType').addEventListener('change', (e) => {
    kernelType = e.target.value;
    document.getElementById('gammaGroup').style.display = kernelType === 'rbf' ? 'flex' : 'none';
    update();
  });

  document.getElementById('cParam').addEventListener('input', (e) => {
    cParam = parseFloat(e.target.value);
    document.getElementById('cVal').textContent = cParam.toFixed(1);
    update();
  });

  document.getElementById('gammaParam').addEventListener('input', (e) => {
    gamma = parseFloat(e.target.value);
    document.getElementById('gammaVal').textContent = gamma.toFixed(1);
    update();
  });

  document.getElementById('clearBtn').addEventListener('click', () => {
    points = [];
    update();
  });

  // Initial update
  update();
</script>
