  function solveSVM() {
    if (state.points.length < 2) {
      state.w = [0, 0];
      state.b = 0;
      return;
    }

    // Simple Subgradient Descent for Primal SVM
    // Objective: min 0.5 * |w|^2 + C * sum(max(0, 1 - y(wx+b)))
