      let db = 0;

      for (const p of state.points) {
        const score = p.label * (w[0] * p.x + w[1] * p.y + b);
        if (score < 1) {
          dw[0] -= state.C * p.label * p.x;
          dw[1] -= state.C * p.label * p.y;
          db -= state.C * p.label;
        }
      }

      w[0] -= lr * dw[0];
      w[1] -= lr * dw[1];
      b -= lr * db;
    }
    state.w = w;
    state.b = b;
  }

  function update() {
    solveSVM();

    const { w, b } = state;
    const magSq = w[0]*w[0] + w[1]*w[1];
    const mag = Math.sqrt(magSq);

    const drawLine = (el, offset) => {
      if (magSq < 1e-7) {
        el.setAttribute('opacity', '0');
        return;
      }
      el.setAttribute('opacity', el === hLine ? '1' : '0.4');

      // w0*x + w1*y + b = offset  =>  y = (offset - b - w0*x) / w1
      if (Math.abs(w[1]) > Math.abs(w[0])) {
        const x1 = -1.5, x2 = 1.5;
        const y1 = (offset - b - w[0] * x1) / w[1];
        const y2 = (offset - b - w[0] * x2) / w[1];
        el.setAttribute('x1', x1); el.setAttribute('y1', -y1);
        el.setAttribute('x2', x2); el.setAttribute('y2', -y2);
      } else {
        const y1 = -1.5, y2 = 1.5;
        const x1 = (offset - b - w[1] * y1) / w[0];
        const x2 = (offset - b - w[1] * y2) / w[0];
        el.setAttribute('x1', x1); el.setAttribute('y1', -y1);
        el.setAttribute('x2', x2); el.setAttribute('y2', -y2);
      }
    };

    drawLine(hLine, 0);
    drawLine(mPosLine, 1);
    drawLine(mNegLine, -1);

    // Update Points
    pointsLayer.innerHTML = '';
    let svCount = 0;
    state.points.forEach(p => {
      const dist = p.label * (w[0] * p.x + w[1] * p.y + b);
      const isSV = dist <= 1.05;
      if (isSV) svCount++;

      const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
      circle.setAttribute('cx', p.x);
      circle.setAttribute('cy', -p.y);
      circle.setAttribute('r', isSV ? '0.06' : '0.045');
      circle.setAttribute('fill', p.label === 1 ? 'var(--primary)' : 'var(--secondary)');
      if (isSV) {
        circle.setAttribute('stroke', 'var(--text)');
        circle.setAttribute('stroke-width', '0.015');
      }
      pointsLayer.appendChild(circle);
    });

    // Stats
    statMargin.textContent = mag > 0.01 ? (2 / mag).toFixed(3) : '∞';
    statSV.textContent = state.points.length > 0 ? svCount : '0';

    let errors = 0;
    state.points.forEach(p => {
      if (p.label * (w[0] * p.x + w[1] * p.y + b) < 0) errors++;
    });
    statStatus.textContent = errors === 0 ? '完全线性可分' : `存在 ${errors} 个误分类`;
    statStatus.style.color = errors === 0 ? 'var(--color-text-success)' : 'var(--color-text-danger)';
  }

  // Interaction
  svg.addEventListener('click', (e) => {
    const rect = svg.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 2.2 - 1.1;
    const y = -(((e.clientY - rect.top) / rect.height) * 2.2 - 1.1);
    state.points.push({ x, y, label: state.activeLabel });
    update();
  });

  cSlider.addEventListener('input', (e) => {
    state.C = Math.pow(10, parseFloat(e.target.value));
    cDisplay.textContent = state.C < 1 ? state.C.toFixed(2) : Math.round(state.C);
    update();
  });

  toggleBtn.addEventListener('click', () => {
    state.activeLabel *= -1;
    indicator.style.background = state.activeLabel === 1 ? 'var(--primary)' : 'var(--secondary)';
  });

  clearBtn.addEventListener('click', () => {
    state.points = [];
    update();
  });

  // Init
  update();
})();
</script>
