<script>
  // 初始数据点
  let points = [
    {x: 0.25, y: 0.35, label: 1},
    {x: 0.30, y: 0.25, label: 1},
    {x: 0.20, y: 0.45, label: 1},
    {x: 0.70, y: 0.70, label: -1},
    {x: 0.80, y: 0.60, label: -1},
    {x: 0.75, y: 0.80, label: -1},
    {x: 0.35, y: 0.75, label: 1},
    {x: 0.65, y: 0.30, label: -1}
  ];

  let currentClass = 1;
  let kernelType = 'linear';
  let paramC = 1.0;
  let paramGamma = 1.0;
  let paramDegree = 3;

  // SVM 求解器状态
  let alpha = [];
  let b = 0;

  const canvas = document.getElementById('svmCanvas');
  const ctx = canvas.getContext('2d');

  // 绑定交互事件
  document.getElementById('btnToggleClass').addEventListener('click', () => {
    currentClass = -currentClass;
    const btn = document.getElementById('btnToggleClass');
    if (currentClass === 1) {
      btn.className = 'btn btn-active-red';
      btn.innerHTML = '<span style="display:inline-block; width:10px; height:10px; border-radius:50%; background:#E24B4A;"></span> 放置：红类 (+1)';
    } else {
      btn.className = 'btn btn-active-blue';
      btn.innerHTML = '<span style="display:inline-block; width:10px; height:10px; border-radius:50%; background:#378ADD;"></span> 放置：蓝类 (-1)';
    }
  });

  document.getElementById('btnClear').addEventListener('click', () => {
    points = [];
    update();
  });

  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = (e.clientY - rect.top) / rect.height;
    points.push({ x, y, label: currentClass });
    update();
  });

  const selectKernel = document.getElementById('selectKernel');
  const rowGamma = document.getElementById('rowGamma');
  const rowDegree = document.getElementById('rowDegree');

  selectKernel.addEventListener('change', (e) => {
    kernelType = e.target.value;
    rowGamma.style.display = kernelType === 'rbf' ? 'flex' : 'none';
    rowDegree.style.display = kernelType === 'poly' ? 'flex' : 'none';
    update();
  });

  // 滑块事件
  const rangeC = document.getElementById('rangeC');
  const valC = document.getElementById('valC');
  rangeC.addEventListener('input', (e) => {
    paramC = Math.pow(10, parseFloat(e.target.value));
    valC.textContent = paramC.toFixed(1);
    update();
  });

  const rangeGamma = document.getElementById('rangeGamma');
  const valGamma = document.getElementById('valGamma');
  rangeGamma.addEventListener('input', (e) => {
    paramGamma = Math.pow(10, parseFloat(e.target.value));
    valGamma.textContent = paramGamma.toFixed(1);
    update();
  });

  const rangeDegree = document.getElementById('rangeDegree');
  const valDegree = document.getElementById('valDegree');
  rangeDegree.addEventListener('input', (e) => {
    paramDegree = parseInt(e.target.value);
    valDegree.textContent = paramDegree;
    update();
  });

  // 核函数计算
  function kernel(p1, p2) {
    if (kernelType === 'linear') {
      return p1.x * p2.x + p1.y * p2.y;
    } else if (kernelType === 'rbf') {
      const dx = p1.x - p2.x;
      const dy = p1.y - p2.y;
      return Math.exp(-paramGamma * (dx * dx + dy * dy));
    } else if (kernelType === 'poly') {
      return Math.pow(p1.x * p2.x + p1.y * p2.y + 1, paramDegree);
    }
    return 0;
  }

  // 简化版 SMO 算法求解 SVM
  function trainSVM() {
    const N = points.length;
    alpha = new Array(N).fill(0);
    b = 0;
    if (N === 0) return;

    const maxIter = 100;
    const tol = 1e-3;

    // 预计算核矩阵
    const K = Array.from({ length: N }, () => new Float64Array(N));
    for (let i = 0; i < N; i++) {
      for (let j = 0; j < N; j++) {
        K[i][j] = kernel(points[i], points[j]);
      }
    }

    let iter = 0;
    while (iter < maxIter) {
      let numChangedAlphas = 0;
      for (let i = 0; i < N; i++) {
        // 计算预测误差 Ei
        let f_i = 0;
        for (let k = 0; k < N; k++) {
          f_i += alpha[k] * points[k].label * K[k][i];
        }
        f_i += b;
        const Ei = f_i - points[i].label;

        if ((points[i].label * Ei < -tol && alpha[i] < paramC) || 
            (points[i].label * Ei > tol && alpha[i] > 0)) {

          // 随机选择第二个变量 j
          let j = Math.floor(Math.random() * (N - 1));
          if (j >= i) j++;

          // 计算 Ej
          let f_j = 0;
          for (let k = 0; k < N; k++) {
            f_j += alpha[k] * points[k].label * K[k][j];
          }
          f_j += b;
          const Ej = f_j - points[j].label;

          const oldAlphaI = alpha[i];
          const oldAlphaJ = alpha[j];

          // 计算边界 L 和 H
          let L, H;
          if (points[i].label !== points[j].label) {
            L = Math.max(0, alpha[j] - alpha[i]);
            H = Math.min(paramC, paramC + alpha[j] - alpha[i]);
          } else {
            L = Math.max(0, alpha[i] + alpha[j] - paramC);
            H = Math.min(paramC, alpha[i] + alpha[j]);
          }

          if (Math.abs(L - H) < 1e-5) continue;

          // 计算 eta
          const eta = 2 * K[i][j] - K[i][i] - K[j][j];
          if (eta >= 0) continue;

          // 更新 alpha[j]
          let newAlphaJ = alpha[j] - (points[j].label * (Ei - Ej)) / eta;
          if (newAlphaJ > H) newAlphaJ = H;
          else if (newAlphaJ < L) newAlphaJ = L;

          if (Math.abs(newAlphaJ - alpha[j]) < 1e-5) continue;

          alpha[j] = newAlphaJ;
          // 更新 alpha[i]
          alpha[i] += points[i].label * points[j].label * (oldAlphaJ - alpha[j]);

          // 更新阈值 b
          const b1 = b - Ei - points[i].label * (alpha[i] - oldAlphaI) * K[i][i] - points[j].label * (alpha[j] - oldAlphaJ) * K[i][j];
          const b2 = b - Ej - points[i].label * (alpha[i] - oldAlphaI) * K[i][j] - points[j].label * (alpha[j] - oldAlphaJ) * K[j][j];

          if (alpha[i] > 0 && alpha[i] < paramC) b = b1;
          else if (alpha[j] > 0 && alpha[j] < paramC) b = b2;
          else b = (b1 + b2) / 2;

          numChangedAlphas++;
        }
      }
      if (numChangedAlphas === 0) iter++;
      else iter = 0;
    }
  }

  // 预测任意点的决策值
  function predict(p) {
    let val = 0;
    for (let i = 0; i < points.length; i++) {
      val += alpha[i] * points[i].label * kernel(points[i], p);
    }
    return val + b;
  }

  // 渲染主函数
  function update() {
    trainSVM();

    const width = canvas.width;
    const height = canvas.height;
    ctx.clearRect(0, 0, width, height);

    // 1. 绘制决策背景场 (60x60 细分网格插值)
    const gridSize = 6;
    for (let x = 0; x < width; x += gridSize) {
      for (let y = 0; y < height; y += gridSize) {
        const px = x / width;
        const py = y / height;
        const val = predict({ x: px, y: py });

        // 映射颜色：正值为红，负值为蓝
        let r, g, b_col, alpha_val;
        if (val > 0) {
          r = 252; g = 235; b_col = 235; // Red 50
          alpha_val = Math.min(0.8, val * 0.5);
        } else {
          r = 230; g = 241; b_col = 251; // Blue 50
          alpha_val = Math.min(0.8, -val * 0.5);
        }
        ctx.fillStyle = `rgba(${r}, ${g}, ${b_col}, ${alpha_val})`;
        ctx.fillRect(x, y, gridSize, gridSize);
      }
    }

    // 2. 绘制决策边界 (0) 和 间隔边界 (-1, +1)
    const contourSteps = 120;
    const contourGrid = [];
    for (let i = 0; i <= contourSteps; i++) {
      contourGrid[i] = [];
      for (let j = 0; j <= contourSteps; j++) {
        contourGrid[i][j] = predict({ x: i / contourSteps, y: j / contourSteps });
      }
    }

    // 简易等高线绘制
    function drawContour(targetVal, color, lineWidth, isDashed = false) {
      ctx.strokeStyle = color;
      ctx.lineWidth = lineWidth;
      if (isDashed) ctx.setLineDash([4, 4]);
      else ctx.setLineDash([]);

      ctx.beginPath();
      for (let i = 0; i < contourSteps; i++) {
        for (let j = 0; j < contourSteps; j++) {
          const x1 = (i / contourSteps) * width;
          const y1 = (j / contourSteps) * height;
          const x2 = ((i + 1) / contourSteps) * width;
          const y2 = ((j + 1) / contourSteps) * height;

          const v00 = contourGrid[i][j];
          const v10 = contourGrid[i + 1][j];
          const v01 = contourGrid[i][j + 1];

          // 水平插值
          if ((v00 >= targetVal && v10 < targetVal) || (v00 < targetVal && v10 >= targetVal)) {
            const t = (targetVal - v00) / (v10 - v00);
            ctx.moveTo(x1 + t * (width / contourSteps), y1);
            ctx.lineTo(x1 + t * (width / contourSteps), y1 + (height / contourSteps));
          }
          // 垂直插值
          if ((v00 >= targetVal && v01 < targetVal) || (v00 < targetVal && v01 >= targetVal)) {
            const t = (targetVal - v00) / (v01 - v00);
            ctx.moveTo(x1, y1 + t * (height / contourSteps));
            ctx.lineTo(x1 + (width / contourSteps), y1 + t * (height / contourSteps));
          }
        }
      }
      ctx.stroke();
    }

    if (points.length > 0) {
      drawContour(0, 'var(--color-text-primary)', 2, false); // 决策边界
      drawContour(1, '#E24B4A', 1, true); // 正间隔边界
      drawContour(-1, '#378ADD', 1, true); // 负间隔边界
    }

    // 3. 绘制数据点与支持向量
    let svCount = 0;
    points.forEach((p, idx) => {
      const cx = p.x * width;
      const cy = p.y * height;
      const isSV = alpha[idx] > 1e-4;

      if (isSV) {
        svCount++;
        // 绘制支持向量的金色光环
        ctx.beginPath();
        ctx.arc(cx, cy, 12, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(239, 159, 39, 0.3)'; // Amber 200
        ctx.strokeStyle = '#BA7517'; // Amber 400
        ctx.lineWidth = 1.5;
        ctx.fill();
        ctx.stroke();
      }

      // 绘制核心点
      ctx.beginPath();
      ctx.arc(cx, cy, 6, 0, Math.PI * 2);
      if (p.label === 1) {
        ctx.fillStyle = '#E24B4A'; // Red
        ctx.strokeStyle = '#A32D2D';
      } else {
        ctx.fillStyle = '#378ADD'; // Blue
        ctx.strokeStyle = '#185FA5';
      }
      ctx.lineWidth = 1.5;
      ctx.fill();
      ctx.stroke();
    });

    // 4. 更新指标面板
    document.getElementById('metricSV').textContent = svCount;

    // 估算几何间隔 (对于线性核，间隔 = 2 / ||w||)
    if (kernelType === 'linear' && points.length > 0) {
      let w2 = 0;
      for (let i = 0; i < points.length; i++) {
        for (let j = 0; j < points.length; j++) {
          w2 += alpha[i] * alpha[j] * points[i].label * points[j].label * kernel(points[i], points[j]);
        }
      }
      const margin = w2 > 1e-5 ? 2 / Math.sqrt(w2) : 0;
      document.getElementById('metricMargin').textContent = margin.toFixed(2);
    } else {
      document.getElementById('metricMargin').textContent = '非线性';
    }
  }

  // 首次绘制
  update();
</script>
