    <div class="table-container">
      <table class="knn-table">
        <thead>
          <tr>
            <th>状态</th>
            <th>样本 ID</th>
            <th>类别</th>
            <th>坐标 (X, Y)</th>
            <th>计算距离</th>
          </tr>
