<script>
  // 初始状态模型
  const state = {
    kValue: 5,
    distanceMetric: 'euclidean',
    points: [
      {id: 1, x: 20, y: 20, label: 'A'},
      {id: 2, x: 30, y: 45, label: 'A'},
      {id: 3, x: 15, y: 70, label: 'A'},
      {id: 4, x: 35, y: 80, label: 'A'},
      {id: 5, x: 50, y: 30, label: 'A'},
      {id: 6, x: 65, y: 85, label: 'B'},
      {id: 7, x: 80, y: 70, label: 'B'},
      {id: 8, x: 90, y: 40, label: 'B'},
      {id: 9, x: 70, y: 25, label: 'B'},
      {id: 10, x: 85, y: 15, label: 'B'}
    ],
    queryPoint: {x: 55, y: 50},
    showDecisionBoundary: true,
    addMode: null // 'A' | 'B' | null
  };

  // DOM 引用
  const svg = document.getElementById('knn-canvas');
  const svgWrapper = document.getElementById('svg-wrapper');
  const queryPointEl = document.getElementById('query-point');
  const queryPulseEl = document.getElementById('query-pulse');
  const kSlider = document.getElementById('k-slider');
  const kValDisplay = document.getElementById('k-val-display');
  const metricSelect = document.getElementById('metric-select');
  const btnAddRed = document.getElementById('btn-add-red');
  const btnAddBlue = document.getElementById('btn-add-blue');
  const btnClear = document.getElementById('btn-clear');
  const toggleBoundary = document.getElementById('toggle-boundary');
  const boundaryGrid = document.getElementById('boundary-grid');
  const distanceLinesGroup = document.getElementById('distance-lines');
  const dataPointsGroup = document.getElementById('data-points');
  const predictClassEl = document.getElementById('predict-class');
  const voteRatioEl = document.getElementById('vote-ratio');
  const voteBarRed = document.getElementById('vote-bar-red');
  const voteBarBlue = document.getElementById('vote-bar-blue');
  const tableBody = document.getElementById('distance-table-body');

  // 距离计算函数
  function calcDistance(p1, p2, metric) {
    if (metric === 'euclidean') {
      return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
    } else {
      return Math.abs(p1.x - p2.x) + Math.abs(p1.y - p2.y);
    }
  }

  // 核心更新渲染逻辑
  function update() {
    const q = state.queryPoint;
    const metric = state.distanceMetric;
    const k = Math.min(state.kValue, state.points.length);

    // 1. 计算所有点到查询点的距离并排序
    const calculated = state.points.map(p => {
      const dist = calcDistance(p, q, metric);
      return { ...p, dist };
    });
    calculated.sort((a, b) => a.dist - b.dist);

    // 标记前 K 个为邻居
    calculated.forEach((p, index) => {
      p.isNeighbor = index < k;
      p.rank = index + 1;
    });

    // 2. 统计投票
    let votesA = 0;
    let votesB = 0;
    calculated.slice(0, k).forEach(p => {
      if (p.label === 'A') votesA++;
      else votesB++;
    });

    let winner = '-';
    if (k > 0) {
      if (votesA > votesB) winner = '红色 (Class A)';
      else if (votesB > votesA) winner = '蓝色 (Class B)';
      else winner = '平局 (Tie)';
    }

    // 更新预测面板
    predictClassEl.textContent = winner;
    if (winner.includes('红色')) {
      predictClassEl.style.color = '#E24B4A';
    } else if (winner.includes('蓝色')) {
      predictClassEl.style.color = '#378ADD';
    } else {
      predictClassEl.style.color = 'var(--color-text-secondary)';
    }

    voteRatioEl.textContent = `${votesA} : ${votesB}`;
    const totalVotes = votesA + votesB || 1;
    const pctRed = (votesA / totalVotes) * 100;
    const pctBlue = (votesB / totalVotes) * 100;
    voteBarRed.style.width = `${pctRed}%`;
    voteBarBlue.style.width = `${pctBlue}%`;

    // 3. 绘制决策背景边界 (低分辨率网格插值)
    boundaryGrid.innerHTML = '';
    if (state.showDecisionBoundary && state.points.length > 0) {
      const step = 4; // 网格步长
      for (let x = 0; x <= 100; x += step) {
        for (let y = 0; y <= 100; y += step) {
          // 计算该网格点的 KNN
          const gridPoint = { x, y };
          const gridDists = state.points.map(p => ({
            label: p.label,
            dist: calcDistance(p, gridPoint, metric)
          })).sort((a, b) => a.dist - b.dist);

          let gA = 0, gB = 0;
          const localK = Math.min(k, gridDists.length);
          for (let i = 0; i < localK; i++) {
            if (gridDists[i].label === 'A') gA++;
            else gB++;
          }

          let fillCol = 'transparent';
          if (gA > gB) fillCol = 'rgba(226, 75, 74, 0.08)';
          else if (gB > gA) fillCol = 'rgba(55, 138, 221, 0.08)';

          const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          rect.setAttribute('x', x - step/2);
          rect.setAttribute('y', y - step/2);
          rect.setAttribute('width', step);
          rect.setAttribute('height', step);
          rect.setAttribute('fill', fillCol);
          boundaryGrid.appendChild(rect);
        }
      }
    }

    // 4. 绘制距离连线
    distanceLinesGroup.innerHTML = '';
    calculated.forEach(p => {
      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      line.setAttribute('x1', q.x);
      line.setAttribute('y1', q.y);
      line.setAttribute('x2', p.x);
      line.setAttribute('y2', p.y);

      if (p.isNeighbor) {
        line.setAttribute('stroke', p.label === 'A' ? '#E24B4A' : '#378ADD');
        line.setAttribute('stroke-width', '0.4');
        line.setAttribute('stroke-dasharray', 'none');
        line.setAttribute('opacity', '0.85');
      } else {
        line.setAttribute('stroke', 'var(--color-text-tertiary)');
        line.setAttribute('stroke-width', '0.15');
        line.setAttribute('stroke-dasharray', '1 1');
        line.setAttribute('opacity', '0.4');
      }
      distanceLinesGroup.appendChild(line);
    });

    // 5. 绘制样本数据点
    dataPointsGroup.innerHTML = '';
    state.points.forEach(p => {
      const isNeighbor = calculated.find(cp => cp.id === p.id)?.isNeighbor;
      const group = document.createElementNS('http://www.w3.org/2000/svg', 'g');

      // 外圈高亮环
      if (isNeighbor) {
        const ring = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        ring.setAttribute('cx', p.x);
        ring.setAttribute('cy', p.y);
        ring.setAttribute('r', '2.8');
        ring.setAttribute('fill', 'none');
        ring.setAttribute('stroke', p.label === 'A' ? '#E24B4A' : '#378ADD');
        ring.setAttribute('stroke-width', '0.4');
        group.appendChild(ring);
      }

      const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      circle.setAttribute('cx', p.x);
      circle.setAttribute('cy', p.y);
      circle.setAttribute('r', '1.8');
      circle.setAttribute('fill', p.label === 'A' ? '#E24B4A' : '#378ADD');
      circle.setAttribute('stroke', '#ffffff');
      circle.setAttribute('stroke-width', '0.3');
      circle.style.cursor = 'pointer';

      // 点击样本点可将其删除
      circle.addEventListener('click', (e) => {
        e.stopPropagation();
        state.points = state.points.filter(pt => pt.id !== p.id);
        update();
      });

      group.appendChild(circle);
      dataPointsGroup.appendChild(group);
    });

    // 6. 更新查询点位置
    queryPointEl.setAttribute('cx', q.x);
    queryPointEl.setAttribute('cy', q.y);
    queryPulseEl.setAttribute('cx', q.x);
    queryPulseEl.setAttribute('cy', q.y);

    // 7. 更新明细表格
    tableBody.innerHTML = '';
    calculated.forEach(p => {
      const tr = document.createElement('tr');
      if (p.isNeighbor) {
        tr.classList.add('is-neighbor');
      }
      tr.innerHTML = `
        <td>
          <span style="font-size: 11px; padding: 2px 6px; border-radius: 10px; font-weight: 500; 
            background: ${p.isNeighbor ? 'var(--color-background-success)' : 'var(--color-background-secondary)'};
            color: ${p.isNeighbor ? 'var(--color-text-success)' : 'var(--color-text-secondary)'};">
            ${p.isNeighbor ? `邻居 #${p.rank}` : '未入选'}
          </span>
        </td>
        <td>#${p.id}</td>
        <td>
          <span class="legend-dot ${p.label === 'A' ? 'legend-red' : 'legend-blue'}"></span>
          ${p.label === 'A' ? '红色 (A)' : '蓝色 (B)'}
        </td>
        <td>(${Math.round(p.x)}, ${Math.round(p.y)})</td>
        <td style="font-family: var(--font-mono); font-weight: 500;">${p.dist.toFixed(2)}</td>
      `;
      tableBody.appendChild(tr);
    });
  }

  // 拖拽与点击交互处理
  let isDragging = false;

  function handlePointerCoords(e) {
    const rect = svg.getBoundingClientRect();
    const clientX = e.clientX || (e.touches && e.touches[0].clientX);
    const clientY = e.clientY || (e.touches && e.touches[0].clientY);
    if (clientX === undefined || clientY === undefined) return null;

    const x = ((clientX - rect.left) / rect.width) * 100;
    const y = ((clientY - rect.top) / rect.height) * 100;
    return {
      x: Math.max(0, Math.min(100, x)),
      y: Math.max(0, Math.min(100, y))
    };
  }

  function handleInteraction(e) {
    const coords = handlePointerCoords(e);
    if (!coords) return;

    if (state.addMode) {
      // 添加新样本点模式
      const newId = state.points.length > 0 ? Math.max(...state.points.map(p => p.id)) + 1 : 1;
      state.points.push({
        id: newId,
        x: coords.x,
        y: coords.y,
        label: state.addMode
      });
      state.addMode = null;
      resetAddButtons();
      update();
    } else {
      // 移动查询点模式
      state.queryPoint = coords;
      update();
    }
  }

  // 绑定 SVG 事件
  svg.addEventListener('mousedown', (e) => {
    if (state.addMode) {
      handleInteraction(e);
    } else {
      isDragging = true;
      handleInteraction(e);
    }
  });

  window.addEventListener('mousemove', (e) => {
    if (isDragging) {
      handleInteraction(e);
    }
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
  });

  // 移动端触摸支持
  svg.addEventListener('touchstart', (e) => {
    if (state.addMode) {
      handleInteraction(e);
    } else {
      isDragging = true;
      handleInteraction(e);
    }
  }, { passive: true });

  window.addEventListener('touchmove', (e) => {
    if (isDragging) {
      handleInteraction(e);
    }
  }, { passive: true });

  window.addEventListener('touchend', () => {
    isDragging = false;
  });

  // 控制控件事件绑定
  kSlider.addEventListener('input', (e) => {
    state.kValue = parseInt(e.target.value);
    kValDisplay.textContent = state.kValue;
    update();
  });

  metricSelect.addEventListener('change', (e) => {
    state.distanceMetric = e.target.value;
    update();
  });

  toggleBoundary.addEventListener('change', (e) => {
    state.showDecisionBoundary = e.target.checked;
    update();
  });

  function resetAddButtons() {
    btnAddRed.className = '';
    btnAddBlue.className = '';
  }

  btnAddRed.addEventListener('click', () => {
    if (state.addMode === 'A') {
      state.addMode = null;
      resetAddButtons();
    } else {
      state.addMode = 'A';
      resetAddButtons();
      btnAddRed.className = 'btn-active-red';
    }
  });

  btnAddBlue.addEventListener('click', () => {
    if (state.addMode === 'B') {
      state.addMode = null;
      resetAddButtons();
    } else {
      state.addMode = 'B';
      resetAddButtons();
      btnAddBlue.className = 'btn-active-blue';
    }
  });

  btnClear.addEventListener('click', () => {
    state.points = [];
    state.addMode = null;
    resetAddButtons();
    update();
  });

  // 首次绘制
  update();
</script>
