<script>
  // State Model
  let state = {
    points: [
      {x: 0.25, y: 0.35, label: 1},
      {x: 0.3, y: 0.25, label: 1},
      {x: 0.2, y: 0.45, label: 1},
      {x: 0.75, y: 0.65, label: -1},
      {x: 0.8, y: 0.55, label: -1},
      {x: 0.7, y: 0.75, label: -1},
      {x: 0.35, y: 0.75, label: 1},
      {x: 0.65, y: 0.25, label: -1}
    ],
    currentLabel: 1,
    kernelType: 'rbf',
    paramC: 10.0,
    paramGamma: 1.0,
    paramDegree: 3
  };

  // SVM Solver State
  let alphas = [];
  let b = 0;

  const canvas = document.getElementById('svmCanvas');
  const ctx = canvas.getContext('2d');

  function setClass(label) {
    state.currentLabel = label;
    document.getElementById('btn-class-red').classList.toggle('active-red', label === 1);
    document.getElementById('btn-class-blue').classList.toggle('active-blue', label === -1);
  }

  function updateKernel() {
    state.kernelType = document.getElementById('kernel-select').value;

    // Toggle UI sliders
    document.getElementById('group-gamma').classList.toggle('disabled-control', state.kernelType !== 'rbf');
    document.getElementById('group-degree').classList.toggle('disabled-control', state.kernelType !== 'poly');

    trainAndRender();
  }

  function updateParam(name, val) {
    const numVal = parseFloat(val);
    if (name === 'C') {
      state.paramC = numVal;
      document.getElementById('val-c').textContent = numVal.toFixed(1);
    } else if (name === 'Gamma') {
      state.paramGamma = numVal;
      document.getElementById('val-gamma').textContent = numVal.toFixed(1);
    } else if (name === 'Degree') {
      state.paramDegree = Math.round(numVal);
      document.getElementById('val-degree').textContent = Math.round(numVal);
    }
    trainAndRender();
  }

  function clearPoints() {
    state.points = [];
    trainAndRender();
  }

  function loadPreset(type) {
    if (type === 'separable') {
      state.points = [
        {x: 0.2, y: 0.2, label: 1},
        {x: 0.3, y: 0.15, label: 1},
        {x: 0.15, y: 0.35, label: 1},
        {x: 0.35, y: 0.3, label: 1},
        {x: 0.75, y: 0.75, label: -1},
        {x: 0.8, y: 0.65, label: -1},
        {x: 0.65, y: 0.8, label: -1},
        {x: 0.85, y: 0.85, label: -1}
      ];
      state.kernelType = 'linear';
      document.getElementById('kernel-select').value = 'linear';
    } else {
      state.points = [
        {x: 0.5, y: 0.5, label: 1},
        {x: 0.48, y: 0.42, label: 1},
        {x: 0.55, y: 0.48, label: 1},
        {x: 0.45, y: 0.55, label: 1},
        {x: 0.2, y: 0.5, label: -1},
        {x: 0.5, y: 0.2, label: -1},
        {x: 0.8, y: 0.5, label: -1},
        {x: 0.5, y: 0.8, label: -1},
        {x: 0.3, y: 0.3, label: -1},
        {x: 0.7, y: 0.7, label: -1},
        {x: 0.3, y: 0.7, label: -1},
        {x: 0.7, y: 0.3, label: -1}
      ];
      state.kernelType = 'rbf';
      document.getElementById('kernel-select').value = 'rbf';
    }
    updateKernel();
  }

  // Kernel Functions
  function kernel(p1, p2) {
    if (state.kernelType === 'linear') {
      return p1.x * p2.x + p1.y * p2.y;
    } else if (state.kernelType === 'rbf') {
      const dx = p1.x - p2.x;
      const dy = p1.y - p2.y;
      return Math.exp(-state.paramGamma * (dx * dx + dy * dy));
    } else if (state.kernelType === 'poly') {
      return Math.pow(p1.x * p2.x + p1.y * p2.y + 1, state.paramDegree);
    }
    return 0;
  }

  // Simplified SMO (Sequential Minimal Optimization) Algorithm
  function trainSVM() {
    const N = state.points.length;
    alphas = new Array(N).fill(0);
    b = 0;
    if (N === 0) return;

    const C = state.paramC;
    const tol = 0.01;
    const maxPasses = 20;
    let passes = 0;

    // Precompute kernel matrix
    const K = Array.from({ length: N }, () => new Float64Array(N));
    for (let i = 0; i < N; i++) {
      for (let j = 0; j < N; j++) {
        K[i][j] = kernel(state.points[i], state.points[j]);
      }
    }

    while (passes < maxPasses) {
      let numChangedAlphas = 0;
      for (let i = 0; i < N; i++) {
        // Calculate Ei
        let f_i = 0;
        for (let k = 0; k < N; k++) {
          f_i += alphas[k] * state.points[k].label * K[k][i];
        }
        f_i += b;
        const E_i = f_i - state.points[i].label;

        if ((state.points[i].label * E_i < -tol && alphas[i] < C) || 
            (state.points[i].label * E_i > tol && alphas[i] > 0)) {

          // Select j != i randomly
          let j = Math.floor(Math.random() * (N - 1));
          if (j >= i) j++;

          // Calculate Ej
          let f_j = 0;
          for (let k = 0; k < N; k++) {
            f_j += alphas[k] * state.points[k].label * K[k][j];
          }
          f_j += b;
          const E_j = f_j - state.points[j].label;

          const oldAlphaI = alphas[i];
          const oldAlphaJ = alphas[j];

          // Compute L and H
          let L, H;
          if (state.points[i].label !== state.points[j].label) {
            L = Math.max(0, alphas[j] - alphas[i]);
            H = Math.min(C, C + alphas[j] - alphas[i]);
          } else {
            L = Math.max(0, alphas[i] + alphas[j] - C);
            H = Math.min(C, alphas[i] + alphas[j]);
          }

          if (Math.abs(L - H) < 1e-5) continue;

          // Compute eta
          const eta = 2 * K[i][j] - K[i][i] - K[j][j];
          if (eta >= 0) continue;

          // Clip new alpha_j
          let newAlphaJ = alphas[j] - (state.points[j].label * (E_i - E_j)) / eta;
          if (newAlphaJ > H) newAlphaJ = H;
          else if (newAlphaJ < L) newAlphaJ = L;

          if (Math.abs(newAlphaJ - alphas[j]) < 1e-5) continue;

          alphas[j] = newAlphaJ;
          // Compute new alpha_i
          alphas[i] += state.points[i].label * state.points[j].label * (oldAlphaJ - alphas[j]);

          // Compute b
          const b1 = b - E_i - state.points[i].label * (alphas[i] - oldAlphaI) * K[i][i] - state.points[j].label * (alphas[j] - oldAlphaJ) * K[i][j];
          const b2 = b - E_j - state.points[i].label * (alphas[i] - oldAlphaI) * K[i][j] - state.points[j].label * (alphas[j] - oldAlphaJ) * K[j][j];

          if (alphas[i] > 0 && alphas[i] < C) b = b1;
          else if (alphas[j] > 0 && alphas[j] < C) b = b2;
          else b = (b1 + b2) / 2;

          numChangedAlphas++;
        }
      }
      if (numChangedAlphas === 0) passes++;
      else passes = 0;
    }
  }

  // Evaluate decision function at a custom point
  function evaluate(p) {
    let val = 0;
    for (let i = 0; i < state.points.length; i++) {
      val += alphas[i] * state.points[i].label * kernel(state.points[i], p);
    }
    return val + b;
  }

  function trainAndRender() {
    trainSVM();
    draw();
  }

  function draw() {
    const width = canvas.width;
    const height = canvas.height;
    ctx.clearRect(0, 0, width, height);

    if (state.points.length === 0) {
      ctx.fillStyle = 'var(--color-text-tertiary)';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('点击画布添加数据点', width / 2, height / 2);
      return;
    }

    // 1. Draw Decision Boundary & Margin Gradients (Dense Grid)
    const gridSize = 4; // Step size for rendering speed
    const imgData = ctx.createImageData(width, height);

    for (let y = 0; y < height; y += gridSize) {
      for (let x = 0; x < width; x += gridSize) {
        const p = { x: x / width, y: y / height };
        const val = evaluate(p);

        // Map decision value to color intensity
        // Red (+1) vs Blue (-1)
        let r = 255, g = 255, b_col = 255, alpha = 0;

        if (val > 0) {
          // Red side
          r = 226; g = 75; b_col = 74;
          alpha = Math.min(180, val * 80); // Scale opacity with confidence
        } else {
          // Blue side
          r = 55; g = 138; b_col = 221;
          alpha = Math.min(180, -val * 80);
        }

        // Fill grid block
        for (let dy = 0; dy < gridSize; dy++) {
          for (let dx = 0; dx < gridSize; dx++) {
            if (x + dx < width && y + dy < height) {
              const idx = ((y + dy) * width + (x + dx)) * 4;
              imgData.data[idx] = r;
              imgData.data[idx + 1] = g;
              imgData.data[idx + 2] = b_col;
              imgData.data[idx + 3] = alpha;
            }
          }
        }
      }
    }
    ctx.putImageData(imgData, 0, 0);

    // 2. Draw Contour Lines (Decision Boundary & Margins)
    // We sample a slightly denser grid to trace clean contour lines
    const contourGrid = 100;
    const gridValues = Array.from({ length: contourGrid + 1 }, () => new Float64Array(contourGrid + 1));
    for (let i = 0; i <= contourGrid; i++) {
      for (let j = 0; j <= contourGrid; j++) {
        gridValues[i][j] = evaluate({ x: i / contourGrid, y: j / contourGrid });
      }
    }

    // Helper to draw contour lines analytically/by approximation
    function drawContour(targetVal, strokeStyle, lineWidth, isDashed) {
      ctx.strokeStyle = strokeStyle;
      ctx.lineWidth = lineWidth;
      if (isDashed) ctx.setLineDash([4, 4]);
      else ctx.setLineDash([]);
      ctx.beginPath();

      for (let i = 0; i < contourGrid; i++) {
        for (let j = 0; j < contourGrid; j++) {
          const x1 = (i / contourGrid) * width;
          const y1 = (j / contourGrid) * height;
          const x2 = ((i + 1) / contourGrid) * width;
          const y2 = ((j + 1) / contourGrid) * height;

          const v00 = gridValues[i][j];
          const v10 = gridValues[i+1][j];
          const v01 = gridValues[i][j+1];
          const v11 = gridValues[i+1][j+1];

          // Check horizontal edges
          if ((v00 >= targetVal && v10 < targetVal) || (v00 < targetVal && v10 >= targetVal)) {
            const t = (targetVal - v00) / (v10 - v00);
            ctx.moveTo(x1 + t * (x2 - x1), y1);
            ctx.lineTo(x1 + t * (x2 - x1), y1); // Small segment
          }
          // Check vertical edges
          if ((v00 >= v01 && v00 < targetVal && v01 >= targetVal) || (v00 >= targetVal && v01 < targetVal)) {
            const t = (targetVal - v00) / (v01 - v00);
            ctx.moveTo(x1, y1 + t * (y2 - y1));
            ctx.lineTo(x1, y1 + t * (y2 - y1));
          }
        }
      }
      ctx.stroke();
    }

    // Draw decision boundary (val = 0)
    drawContour(0, 'var(--color-text-primary)', 2, false);
    // Draw margins (val = 1 and val = -1)
    drawContour(1, 'var(--color-text-secondary)', 1, true);
    drawContour(-1, 'var(--color-text-secondary)', 1, true);
    ctx.setLineDash([]); // Reset

    // 3. Draw Data Points & Highlight Support Vectors
    state.points.forEach((p, idx) => {
      const px = p.x * width;
      const py = p.y * height;
      const isSupportVector = alphas[idx] > 1e-4;

      if (isSupportVector) {
        // Outer ring for support vectors
        ctx.beginPath();
        ctx.arc(px, py, 11, 0, Math.PI * 2);
        ctx.strokeStyle = 'var(--color-text-primary)';
        ctx.lineWidth = 2;
        ctx.stroke();
      }

      // Inner point
      ctx.beginPath();
      ctx.arc(px, py, 7, 0, Math.PI * 2);
      if (p.label === 1) {
        ctx.fillStyle = '#e24b4a'; // Red
      } else {
        ctx.fillStyle = '#378add'; // Blue
      }
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1.5;
      ctx.stroke();
    });
  }

  // Canvas Click Event to Add Points
  canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = (e.clientY - rect.top) / rect.height;

    // Prevent adding points outside bounds
    if (x >= 0 && x <= 1 && y >= 0 && y <= 1) {
      state.points.push({ x, y, label: state.currentLabel });
      trainAndRender();
    }
  });

  // Initial Paint
  trainAndRender();
</script>
