                  stroke="${isSelected ? 'var(--color-text-info)' : 'var(--color-border-secondary)'}" stroke-width="1"/>
            <text class="ts" x="47" y="${39 + idx * 40}" text-anchor="middle" dominant-baseline="central" 
                  fill="${isSelected ? 'var(--color-text-info)' : 'var(--color-text-primary)'}" font-weight="${isSelected ? 'bold' : 'normal'}">${word}</text>
          </g>
        `;
      });

      // 绘制右侧 Key 词
      words.forEach((word, idx) => {
        matrixHtml += `
          <g>
            <rect x="240" y="${25 + idx * 40}" width="65" height="28" rx="4" 
                  fill="var(--color-background-secondary)" stroke="var(--color-border-secondary)" stroke-width="0.5"/>
            <text class="ts" x="272" y="${39 + idx * 40}" text-anchor="middle" dominant-baseline="central" fill="var(--color-text-primary)">${word}</text>
          </g>
        `;
      });

      matrixHtml += `
        <text class="ts" x="160" y="205" text-anchor="middle" fill="var(--color-text-secondary)">点击左侧单词切换查询词 (Query)</text>
      </svg>`;
      container.innerHTML = matrixHtml;

    } else if (comp === 'embedding') {
      container.innerHTML = `
