      title: '输入嵌入 (Input Embedding)',
      category: '特征表示',
      body: '将离散的 Token ID 转换为高维连续稠密向量（通常为 512 维）。相似语义的词在向量空间中距离更近。例如，"student" 和 "teacher" 的向量会具有较高的余弦相似度。'
    },
    'pos-enc': {
      title: '位置编码 (Positional Encoding)',
      category: '特征表示',
      body: '由于 Transformer 摒弃了循环结构，无法感知序列顺序。因此，必须引入位置编码。通过正弦和余弦函数的组合，为每个位置生成一个独特的向量，并与词嵌入向量直接相加，使模型能够识别词语的先后顺序。'
    },
    'self-attn': {
      title: '多头自注意力机制 (Multi-Head Self-Attention)',
      category: '编码器核心',
      body: '允许模型在处理一个词时，同时关注句子中其他词的信息。通过计算 Query (Q)、Key (K) 和 Value (V) 的内积来分配权重。多头机制（Multi-Head）允许模型在不同的子空间中并行学习多种语义关联（例如，一个头关注主谓关系，另一个头关注代词指代）。'
    },
    'ffn-enc': {
      title: '前馈神经网络 (Feed-Forward Network)',
      category: '特征转换',
      body: '在注意力机制之后，每个位置的向量会独立通过一个相同的两层全连接神经网络（通常包含 ReLU 激活函数）。它负责对注意力机制提取的特征进行非线性变换和整合。'
    },
    'output-in': {
      title: '输出目标 (Outputs / Shifted Right)',
      category: '数据输入',
      body: '在训练阶段，解码器接收的是目标句子（"我是学生"）向右平移一位后的序列（即以 &lt;bos&gt; 开始标记开头）。在推理阶段，解码器是自回归的，每次将上一步预测出的词作为输入。'
    },
    'out-embed': {
      title: '输出嵌入 (Output Embedding)',
      category: '特征表示',
      body: '与输入嵌入类似，将目标语言（中文）的 Token 转换为高维稠密向量，为解码器提供初始的语义表示。'
    },
    'pos-dec': {
      title: '位置编码 (Decoder Positional Encoding)',
      category: '特征表示',
      body: '为解码器端的中文 Token 序列注入位置信息，确保模型知道“我”、“是”、“学生”在目标句子中的相对位置。'
    },
    'masked-attn': {
      title: '掩码多头自注意力 (Masked Self-Attention)',
      category: '解码器核心',
      body: '在解码时，为了防止模型“偷看”未来的词，引入了掩码（Masking）。在计算注意力权重时，将当前位置之后的词的权重设为极小值（-inf），从而在 Softmax 后变为 0。这确保了预测第 N 个词时，只能使用前 N-1 个词的信息。'
    },
    'cross-attn': {
      title: '交叉注意力机制 (Encoder-Decoder Attention)',
      category: '解码器核心',
      body: '连接编码器与解码器的桥梁。解码器生成 Query (Q)，而 Key (K) 和 Value (V) 来自编码器的最终输出。这使得解码器在翻译每个中文词时，能够精准地“对齐”并关注英文输入源句中的相关单词。'
    },
    'ffn-dec': {
      title: '前馈神经网络 (Decoder FFN)',
      category: '特征转换',
      body: '对交叉注意力层输出的特征进行进一步的非线性映射，为最终的类别预测做准备。'
    },
    'linear': {
      title: '线性层与 Softmax (Linear & Softmax)',
      category: '输出预测',
      body: '线性层将解码器输出的向量投影到一个极大的向量中（维度等于目标语言词表大小）。随后，Softmax 函数将这些投影值转换为概率分布，概率最大的词即为当前步骤的预测输出。'
    },
    'final-out': {
      title: '预测输出概率 (Output Probabilities)',
      category: '输出预测',
      body: '输出当前步骤预测的词。例如，在第一步，模型以高概率输出“我”；接着将“我”作为下一步的输入，继续预测“是”，直至输出结束符 &lt;eos&gt;。'
    }
  };

  let activeNodeId = null;
  let demoInterval = null;
  let demoStep = 0;
  let isPlaying = false;

  // 选择节点并更新右侧卡片
  function selectNode(nodeId) {
    if (activeNodeId) {
      const prevNode = document.getElementById(`node-${activeNodeId}`);
      if (prevNode) prevNode.classList.remove('active');
    }

    activeNodeId = nodeId;
    const currNode = document.getElementById(`node-${nodeId}`);
    if (currNode) currNode.classList.add('active');

    const detail = nodeDetails[nodeId];
    if (detail) {
      document.getElementById('info-title').innerHTML = `<span>${detail.title}</span>`;
      document.getElementById('info-body').innerHTML = detail.body;
      document.getElementById('info-category').innerText = `分类: ${detail.category}`;
    }
  }

  // 演示步骤定义
  const demoSteps = [
    {
      nodes: ['input', 'in-embed', 'pos-enc'],
      status: '【步骤 1/5 - 输入处理】源句子 "I am a student" 转化为 Token，通过 Embedding 转换为向量，并与位置编码相加。',
      path: 'M 110 510 L 110 380',
      indicator: 0
    },
    {
      nodes: ['self-attn', 'ffn-enc'],
      status: '【步骤 2/5 - 编码器表征】自注意力机制计算单词间的相互关系（如 "I" 与 "student" 的关联），FFN 进行特征转换，生成上下文向量。',
      path: 'M 110 380 L 110 215',
      indicator: 1
    },
    {
      nodes: ['output-in', 'out-embed', 'pos-dec', 'masked-attn'],
      status: '【步骤 3/5 - 解码器自注意力】解码器接收已生成的中文序列（如 "&lt;bos&gt; 我"），通过掩码自注意力防止预测时偷看未来的词。',
      path: 'M 310 510 L 310 350',
      indicator: 2
    },
    {
      nodes: ['cross-attn'],
      status: '【步骤 4/5 - 交叉注意力对齐】解码器通过交叉注意力机制，将当前的中文状态与编码器输出的英文特征进行对齐（如将“我”与“I”对齐）。',
      path: 'M 110 215 L 220 215 L 220 295 L 270 295',
      indicator: 3
    },
    {
      nodes: ['ffn-dec', 'linear', 'final-out'],
      status: '【步骤 5/5 - 预测输出】经过 FFN 转换，线性层与 Softmax 计算词表概率，预测出下一个词：“是”。整个过程自回归循环，直至翻译完成。',
      path: 'M 310 280 L 310 55',
      indicator: 4
    }
  ];

  function runDemoStep() {
    // 清除所有高亮
    document.querySelectorAll('.interactive-node').forEach(n => n.classList.remove('active'));
    document.querySelectorAll('#step-indicator span').forEach(s => s.classList.remove('active'));

    const step = demoSteps[demoStep];

    // 高亮当前步骤的节点
    step.nodes.forEach(nodeId => {
      const node = document.getElementById(`node-${nodeId}`);
      if (node) node.classList.add('active');
    });

    // 激活右侧第一个节点作为详情展示
    selectNode(step.nodes[0]);

    // 更新状态文字
    document.getElementById('demo-status').innerHTML = step.status;

    // 更新步骤指示器
    document.getElementById(`ind-${step.indicator}`).classList.add('active');

    // 绘制动态流线
    const flowPath = document.getElementById('flow-path');
    flowPath.setAttribute('d', step.path);
    flowPath.style.display = 'block';

    // 递增步骤
    demoStep = (demoStep + 1) % demoSteps.length;
  }

  function toggleDemo() {
    const btn = document.getElementById('btn-play');
    if (isPlaying) {
      clearInterval(demoInterval);
      btn.innerText = '继续演示';
      isPlaying = false;
    } else {
      btn.innerText = '暂停演示';
      isPlaying = true;
      runDemoStep();
      demoInterval = setInterval(runDemoStep, 4000);
    }
  }

  function resetDemo() {
    clearInterval(demoInterval);
    isPlaying = false;
    demoStep = 0;
    document.getElementById('btn-play').innerText = '开始演示';
    document.getElementById('demo-status').innerText = '点击下方“开始演示”观察数据如何在 Transformer 中流动。';
    document.getElementById('flow-path').style.display = 'none';
    document.querySelectorAll('.interactive-node').forEach(n => n.classList.remove('active'));
    document.querySelectorAll('#step-indicator span').forEach(s => s.classList.remove('active'));
    document.getElementById('ind-0').classList.add('active');
    selectNode('input');
  }

  function askClaude() {
    const currentTitle = activeNodeId ? nodeDetails[activeNodeId].title : "Transformer 架构";
    sendPrompt(`请详细解释一下 Transformer 架构中的 ${currentTitle}，它是如何工作的？`);
  }
</script>
