<style>
  :root {
    --primary-color: var(--color-text-info, #2563eb);
    --bg-card: var(--color-background-secondary, #f8fafc);
    --border-color: var(--color-border-tertiary, rgba(0,0,0,0.1));
    --text-main: var(--color-text-primary, #0f172a);
    --text-muted: var(--color-text-secondary, #475569);
  }

  .pa-container {
    font-family: var(--font-sans), system-ui, -apple-system, sans-serif;
    color: var(--text-main);
    padding: 1rem 0;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
    width: 100%;
    box-sizing: border-box;
  }

  /* Header Controls */
  .pa-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    border-bottom: 1px solid var(--border-color);
    padding-bottom: 1rem;
  }
  .pa-title-area h2 {
    margin: 0;
    font-size: 1.25rem;
    font-weight: 500;
  }
  .pa-title-area p {
    margin: 0.25rem 0 0 0;
    font-size: 0.85rem;
    color: var(--text-muted);
  }
  .btn-toggle {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    color: var(--text-main);
    padding: 0.5rem 1rem;
    border-radius: var(--border-radius-md);
    cursor: pointer;
    font-size: 0.85rem;
    font-weight: 500;
    transition: all 0.2s ease;
  }
  .btn-toggle:hover {
    border-color: var(--color-text-info);
    color: var(--color-text-info);
  }

  /* Main Layout Split */
  .pa-layout {
    display: grid;
    grid-template-columns: 1.4fr 1fr;
    gap: 1.5rem;
  }
  @media (max-width: 768px) {
    .pa-layout {
      grid-template-columns: 1fr;
    }
  }

  /* Left Panel: SVG Tree & Timeline */
  .pa-visual-panel {
    background: var(--bg-card);
    border-radius: var(--border-radius-lg);
    border: 1px solid var(--border-color);
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }

  /* Right Panel: Dynamic Details */
  .pa-detail-panel {
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }

  /* Detail Card Style */
  .detail-card {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: var(--border-radius-lg);
    padding: 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
    transition: all 0.3s ease;
  }
  .detail-card-header {
    border-bottom: 1px solid var(--border-color);
    padding-bottom: 0.75rem;
  }
  .stage-badge {
    display: inline-block;
    padding: 0.25rem 0.5rem;
    font-size: 0.75rem;
    border-radius: 4px;
    font-weight: 500;
    margin-bottom: 0.5rem;
  }
  .badge-0 { background: rgba(37,99,235,0.1); color: #2563eb; }
  .badge-1 { background: rgba(13,148,136,0.1); color: #0d9488; }
  .badge-2 { background: rgba(217,119,6,0.1); color: #d97706; }
  .badge-3 { background: rgba(147,51,234,0.1); color: #9333ea; }

  .detail-title {
    font-size: 1.1rem;
    font-weight: 500;
    margin: 0;
  }
  .detail-desc {
    font-size: 0.875rem;
    line-height: 1.6;
    color: var(--text-muted);
    margin: 0;
  }

  /* Theorist Info Grid */
  .theorist-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
    gap: 0.75rem;
  }
  .theorist-card {
    background: var(--color-background-primary, #ffffff);
    border: 1px solid var(--border-color);
    border-radius: var(--border-radius-md);
    padding: 0.75rem;
    cursor: pointer;
    transition: all 0.2s ease;
  }
  .theorist-card.active {
    border-color: var(--primary-color);
    box-shadow: 0 0 0 2px rgba(37,99,235,0.15);
  }
  .theorist-name {
    font-size: 0.85rem;
    font-weight: 500;
    margin: 0 0 0.25rem 0;
  }
  .theorist-concept {
    font-size: 0.75rem;
    color: var(--text-muted);
    margin: 0;
  }

  /* Comparison Matrix */
  .compare-matrix {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.8rem;
    background: var(--bg-card);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    border: 1px solid var(--border-color);
  }
  .compare-matrix th, .compare-matrix td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid var(--border-color);
    border-right: 1px solid var(--border-color);
  }
  .compare-matrix th {
    background: rgba(0,0,0,0.02);
    font-weight: 500;
  }
  .compare-matrix tr:last-child td {
    border-bottom: none;
  }
  .compare-matrix td:last-child, .compare-matrix th:last-child {
    border-right: none;
  }

  /* SVG Interactive Elements */
  .node-interactive {
    cursor: pointer;
    transition: transform 0.2s ease, opacity 0.2s ease;
  }
  .node-interactive:hover {
    opacity: 0.9;
  }
  .timeline-step {
    cursor: pointer;
  }
  .timeline-step:hover rect {
    fill: var(--color-border-secondary);
  }
  .active-indicator {
    transition: all 0.3s ease;
  }
</style>

