            </div>
          ` : ''}
        </div>
      `;
    }
  }

  // Interaction Handlers
  window.selectStage = function(index) {
    state.activeStage = index;
    // Auto-highlight first theorist of the selected stage
    if (stagesData[index].theorists.length > 0) {
      state.highlightNode = stagesData[index].theorists[0].id;
    }
    update();
  };

  window.selectTheorist = function(id) {
    state.highlightNode = id;
    // Auto-switch stage if theorist belongs to another stage
    stagesData.forEach((stage, index) => {
      if (stage.theorists.some(t => t.id === id)) {
        state.activeStage = index;
      }
    });
    update();
  };

  document.getElementById('toggle-compare').addEventListener('click', () => {
    state.compareMode = !state.compareMode;
    update();
  });

  // Initial Paint
  update();
</script>

