  let currentStageId = "traditional";

  function renderTimeline() {
    const nav = document.getElementById("timelineNav");
    nav.innerHTML = stagesData.map(stage => `
      <div class="timeline-node ${stage.id === currentStageId ? 'active' : ''}" onclick="selectStage('${stage.id}')">
        <div class="node-period" style="color: ${stage.color}">${stage.period}</div>
        <div class="node-title">${stage.title}</div>
      </div>
    `).join('');
  }

  function renderStagePanel() {
    const stage = stagesData.find(s => s.id === currentStageId);
    const panel = document.getElementById("stagePanel");

    panel.innerHTML = `
      <div class="stage-header">
        <div class="stage-meta">
          <span class="stage-badge ${stage.themeClass}">${stage.badge}</span>
          <h2 style="font-size: 18px; font-weight: 500; margin: 6px 0 0 0;">${stage.title} (${stage.period})</h2>
        </div>
      </div>
      <p style="font-size: 14px; line-height: 1.6; margin: 0; color: var(--color-text-secondary);">${stage.desc}</p>
      <div>
        <h3 style="font-size: 14px; font-weight: 500; margin: 0 0 10px 0; color: var(--color-text-primary);">代表学者与核心观点</h3>
        <div class="theorist-grid">
          ${stage.theorists.map(t => `
            <div class="theorist-card">
