  function drawTree() {
    const svg = document.getElementById("evolutionTree");
    const isDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
    const strokeColor = isDark ? "rgba(255,255,255,0.15)" : "rgba(0,0,0,0.1)";
    const activeStrokeColor = "var(--color-border-info)";

    // 节点坐标定义
    const nodes = [
      { id: "traditional", cx: 150, cy: 220, label: "传统公共行政", period: "1880s-1970s", color: "#378add" },
      { id: "npm", cx: 150, cy: 140, label: "新公共管理 (NPM)", period: "1980s-1990s", color: "#ba7517" },
      { id: "npg", cx: 450, cy: 140, label: "新公共治理 (NPG)", period: "2000s-2010s", color: "#1d9e75" },
      { id: "digital", cx: 300, cy: 50, label: "数字与智慧治理", period: "2010s-至今", color: "#7f77dd" }
    ];

    // 连线定义
    const links = [
      { from: "traditional", to: "npm", type: "efficiency" },
      { from: "traditional", to: "npg", type: "democracy" },
      { from: "npm", to: "digital", type: "tech" },
      { from: "npg", to: "digital", type: "tech" }
    ];

    let html = "";

    // 绘制连线
    links.forEach(link => {
      const fromNode = nodes.find(n => n.id === link.from);
      const toNode = nodes.find(n => n.id === link.to);
      const isActive = currentStageId === link.from || currentStageId === link.to;

      // 贝塞尔曲线连接
      const dx = toNode.cx - fromNode.cx;
      const dy = toNode.cy - fromNode.cy;
      const pathData = `M ${fromNode.cx} ${fromNode.cy} C ${fromNode.cx} ${fromNode.cy - dy/2}, ${toNode.cx} ${toNode.cy + dy/2}, ${toNode.cx} ${toNode.cy}`;

      html += `
        <path d="${pathData}" 
              fill="none" 
              stroke="${isActive ? activeStrokeColor : strokeColor}" 
              stroke-width="${isActive ? '2' : '1.5'}" 
              stroke-dasharray="${link.type === 'democracy' ? '4,4' : 'none'}" />
      `;
    });

    // 绘制节点
    nodes.forEach(node => {
      const isActive = node.id === currentStageId;
      const textColor = isDark ? "#ffffff" : "#111111";
      const subTextColor = isDark ? "#aaaaaa" : "#666666";

      html += `
        <g style="cursor: pointer;" onclick="selectStage('${node.id}')">
          <!-- 节点外圈高亮 -->
          <circle cx="${node.cx}" cy="${node.cy}" r="18" 
                  fill="${node.color}" 
                  fill-opacity="${isActive ? '0.2' : '0.1'}" 
                  stroke="${node.color}" 
                  stroke-width="${isActive ? '2.5' : '1'}" />
          <!-- 节点核心圆点 -->
          <circle cx="${node.cx}" cy="${node.cy}" r="6" fill="${node.color}" />
          <!-- 文本标签 -->
          <text x="${node.cx}" y="${node.cy - 24}" text-anchor="middle" 
                font-size="12px" font-weight="${isActive ? '500' : '400'}" fill="${textColor}">
            ${node.label}
          </text>
          <text x="${node.cx}" y="${node.cy + 30}" text-anchor="middle" 
                font-size="10px" fill="${subTextColor}">
            ${node.period}
          </text>
        </g>
      `;
    });

    svg.innerHTML = html;
  }

  function selectStage(stageId) {
    currentStageId = stageId;
    renderTimeline();
    renderStagePanel();
    drawTree();
  }

  // 初始化
  selectStage("traditional");

  // 监听系统主题变化以重绘 SVG
  if (window.matchMedia) {
    window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
      drawTree();
    });
  }
</script>
