<script>
  // 初始样本点数据
  const initialPoints = [
    { id: 0, x: 0.25, y: 0.30, label: 1 },
    { id: 1, x: 0.30, y: 0.70, label: 1 },
    { id: 2, x: 0.40, y: 0.45, label: 1 },
    { id: 3, x: 0.75, y: 0.70, label: -1 },
    { id: 4, x: 0.70, y: 0.30, label: -1 },
    { id: 5, x: 0.60, y: 0.55, label: -1 }
  ];

  let state = {
    points: JSON.parse(JSON.stringify(initialPoints)),
    kernelType: 'linear',
    C: 1.0,
    rbfSigma: 0.5,
    draggedPointId: -1,
    nextId: 6
  };

  // 极简 SMO 求解器实现
  function solveSVM() {
    const N = state.points.length;
    if (N === 0) return null;

    // 准备特征与标签
    const X = state.points.map(p => [p.x, p.y]);
    const Y = state.points.map(p => p.label);

    // 核函数定义
    function kernel(x1, x2) {
      if (state.kernelType === 'linear') {
        return x1[0] * x2[0] + x1[1] * x2[1];
      } else {
        const distSq = (x1[0] - x2[0]) ** 2 + (x1[1] - x2[1]) ** 2;
        return Math.exp(-distSq / (2 * state.rbfSigma * state.rbfSigma));
      }
    }

    // 预计算核矩阵
    const K = Array(N).fill(0).map(() => Array(N).fill(0));
    for (let i = 0; i < N; i++) {
      for (let j = 0; j < N; j++) {
        K[i][j] = kernel(X[i], X[j]);
      }
    }

    // 变量初始化
    let alpha = Array(N).fill(0);
    let b = 0;
    const tol = 1e-3;
    const C = state.C;
    let passes = 0;
    const maxPasses = 40;

    // 简易 SMO 循环
    while (passes < maxPasses) {
      let numChangedAlphas = 0;
      for (let i = 0; i < N; i++) {
        // 计算 Ei
        let f_i = 0;
        for (let k = 0; k < N; k++) {
          f_i += alpha[k] * Y[k] * K[k][i];
        }
        f_i += b;
        const E_i = f_i - Y[i];

        if ((Y[i] * E_i < -tol && alpha[i] < C) || (Y[i] * E_i > tol && alpha[i] > 0)) {
          // 随机选择 j != i
          let j = Math.floor(Math.random() * (N - 1));
          if (j >= i) j++;

          // 计算 Ej
          let f_j = 0;
          for (let k = 0; k < N; k++) {
            f_j += alpha[k] * Y[k] * K[k][j];
          }
          f_j += b;
          const E_j = f_j - Y[j];

          const oldAlphaI = alpha[i];
          const oldAlphaJ = alpha[j];

          // 计算 L 和 H
          let L = 0, H = C;
          if (Y[i] !== Y[j]) {
            L = Math.max(0, alpha[j] - alpha[i]);
            H = Math.min(C, C + alpha[j] - alpha[i]);
          } else {
            L = Math.max(0, alpha[i] + alpha[j] - C);
            H = Math.min(C, alpha[i] + alpha[j]);
          }

          if (Math.abs(L - H) < 1e-5) continue;

          // 计算 eta
          const eta = 2 * K[i][j] - K[i][i] - K[j][j];
          if (eta >= 0) continue;

          // 更新 alpha[j]
          let newAlphaJ = alpha[j] - (Y[j] * (E_i - E_j)) / eta;
          if (newAlphaJ > H) newAlphaJ = H;
          else if (newAlphaJ < L) newAlphaJ = L;

          if (Math.abs(newAlphaJ - alpha[j]) < 1e-5) continue;

          alpha[j] = newAlphaJ;

          // 更新 alpha[i]
          alpha[i] = alpha[i] + Y[i] * Y[j] * (oldAlphaJ - alpha[j]);

          // 更新 b
          const b1 = b - E_i - Y[i] * (alpha[i] - oldAlphaI) * K[i][i] - Y[j] * (alpha[j] - oldAlphaJ) * K[i][j];
          const b2 = b - E_j - Y[i] * (alpha[i] - oldAlphaI) * K[i][j] - Y[j] * (alpha[j] - oldAlphaJ) * K[j][j];

          if (alpha[i] > 0 && alpha[i] < C) b = b1;
          else if (alpha[j] > 0 && alpha[j] < C) b = b2;
          else b = (b1 + b2) / 2;

          numChangedAlphas++;
        }
      }

      if (numChangedAlphas === 0) {
        passes++;
      } else {
        passes = 0;
      }
    }

    // 预测函数
    function predict(x) {
      let val = 0;
      for (let i = 0; i < N; i++) {
        val += alpha[i] * Y[i] * kernel(X[i], x);
      }
      return val + b;
    }

    return { alpha, b, predict, X, Y };
  }

  // 渲染更新
  function update() {
    const svg = document.getElementById('svm-svg');
    const contourGroup = document.getElementById('contour-group');
    const pointsGroup = document.getElementById('points-group');
    const svHighlights = document.getElementById('sv-highlights');
    const dbPath = document.getElementById('decision-boundary');
    const mPlusPath = document.getElementById('margin-plus');
    const mMinusPath = document.getElementById('margin-minus');

    // 清空动态生成的内容
    contourGroup.innerHTML = '';
    pointsGroup.innerHTML = '';
    svHighlights.innerHTML = '';

    // 求解 SVM
    const model = solveSVM();
    let supportVectorCount = 0;

    if (model) {
      // 统计支持向量
      supportVectorCount = model.alpha.filter(a => a > 1e-4).length;
      document.getElementById('stat-sv').textContent = supportVectorCount;
      document.getElementById('stat-status').textContent = '收敛';

      // 绘制背景决策区域 (网格采样)
      const gridCols = 40;
      const gridRows = 30;
      const cellW = 600 / gridCols;
      const cellH = 450 / gridRows;

      for (let c = 0; c < gridCols; c++) {
        for (let r = 0; r < gridRows; r++) {
          const px = (c + 0.5) / gridCols;
          const py = (r + 0.5) / gridRows;
          const val = model.predict([px, py]);

          const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          rect.setAttribute('x', c * cellW);
          rect.setAttribute('y', r * cellH);
          rect.setAttribute('width', cellW + 0.5);
          rect.setAttribute('height', cellH + 0.5);

          // 柔和的分类背景色
          if (val > 0) {
            rect.setAttribute('fill', 'var(--color-background-danger)');
            rect.setAttribute('opacity', Math.min(0.15, val * 0.1));
          } else {
            rect.setAttribute('fill', 'var(--color-background-info)');
            rect.setAttribute('opacity', Math.min(0.15, -val * 0.1));
          }
          contourGroup.appendChild(rect);
        }
      }

      // 提取决策边界和间隔线 (等高线绘制)
      function getContourPath(targetVal) {
        let pathData = '';
        const resX = 60;
        const resY = 45;
        const grid = Array(resX).fill(0).map(() => Array(resY).fill(0));

        for (let i = 0; i < resX; i++) {
          for (let j = 0; j < resY; j++) {
            grid[i][j] = model.predict([i / (resX - 1), j / (resY - 1)]);
          }
        }

        // 简易 Marching Squares 提取等高线段
        for (let i = 0; i < resX - 1; i++) {
          for (let j = 0; j < resY - 1; j++) {
            const x0 = (i / (resX - 1)) * 600;
            const x1 = ((i + 1) / (resX - 1)) * 600;
            const y0 = (j / (resY - 1)) * 450;
            const y1 = ((j + 1) / (resY - 1)) * 450;

            const v00 = grid[i][j] - targetVal;
            const v10 = grid[i + 1][j] - targetVal;
            const v11 = grid[i + 1][j + 1] - targetVal;
            const v01 = grid[i][j + 1] - targetVal;

            let points = [];
            // 插值计算边界点
            if ((v00 >= 0) !== (v10 >= 0)) {
              const t = -v00 / (v10 - v00);
              points.push({ x: x0 + t * (x1 - x0), y: y0 });
            }
            if ((v10 >= 0) !== (v11 >= 0)) {
              const t = -v10 / (v11 - v10);
              points.push({ x: x1, y: y0 + t * (y1 - y0) });
            }
            if ((v11 >= 0) !== (v01 >= 0)) {
              const t = -v11 / (v01 - v11);
              points.push({ x: x1 - t * (x1 - x0), y: y1 });
            }
            if ((v01 >= 0) !== (v00 >= 0)) {
              const t = -v01 / (v00 - v01);
              points.push({ x: x0, y: y1 - t * (y1 - y0) });
            }

            if (points.length >= 2) {
              pathData += ` M ${points[0].x} ${points[0].y} L ${points[1].x} ${points[1].y}`;
            }
          }
        }
        return pathData;
      }

      dbPath.setAttribute('d', getContourPath(0));
      mPlusPath.setAttribute('d', getContourPath(1));
      mMinusPath.setAttribute('d', getContourPath(-1));
    } else {
      document.getElementById('stat-sv').textContent = '0';
      document.getElementById('stat-status').textContent = '无数据';
      dbPath.setAttribute('d', '');
      mPlusPath.setAttribute('d', '');
      mMinusPath.setAttribute('d', '');
    }

    // 绘制样本点与支持向量高亮
    state.points.forEach((p) => {
      const cx = p.x * 600;
      const cy = p.y * 450;
      const isSV = model && model.alpha[state.points.indexOf(p)] > 1e-4;

      if (isSV) {
        // 支持向量外圈虚线圆环
        const halo = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        halo.setAttribute('cx', cx);
        halo.setAttribute('cy', cy);
        halo.setAttribute('r', 14);
        halo.setAttribute('fill', 'none');
        halo.setAttribute('stroke', 'var(--color-text-primary)');
        halo.setAttribute('stroke-width', '1.5');
        halo.setAttribute('stroke-dasharray', '3,3');
        svHighlights.appendChild(halo);
      }

      // 样本点实体
      const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      circle.setAttribute('cx', cx);
      circle.setAttribute('cy', cy);
      circle.setAttribute('r', 8);
      circle.setAttribute('class', p.label === 1 ? 'c-red' : 'c-blue');
      circle.setAttribute('fill', p.label === 1 ? 'var(--color-text-danger)' : 'var(--color-text-info)');
      circle.setAttribute('stroke', 'var(--color-background-primary)');
      circle.setAttribute('stroke-width', '2');
      circle.style.cursor = 'grab';

      // 绑定拖拽事件
      const startDrag = (e) => {
        state.draggedPointId = p.id;
        circle.style.cursor = 'grabbing';
      };

      circle.addEventListener('mousedown', startDrag);
      circle.addEventListener('touchstart', (e) => {
        e.preventDefault();
        startDrag();
      });

      pointsGroup.appendChild(circle);
    });
  }

  // 全局拖拽事件监听
  const svgEl = document.getElementById('svm-svg');

  function handleMove(clientX, clientY) {
    if (state.draggedPointId === -1) return;
    const rect = svgEl.getBoundingClientRect();
    const x = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
    const y = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));

    const point = state.points.find(p => p.id === state.draggedPointId);
    if (point) {
      point.x = x;
      point.y = y;
      update();
    }
  }

  window.addEventListener('mousemove', (e) => {
    if (state.draggedPointId !== -1) {
      handleMove(e.clientX, e.clientY);
    }
  });

  window.addEventListener('touchmove', (e) => {
    if (state.draggedPointId !== -1 && e.touches.length > 0) {
      handleMove(e.touches[0].clientX, e.touches[0].clientY);
    }
  }, { passive: false });

  const endDrag = () => {
    state.draggedPointId = -1;
  };
  window.addEventListener('mouseup', endDrag);
  window.addEventListener('touchend', endDrag);

  // 控件事件绑定
  document.getElementById('kernel-type').addEventListener('change', (e) => {
    state.kernelType = e.target.value;
    document.getElementById('sigma-group').style.display = state.kernelType === 'rbf' ? 'flex' : 'none';
    update();
  });

  document.getElementById('range-c').addEventListener('input', (e) => {
    state.C = parseFloat(e.target.value);
    document.getElementById('val-c').textContent = state.C.toFixed(1);
    update();
  });

  document.getElementById('range-sigma').addEventListener('input', (e) => {
    state.rbfSigma = parseFloat(e.target.value);
    document.getElementById('val-sigma').textContent = state.rbfSigma.toFixed(2);
    update();
  });

  document.getElementById('reset-points').addEventListener('click', () => {
    state.points = JSON.parse(JSON.stringify(initialPoints));
    update();
  });

  document.getElementById('add-red').addEventListener('click', () => {
    state.points.push({
      id: state.nextId++,
      x: 0.3 + Math.random() * 0.1,
      y: 0.4 + Math.random() * 0.1,
      label: 1
    });
    update();
  });

  document.getElementById('add-blue').addEventListener('click', () => {
    state.points.push({
      id: state.nextId++,
      x: 0.6 + Math.random() * 0.1,
      y: 0.4 + Math.random() * 0.1,
      label: -1
    });
    update();
  });

  // 首次渲染
  update();
</script>
