<script>
  // 状态变量
  let array = [45, 12, 85, 32, 89, 39, 67, 93, 22, 55];
  let statesHistory = [];
  let currentStepIndex = 0;
  let isPlaying = false;
  let speed = 700;
  let timer = null;

  // 预生成快速排序的每一步状态
  function generateHistory() {
    statesHistory = [];
    let arrCopy = [...array];
    let sortedIndices = new Set();

    // 辅助记录函数
    function record(low, high, i, j, pivotIdx, activeLine, desc, highlightSwap = []) {
      statesHistory.push({
        arr: [...arrCopy],
        low,
        high,
        i,
        j,
        pivotIdx,
        activeLine,
        desc,
        sorted: new Set(sortedIndices),
        highlightSwap: [...highlightSwap]
      });
    }

    function quickSort(low, high) {
      record(low, high, -1, -1, -1, 1, `准备对区间 [${low}, ${high}] 进行排序`);
      if (low < high) {
        let pIdx = partition(low, high);
        record(low, high, -1, -1, pIdx, 2, `完成基准划分，基准元素值 ${arrCopy[pIdx]} 已就位。递归处理左右子区间`);

        quickSort(low, pIdx - 1);
        quickSort(pIdx + 1, high);
      } else if (low === high) {
        sortedIndices.add(low);
        record(low, high, -1, -1, -1, 1, `区间长度为 1，元素 ${arrCopy[low]} 已自然有序`);
      }
    }

    function partition(low, high) {
      let pivot = arrCopy[high];
      let pivotIdx = high;
      record(low, high, -1, -1, pivotIdx, 7, `选择当前区间最右端元素 ${pivot} 作为基准值 (Pivot)`);

      let i = low - 1;
      record(low, high, i, -1, pivotIdx, 8, `初始化指针 i = ${i} (表示小于基准值区域的右边界)`);

      for (let j = low; j < high; j++) {
        record(low, high, i, j, pivotIdx, 9, `扫描指针 j = ${j}，对比当前元素 ${arrCopy[j]} 与基准值 ${pivot}`);
        if (arrCopy[j] < pivot) {
          i++;
          record(low, high, i, j, pivotIdx, 10, `发现 ${arrCopy[j]} < 基准值 ${pivot}，准备将 i 往右移并交换元素`);
          let temp = arrCopy[i];
          arrCopy[i] = arrCopy[j];
          arrCopy[j] = temp;
          record(low, high, i, j, pivotIdx, 11, `交换 arr[i](${arrCopy[i]}) 与 arr[j](${arrCopy[j]})`, [i, j]);
        } else {
          record(low, high, i, j, pivotIdx, 9, `${arrCopy[j]} >= 基准值 ${pivot}，指针 j 继续向前推进`);
        }
      }

      record(low, high, i, -1, pivotIdx, 12, `扫描完成。准备将基准元素与 arr[i + 1] 交换，使基准归位`);
      let temp = arrCopy[i + 1];
      arrCopy[i + 1] = arrCopy[high];
      arrCopy[high] = temp;
      let finalPivotIdx = i + 1;
      sortedIndices.add(finalPivotIdx);
      record(low, high, i, -1, finalPivotIdx, 12, `交换成功，基准值归位到索引 ${finalPivotIdx}。该位置元素已确定最终排好序`, [i + 1, high]);

      return finalPivotIdx;
    }

    quickSort(0, arrCopy.length - 1);

    // 补齐最终完成状态
    for (let k = 0; k < arrCopy.length; k++) sortedIndices.add(k);
    record(-1, -1, -1, -1, -1, 0, "快速排序算法执行完毕！所有元素均已排好序。");
  }

  // 渲染函数
  function update() {
    const state = statesHistory[currentStepIndex];
    if (!state) return;

    // 更新步骤计数
    document.getElementById('step-counter').textContent = `${currentStepIndex + 1} / ${statesHistory.length}`;

    // 更新描述文本
    document.getElementById('status-desc').textContent = state.desc;

    // 更新伪代码高亮
    for (let c = 0; c <= 13; c++) {
      const lineEl = document.getElementById(`code-${c}`);
      if (lineEl) {
        if (c === state.activeLine) {
          lineEl.classList.add('active');
        } else {
          lineEl.classList.remove('active');
        }
      }
    }

    // 绘制 SVG 柱状图
    const svg = document.getElementById('stage-svg');
    svg.innerHTML = '';

    const width = 800;
    const height = 400;
    const padding = 50;
    const barAreaWidth = width - padding * 2;
    const barAreaHeight = height - padding * 2;
    const n = state.arr.length;
    const barGap = 12;
    const barWidth = (barAreaWidth - barGap * (n - 1)) / n;

    // 计算缩放比例
    const maxVal = Math.max(...array, 100);

    // 渲染当前活跃区间背景指示
    if (state.low !== -1 && state.high !== -1) {
      const activeX = padding + state.low * (barWidth + barGap) - 6;
      const activeW = (state.high - state.low + 1) * (barWidth + barGap) - barGap + 12;

      // 虚线框包裹当前区间
      const rectBox = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      rectBox.setAttribute("x", activeX);
      rectBox.setAttribute("y", padding - 15);
      rectBox.setAttribute("width", activeW);
      rectBox.setAttribute("height", barAreaHeight + 35);
      rectBox.setAttribute("fill", "rgba(56, 189, 248, 0.03)");
      rectBox.setAttribute("stroke", "rgba(56, 189, 248, 0.25)");
      rectBox.setAttribute("stroke-dasharray", "4 4");
      rectBox.setAttribute("rx", "6");
      svg.appendChild(rectBox);

      // 区间标注文本
      const textRange = document.createElementNS("http://www.w3.org/2000/svg", "text");
      textRange.setAttribute("x", activeX + activeW / 2);
      textRange.setAttribute("y", padding - 22);
      textRange.setAttribute("fill", "#38BDF8");
      textRange.setAttribute("font-size", "11px");
      textRange.setAttribute("text-anchor", "middle");
      textRange.textContent = `当前活跃区间: [${state.low} ... ${state.high}]`;
      svg.appendChild(textRange);
    }

    // 绘制每个柱子
    for (let idx = 0; idx < n; idx++) {
      const val = state.arr[idx];
      const barHeight = (val / maxVal) * barAreaHeight;
      const x = padding + idx * (barWidth + barGap);
      const y = height - padding - barHeight;

      // 决定颜色
      let color = "#38BDF8"; // 默认蓝色
      let isPivot = (idx === state.pivotIdx);
      let isSorted = state.sorted.has(idx);
      let isHighlightedSwap = state.highlightSwap.includes(idx);

      if (isSorted) {
        color = "#10B981"; // 已排好序：绿色
      } else if (isPivot) {
        color = "#F43F5E"; // 基准值：红色
      } else if (isHighlightedSwap) {
        color = "#F59E0B"; // 正在交换：黄色
      } else if (state.low !== -1 && state.high !== -1 && idx >= state.low && idx <= state.high) {
        color = "#E2E8F0"; // 处于活跃区间但非基准：淡灰色
      } else {
        color = "#475569"; // 处于非活跃区间：暗灰
      }

      // 如果是 Pivot，绘制发光光晕
      if (isPivot) {
        const glow = document.createElementNS("http://www.w3.org/2000/svg", "rect");
        glow.setAttribute("x", x - 4);
        glow.setAttribute("y", y - 4);
        glow.setAttribute("width", barWidth + 8);
        glow.setAttribute("height", barHeight + 8);
        glow.setAttribute("fill", "none");
        glow.setAttribute("stroke", "#F43F5E");
        glow.setAttribute("stroke-width", "2");
        glow.setAttribute("opacity", "0.4");
        glow.setAttribute("rx", "4");
        svg.appendChild(glow);
      }

      // 绘制柱体
      const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      rect.setAttribute("x", x);
      rect.setAttribute("y", y);
      rect.setAttribute("width", barWidth);
      rect.setAttribute("height", barHeight);
      rect.setAttribute("fill", color);
      rect.setAttribute("rx", "3");
      rect.style.transition = "all 0.2s ease-in-out";
      svg.appendChild(rect);

      // 绘制柱顶数值
      const textVal = document.createElementNS("http://www.w3.org/2000/svg", "text");
      textVal.setAttribute("x", x + barWidth / 2);
      textVal.setAttribute("y", y - 8);
      textVal.setAttribute("fill", isPivot ? "#F43F5E" : (isSorted ? "#10B981" : "#94A3B8"));
      textVal.setAttribute("font-size", "11px");
      textVal.setAttribute("font-weight", isPivot || isSorted ? "bold" : "normal");
      textVal.setAttribute("text-anchor", "middle");
      textVal.textContent = val;
      svg.appendChild(textVal);

      // 绘制底部索引
      const textIdx = document.createElementNS("http://www.w3.org/2000/svg", "text");
      textIdx.setAttribute("x", x + barWidth / 2);
      textIdx.setAttribute("y", height - padding + 18);
      textIdx.setAttribute("fill", "#64748B");
      textIdx.setAttribute("font-size", "10px");
      textIdx.setAttribute("text-anchor", "middle");
      textIdx.textContent = idx;
      svg.appendChild(textIdx);

      // 绘制指针标记 (i, j)
      let pointerLabel = "";
      let pointerColor = "";
      if (idx === state.i && idx === state.j) {
        pointerLabel = "i, j";
        pointerColor = "#38BDF8";
      } else if (idx === state.i) {
        pointerLabel = "i";
        pointerColor = "#F59E0B";
      } else if (idx === state.j) {
        pointerLabel = "j";
        pointerColor = "#38BDF8";
      }

      if (pointerLabel) {
        const textPtr = document.createElementNS("http://www.w3.org/2000/svg", "text");
        textPtr.setAttribute("x", x + barWidth / 2);
        textPtr.setAttribute("y", height - padding + 34);
        textPtr.setAttribute("fill", pointerColor);
        textPtr.setAttribute("font-size", "11px");
        textPtr.setAttribute("font-weight", "bold");
        textPtr.setAttribute("text-anchor", "middle");
        textPtr.textContent = pointerLabel;
        svg.appendChild(textPtr);

        // 指向的小箭头
        const arrow = document.createElementNS("http://www.w3.org/2000/svg", "path");
        arrow.setAttribute("d", `M ${x + barWidth / 2} ${height - padding + 22} l -3 4 l 6 0 z`);
        arrow.setAttribute("fill", pointerColor);
        svg.appendChild(arrow);
      }

      // 如果 i 此时为 -1，在最左侧画出 i 指针表示虚拟起点
      if (state.i === -1 && idx === 0 && (state.low !== -1)) {
        const xVirtual = padding - 25;
        const textPtr = document.createElementNS("http://www.w3.org/2000/svg", "text");
        textPtr.setAttribute("x", xVirtual);
        textPtr.setAttribute("y", height - padding + 34);
        textPtr.setAttribute("fill", "#F59E0B");
        textPtr.setAttribute("font-size", "11px");
        textPtr.setAttribute("font-weight", "bold");
        textPtr.setAttribute("text-anchor", "middle");
        textPtr.textContent = "i (-1)";
        svg.appendChild(textPtr);
      }
    }

    // 禁用/启用单步按钮
    document.getElementById('btn-prev').disabled = currentStepIndex === 0;
    document.getElementById('btn-next').disabled = currentStepIndex === statesHistory.length - 1;
  }

  // 播放控制
  function togglePlay() {
    if (isPlaying) {
      clearInterval(timer);
      isPlaying = false;
      document.getElementById('play-icon').innerHTML = `
        <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
        自动播放
      `;
    } else {
      if (currentStepIndex >= statesHistory.length - 1) {
        currentStepIndex = 0;
      }
      isPlaying = true;
      document.getElementById('play-icon').innerHTML = `
        <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
        暂停播放
      `;
      runTimer();
    }
  }

  function runTimer() {
    clearInterval(timer);
    timer = setInterval(() => {
      if (currentStepIndex < statesHistory.length - 1) {
        currentStepIndex++;
        update();
      } else {
        togglePlay(); // 结束播放
      }
    }, speed);
  }

  // 生成随机数组
  function regenerateArray() {
    let newArr = [];
    for (let k = 0; k < 10; k++) {
      newArr.push(Math.floor(Math.random() * 85) + 12);
    }
    array = newArr;
    currentStepIndex = 0;
    if (isPlaying) togglePlay();
    generateHistory();
    update();
  }

  // 事件绑定
  document.getElementById('btn-play').addEventListener('click', togglePlay);

  document.getElementById('btn-next').addEventListener('click', () => {
    if (currentStepIndex < statesHistory.length - 1) {
      currentStepIndex++;
      update();
    }
  });

  document.getElementById('btn-prev').addEventListener('click', () => {
    if (currentStepIndex > 0) {
      currentStepIndex--;
      update();
    }
  });

  document.getElementById('btn-reset').addEventListener('click', () => {
    currentStepIndex = 0;
    if (isPlaying) togglePlay();
    update();
  });

  document.getElementById('btn-random').addEventListener('click', regenerateArray);

  const speedRange = document.getElementById('speed-range');
  speedRange.addEventListener('input', (e) => {
    speed = parseInt(e.target.value);
    document.getElementById('speed-val').textContent = `${speed}ms`;
    if (isPlaying) {
      runTimer();
    }
  });

  // 初始化绘制
  generateHistory();
  update();
</script>
