    state.selectedTokenIndex = index;
    update();
  }

  // 全局渲染更新
  function update() {
    // 1. 更新左侧架构图高亮
    document.querySelectorAll('.arch-node').forEach(node => {
      node.classList.remove('active');
    });
    const activeNode = document.getElementById(`node-${state.activeStep}`);
    if (activeNode) {
      activeNode.classList.add('active');
    }

    // 2. 更新底部文字和公式
    const detail = stepDetails[state.activeStep];
    document.getElementById('micro-title').textContent = detail.title;
    document.getElementById('micro-subtitle').textContent = detail.subtitle;
    document.getElementById('formula-render').textContent = detail.formula;
    document.getElementById('explain-render').textContent = detail.explain;

    // 3. 更新顶部按钮样式
    document.querySelectorAll('.step-btn').forEach(btn => {
      btn.classList.remove('active');
      if (btn.getAttribute('onclick').includes(state.activeStep)) {
        btn.classList.add('active');
      }
    });

    // 4. 重绘右侧微观视图
    renderDetailView();
  }

  // 绘制右侧微观视图
  function renderDetailView() {
    const svg = document.getElementById('detail-svg');
    svg.innerHTML = ''; // 清空

    if (state.activeStep === 'input') {
      renderInputView(svg);
    } else if (state.activeStep === 'attention') {
      renderAttentionView(svg);
    } else if (state.activeStep === 'multihead') {
      renderMultiheadView(svg);
    } else if (state.activeStep === 'feedforward') {
      renderFeedforwardView(svg);
    }
  }

  // 1. 渲染输入嵌入视图
  function renderInputView(svg) {
    let html = '';
    state.inputText.forEach((token, idx) => {
      const x = 50 + idx * 65;
      html += `
        <!-- Token -->
        <g class="token-node" onclick="selectToken(${idx})">
          <rect x="${x}" y="240" width="50" height="30" rx="4" fill="#1f293d" stroke="#58a6ff" stroke-width="1"/>
          <text x="${x+25}" y="255" font-size="11" fill="#e6edf3" text-anchor="middle" dominant-baseline="central">${token}</text>
        </g>
        <!-- Sum node -->
        <circle cx="${x+25}" cy="160" r="14" fill="#161b22" stroke="#7ee787" stroke-width="1.5"/>
        <text x="${x+25}" y="160" font-size="14" fill="#7ee787" text-anchor="middle" dominant-baseline="central">+</text>

        <!-- Positional Embed -->
        <rect x="${x}" y="80" width="50" height="24" rx="4" fill="#21262d" stroke="#30363d" stroke-width="1"/>
        <text x="${x+25}" y="92" font-size="9" fill="#8b949e" text-anchor="middle" dominant-baseline="central">Pos [${idx}]</text>

        <!-- Vectors -->
        <line x1="${x+25}" y1="240" x2="${x+25}" y2="174" stroke="#8b949e" stroke-dasharray="2,2"/>
        <line x1="${x+25}" y1="104" x2="${x+25}" y2="146" stroke="#8b949e" stroke-dasharray="2,2"/>
        <line x1="${x+25}" y1="146" x2="${x+25}" y2="40" stroke="#7ee787" stroke-width="1.5" marker-end="url(#arrow)"/>
      `;
    });
    html += `<text x="180" y="30" font-size="11" fill="#7ee787" text-anchor="middle">融合位置信息的特征表达向量 (X)</text>`;
    svg.innerHTML = html;
  }

  // 2. 渲染自注意力视图
  function renderAttentionView(svg) {
    let html = '';
    const selIdx = state.selectedTokenIndex;
    const qToken = state.inputText[selIdx];

    // 绘制上方节点 (Target Vector)
    html += `
      <g>
        <rect x="130" y="20" width="100" height="32" rx="6" fill="#1f293d" stroke="#58a6ff" stroke-width="1.5"/>
        <text x="180" y="36" font-size="12" fill="#79c0ff" text-anchor="middle" dominant-baseline="central">融合特征: ${qToken}</text>
      </g>
    `;

    // 绘制下方节点 (Source Tokens)
    state.inputText.forEach((token, idx) => {
      const x = 30 + idx * 65;
      const weight = state.attentionMatrix[selIdx][idx];
      const isSelected = idx === selIdx;

      // 注意力连线
      const strokeWidth = 1 + weight * 8;
      const opacity = 0.15 + weight * 0.85;
      const strokeColor = isSelected ? '#7ee787' : '#58a6ff';

      html += `
        <path d="M 180,52 L ${x+25},220" stroke="${strokeColor}" stroke-width="${strokeWidth}" opacity="${opacity}" fill="none"/>
        <!-- 粒子微光 -->
        <path class="flow-line" d="M 180,52 L ${x+25},220" stroke="#ff7b72" stroke-width="1" opacity="${weight > 0.2 ? 0.8 : 0}" fill="none"/>

        <!-- 权重标签 -->
        <text x="${x+25}" y="195" font-size="10" fill="#7ee787" text-anchor="middle" opacity="${opacity}">${(weight * 100).toFixed(0)}%</text>

        <g class="token-node ${isSelected ? 'selected' : ''}" onclick="selectToken(${idx})">
          <rect x="${x}" y="220" width="50" height="30" rx="4" fill="#161b22" stroke="#30363d" stroke-width="1"/>
          <text x="${x+25}" y="235" font-size="11" fill="#e6edf3" text-anchor="middle" dominant-baseline="central">${token}</text>
        </g>
      `;
    });

    svg.innerHTML = html;
  }

  // 3. 渲染多头自注意力机制
  function renderMultiheadView(svg) {
    let html = '';
    const heads = state.headCount;

    // 输入端
    html += `
      <rect x="110" y="250" width="140" height="28" rx="4" fill="#161b22" stroke="#30363d"/>
      <text x="180" y="264" font-size="11" fill="#e6edf3" text-anchor="middle" dominant-baseline="central">输入矩阵 X</text>
    `;

    // 多头分流
    for (let i = 0; i < heads; i++) {
      const hX = 50 + i * (260 / (heads - 1 || 1));
      const colors = ['#58a6ff', '#7ee787', '#ff7b72', '#d2a8ff'];
      const color = colors[i % colors.length];

      html += `
        <line x1="180" y1="250" x2="${hX}" y2="160" stroke="${color}" stroke-width="1.5" opacity="0.7"/>
        <g>
          <rect x="${hX-25}" y="120" width="50" height="40" rx="4" fill="#1f293d" stroke="${color}" stroke-width="1"/>
          <text x="${hX}" y="135" font-size="10" fill="#e6edf3" text-anchor="middle">Head ${i+1}</text>
          <text x="${hX}" y="148" font-size="8" fill="${color}" text-anchor="middle">Attention</text>
        </g>
        <line x1="${hX}" y1="120" x2="180" y2="50" stroke="${color}" stroke-width="1.5" opacity="0.7"/>
      `;
    }

    // 拼接输出
    html += `
      <rect x="110" y="20" width="140" height="30" rx="4" fill="#1b2a22" stroke="#7ee787"/>
      <text x="180" y="35" font-size="11" fill="#7ee787" text-anchor="middle" dominant-baseline="central">Concat (多头拼接输出)</text>
    `;

    svg.innerHTML = html;
  }

  // 4. 渲染前馈网络视图
  function renderFeedforwardView(svg) {
    svg.innerHTML = `
      <!-- 输入 -->
      <rect x="100" y="240" width="160" height="28" rx="4" fill="#161b22" stroke="#30363d"/>
      <text x="180" y="254" font-size="11" fill="#e6edf3" text-anchor="middle" dominant-baseline="central">自注意力层输出向量</text>
      <line x1="180" y1="240" x2="180" y2="190" stroke="#30363d" stroke-width="2" marker-end="url(#arrow)"/>

      <!-- 线性映射 1 + ReLU -->
      <rect x="70" y="150" width="220" height="40" rx="6" fill="#1f293d" stroke="#58a6ff"/>
      <text x="180" y="164" font-size="11" fill="#e6edf3" text-anchor="middle">线性映射 (维度放大 4 倍)</text>
      <text x="180" y="178" font-size="10" fill="#79c0ff" text-anchor="middle">Linear + ReLU 激活函数</text>
      <line x1="180" y1="150" x2="180" y2="100" stroke="#30363d" stroke-width="2" marker-end="url(#arrow)"/>

      <!-- 线性映射 2 -->
      <rect x="70" y="60" width="220" height="40" rx="6" fill="#1f293d" stroke="#7ee787"/>
      <text x="180" y="74" font-size="11" fill="#e6edf3" text-anchor="middle">线性映射 (维度恢复至 d_model)</text>
      <text x="180" y="88" font-size="10" fill="#7ee787" text-anchor="middle">Linear Projection</text>
      <line x1="180" y1="60" x2="180" y2="25" stroke="#7ee787" stroke-width="1.5" marker-end="url(#arrow)"/>

      <!-- 输出结果 -->
      <text x="180" y="15" font-size="11" fill="#7ee787" text-anchor="middle">最终前馈特征输出</text>
    `;
  }

  // 初始化首次绘制
  update();
</script>
</widget_code>

