      {id: 5, x: 30, y: 55, label: 'A'},
      {id: 6, x: 60, y: 75, label: 'B'},
      {id: 7, x: 75, y: 60, label: 'B'},
      {id: 8, x: 80, y: 35, label: 'B'},
      {id: 9, x: 65, y: 40, label: 'B'},
      {id: 10, x: 85, y: 70, label: 'B'},
      {id: 11, x: 52, y: 62, label: 'B'},
      {id: 12, x: 48, y: 38, label: 'A'}
    ],
    addMode: null // 'A' or 'B' or null
  };

  const svg = document.getElementById('stage-svg');
  const queryGroup = document.getElementById('query-group');
  const queryPointEl = document.getElementById('query-point');
  const queryGlowEl = document.getElementById('query-glow');
  const kSlider = document.getElementById('k-slider');
  const kValText = document.getElementById('k-val');
  const metricSelect = document.getElementById('metric');
  const addABtn = document.getElementById('add-a-btn');
  const addBBtn = document.getElementById('add-b-btn');

  // 初始化网格背景
  function initGrid() {
    const gridG = document.getElementById('grid');
    let gridHTML = '';
    for (let i = 10; i < 100; i += 10) {
      gridHTML += `<line class="grid-lines" x1="${i}" y1="0" x2="${i}" y2="100" />`;
      gridHTML += `<line class="grid-lines" x1="0" y1="${i}" x2="100" y2="${i}" />`;
    }
    gridG.innerHTML = gridHTML;
  }

  // 距离计算
  function calcDistance(p1, p2, metric) {
    if (metric === 'euclidean') {
      return Math.sqrt(Math.pow(p1[0] - p2[0], 2) + Math.pow(p1[1] - p2[1], 2));
    } else {
      return Math.abs(p1[0] - p2[0]) + Math.abs(p1[1] - p2[1]);
    }
  }

  // 主渲染与计算流程
  function update() {
    const qX = state.queryPoint[0];
    const qY = state.queryPoint[1];

    // 更新查询点位置
    queryGroup.setAttribute('transform', `translate(${qX}, ${qY})`);

    // 计算到所有样本点的距离并排序
    const sortedData = state.dataset.map(pt => {
      const dist = calcDistance([pt.x, pt.y], [qX, qY], state.distanceMetric);
      return { ...pt, dist };
    }).sort((a, b) => a.dist - b.dist);

    // 筛选前 K 个邻居
    const k = Math.min(state.kValue, sortedData.length);
    const neighbors = sortedData.slice(0, k);
    const neighborIds = new Set(neighbors.map(n => n.id));

    // 统计投票
    let votesA = 0;
    let votesB = 0;
    neighbors.forEach(n => {
      if (n.label === 'A') votesA++;
      else votesB++;
    });

    const winner = votesA >= votesB ? 'A' : 'B';

    // 1. 绘制样本点
    const ptsG = document.getElementById('dataset-points');
    ptsG.innerHTML = state.dataset.map(pt => {
      const isNeighbor = neighborIds.has(pt.id);
      const color = pt.label === 'A' ? '#3B82F6' : '#EC4899';
      const glow = pt.label === 'A' ? 'url(#glow-a)' : 'url(#glow-b)';
      const stroke = isNeighbor ? '#F3F4F6' : 'none';
      const strokeW = isNeighbor ? 0.8 : 0;
      const r = isNeighbor ? 2.2 : 1.6;
      return `
        <g>
          <circle cx="${pt.x}" cy="${pt.y}" r="${r * 3}" fill="${glow}" />
          <circle cx="${pt.x}" cy="${pt.y}" r="${r}" fill="${color}" stroke="${stroke}" stroke-width="${strokeW}" style="transition: r 0.15s;" />
        </g>
      `;
    }).join('');

    // 2. 绘制连接线与包围圈
    const connG = document.getElementById('connections');
    connG.innerHTML = neighbors.map(n => {
      const color = n.label === 'A' ? '#3B82F6' : '#EC4899';
      return `<line x1="${qX}" y1="${qY}" x2="${n.x}" y2="${n.y}" stroke="${color}" stroke-width="0.3" stroke-dasharray="0.8 1" opacity="0.7" />`;
    }).join('');

    // 包围圈半径为最远邻居的距离
    const boundaryCircle = document.getElementById('boundary-circle');
    if (neighbors.length > 0) {
      const maxDist = neighbors[neighbors.length - 1].dist;
      boundaryCircle.setAttribute('cx', qX);
      boundaryCircle.setAttribute('cy', qY);
      boundaryCircle.setAttribute('r', maxDist);
      boundaryCircle.setAttribute('opacity', '1');
    } else {
      boundaryCircle.setAttribute('opacity', '0');
    }

    // 3. 更新侧边栏决策面板
    const decPanel = document.getElementById('decision-panel');
    const decText = document.getElementById('decision-text');
    const voteA = document.getElementById('vote-a');
    const voteB = document.getElementById('vote-b');
    const voteACount = document.getElementById('vote-a-count');
    const voteBCount = document.getElementById('vote-b-count');

    if (winner === 'A') {
      decPanel.className = 'decision-box class-a';
      decText.className = 'decision-result class-a';
      decText.textContent = 'A 类 (蓝色)';
    } else {
      decPanel.className = 'decision-box class-b';
      decText.className = 'decision-result class-b';
      decText.textContent = 'B 类 (粉色)';
    }

    const totalVotes = k || 1;
    const pctA = (votesA / totalVotes) * 100;
    const pctB = (votesB / totalVotes) * 100;

    voteA.style.width = `${pctA}%`;
    voteB.style.width = `${pctB}%`;
    voteACount.textContent = votesA;
    voteBCount.textContent = votesB;

    // 4. 更新邻居列表
    const listContainer = document.getElementById('neighbor-list');
    listContainer.innerHTML = sortedData.map((pt, idx) => {
      const isNeighbor = idx < k;
      const classType = pt.label === 'A' ? 'class-a' : 'class-b';
      const selectedClass = isNeighbor ? 'selected' : '';
      return `
        <div class="neighbor-item ${classType} ${selectedClass}">
          <div>
            <span class="neighbor-id ${classType}">#${pt.id}</span>
            <span style="color: #94A3B8; margin-left: 6px;">(${pt.label}类)</span>
          </div>
          <span class="neighbor-dist">${pt.dist.toFixed(1)} px</span>
        </div>
      `;
    }).join('');
  }

  // 事件绑定与交互
  // 1. 拖拽目标点
  let isDragging = false;
  function getMouseCoords(e) {
    const rect = svg.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;
    return [Math.max(0, Math.min(100, x)), Math.max(0, Math.min(100, y))];
  }

  function handleStart(e) {
    if (state.addMode) {
      const coords = getMouseCoords(e);
      const newId = state.dataset.length + 1;
      state.dataset.push({
        id: newId,
        x: Math.round(coords[0]),
        y: Math.round(coords[1]),
        label: state.addMode
      });
      state.addMode = null;
      addABtn.classList.remove('active');
      addBBtn.classList.remove('active');
      update();
      return;
    }
    isDragging = true;
    handleMove(e);
  }

  function handleMove(e) {
    if (!isDragging) return;
    e.preventDefault();
    const coords = getMouseCoords(e);
    state.queryPoint = [Math.round(coords[0]), Math.round(coords[1])];
    update();
  }

  function handleEnd() {
    isDragging = false;
  }

  queryGroup.addEventListener('mousedown', handleStart);
  svg.addEventListener('mousedown', handleStart);
  window.addEventListener('mousemove', handleMove);
  window.addEventListener('mouseup', handleEnd);

  // 移动端触摸支持
  queryGroup.addEventListener('touchstart', (e) => {
    isDragging = true;
    handleMove(e.touches[0]);
  });
  svg.addEventListener('touchstart', (e) => {
    handleStart(e.touches[0]);
  });
  window.addEventListener('touchmove', (e) => {
    if (isDragging) handleMove(e.touches[0]);
  }, { passive: false });
  window.addEventListener('touchend', handleEnd);

  // 2. 控制项交互
  kSlider.addEventListener('input', (e) => {
    state.kValue = parseInt(e.target.value);
    kValText.textContent = state.kValue;
    update();
  });

  metricSelect.addEventListener('change', (e) => {
    state.distanceMetric = e.target.value;
    update();
  });

  addABtn.addEventListener('click', () => {
    state.addMode = state.addMode === 'A' ? null : 'A';
    addABtn.classList.toggle('active', state.addMode === 'A');
    addBBtn.classList.remove('active');
  });

  addBBtn.addEventListener('click', () => {
    state.addMode = state.addMode === 'B' ? null : 'B';
    addBBtn.classList.toggle('active', state.addMode === 'B');
    addABtn.classList.remove('active');
  });

  // 启动
  initGrid();
  update();
</script>
