<script>
  // State Model
  let kValue = 5;
  let distanceMetric = 'euclidean';
  let queryPoint = { x: 250, y: 250 };
  let points = [];

  // Seed initial cluster points
  function seedPoints() {
    points = [];
    // Class A (Blue) - centered around top-left/mid-left
    for (let i = 0; i < 11; i++) {
      points.push({
        x: Math.round(80 + Math.random() * 140),
        y: Math.round(100 + Math.random() * 200),
        label: 'A'
      });
    }
    // Class B (Red) - centered around bottom-right/mid-right
    for (let i = 0; i < 11; i++) {
      points.push({
        x: Math.round(260 + Math.random() * 160),
        y: Math.round(200 + Math.random() * 220),
        label: 'B'
      });
    }
  }

  // Calculate distance
  function getDistance(p1, p2, metric) {
    if (metric === 'manhattan') {
      return Math.abs(p1.x - p2.x) + Math.abs(p1.y - p2.y);
    } else {
      return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
    }
  }

  // Core update and render logic
  function update() {
    // 1. Calculate distances and sort
    const calculated = points.map((p, idx) => {
      const dist = getDistance(queryPoint, p, distanceMetric);
      return { ...p, dist, originalIndex: idx };
    });

    calculated.sort((a, b) => a.dist - b.dist);

    // Flag neighbors
    for (let i = 0; i < calculated.length; i++) {
      calculated[i].isNeighbor = (i < kValue);
    }

    // 2. Class voting breakdown
    let votesA = 0;
    let votesB = 0;
    for (let i = 0; i < kValue; i++) {
      if (calculated[i].label === 'A') votesA++;
      else votesB++;
    }

    // Update UI elements - Badges and bars
    const badge = document.getElementById('vote-winner-badge');
    const queryCircle = document.getElementById('query-circle');
    const queryOuterGlow = document.getElementById('query-outer-glow');

    if (votesA > votesB) {
      badge.textContent = '类别 A 胜出';
      badge.className = 'vote-badge badge-a';
      queryCircle.setAttribute('fill', '#58a6ff');
      queryOuterGlow.setAttribute('fill', 'rgba(88,166,255,0.25)');
    } else if (votesB > votesA) {
      badge.textContent = '类别 B 胜出';
      badge.className = 'vote-badge badge-b';
      queryCircle.setAttribute('fill', '#ff7b72');
      queryOuterGlow.setAttribute('fill', 'rgba(255,123,114,0.25)');
    } else {
      badge.textContent = '平局';
      badge.className = 'vote-badge badge-tie';
      queryCircle.setAttribute('fill', '#ffca28');
      queryOuterGlow.setAttribute('fill', 'rgba(255,202,40,0.25)');
    }

    const totalVotes = votesA + votesB;
    const pctA = totalVotes > 0 ? (votesA / totalVotes) * 100 : 50;
    const pctB = totalVotes > 0 ? (votesB / totalVotes) * 100 : 50;
    document.getElementById('bar-a').style.width = pctA + '%';
    document.getElementById('bar-b').style.width = pctB + '%';
    document.getElementById('count-a').textContent = votesA;
    document.getElementById('count-b').textContent = votesB;

    // 3. Render SVG Points
    const pointsGroup = document.getElementById('points-group');
    pointsGroup.innerHTML = '';
    points.forEach((p, idx) => {
      const isSelectedNeighbor = calculated.find(c => c.originalIndex === idx).isNeighbor;
      const color = p.label === 'A' ? '#58a6ff' : '#ff7b72';

      // Outer ring for selected neighbors
      if (isSelectedNeighbor) {
        const ring = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        ring.setAttribute('cx', p.x);
        ring.setAttribute('cy', p.y);
        ring.setAttribute('r', 11);
        ring.setAttribute('fill', 'none');
        ring.setAttribute('stroke', color);
        ring.setAttribute('stroke-width', 1.5);
        ring.setAttribute('opacity', '0.8');
        pointsGroup.appendChild(ring);
      }

      const dot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      dot.setAttribute('cx', p.x);
      dot.setAttribute('cy', p.y);
      dot.setAttribute('r', 6);
      dot.setAttribute('fill', color);
      dot.setAttribute('stroke', '#0d1117');
      dot.setAttribute('stroke-width', 1.5);
      pointsGroup.appendChild(dot);
    });

    // 4. Render Connection Lines and Distance Envelope
    const connectionsGroup = document.getElementById('connections-group');
    connectionsGroup.innerHTML = '';

    const kNeighbors = calculated.slice(0, kValue);
    kNeighbors.forEach(neighbor => {
      const color = neighbor.label === 'A' ? '#58a6ff' : '#ff7b72';
      if (distanceMetric === 'manhattan') {
        // Manhattan staircase path
        const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
        path.setAttribute('d', `M ${queryPoint.x} ${queryPoint.y} L ${neighbor.x} ${queryPoint.y} L ${neighbor.x} ${neighbor.y}`);
        path.setAttribute('fill', 'none');
        path.setAttribute('stroke', color);
        path.setAttribute('stroke-width', 1);
        path.setAttribute('opacity', '0.4');
        path.setAttribute('stroke-dasharray', '2 2');
        connectionsGroup.appendChild(path);
      } else {
        // Straight line
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', queryPoint.x);
        line.setAttribute('y1', queryPoint.y);
        line.setAttribute('x2', neighbor.x);
        line.setAttribute('y2', neighbor.y);
        line.setAttribute('stroke', color);
        line.setAttribute('stroke-width', 1.2);
        line.setAttribute('opacity', '0.5');
        connectionsGroup.appendChild(line);
      }
    });

    // Draw the bounding envelope containing K-nearest neighbors
    const envelope = document.getElementById('neighborhood-envelope');
    if (kNeighbors.length > 0) {
      const kDistance = kNeighbors[kNeighbors.length - 1].dist;
      if (distanceMetric === 'manhattan') {
        // Manhattan distance boundary is a diamond (rotated square)
        const d = kDistance;
        const cx = queryPoint.x;
        const cy = queryPoint.y;
        envelope.setAttribute('d', `M ${cx} ${cy - d} L ${cx + d} ${cy} L ${cx} ${cy + d} L ${cx - d} ${cy} Z`);
      } else {
        // Euclidean distance boundary is a circle
        const cx = queryPoint.x;
        const cy = queryPoint.y;
        const r = kDistance;
        envelope.setAttribute('d', `M ${cx - r},${cy} a ${r},${r} 0 1,0 ${r*2},0 a ${r},${r} 0 1,0 -${r*2},0`);
      }
      envelope.setAttribute('display', 'block');
    } else {
      envelope.setAttribute('display', 'none');
    }

    // Move query point visually
    const queryGp = document.getElementById('query-point');
    queryGp.setAttribute('transform', `translate(${queryPoint.x}, ${queryPoint.y})`);

    // 5. Render sidebar table (Top 7 closest items)
    const tbody = document.getElementById('distance-tbody');
    tbody.innerHTML = '';
    calculated.slice(0, 7).forEach((p) => {
      const tr = document.createElement('tr');
      if (p.isNeighbor) {
        tr.className = p.label === 'A' ? 'is-neighbor' : 'is-neighbor-b';
      }

      const labelColor = p.label === 'A' ? '#58a6ff' : '#ff7b72';
      tr.innerHTML = `
        <td style="color: ${labelColor}; font-weight: bold;">${p.label}</td>
        <td style="color: #8b949e;">(${p.x}, ${p.y})</td>
        <td style="text-align: right; color: ${p.isNeighbor ? '#ffca28' : '#8b949e'}; font-weight: ${p.isNeighbor ? 'bold' : 'normal'};">
          ${p.dist.toFixed(1)}
        </td>
      `;
      tbody.appendChild(tr);
    });
  }

  // Interactivity Handlers
  const stage = document.getElementById('stage');
  let isDragging = false;

  function handlePointerMove(e) {
    const rect = stage.getBoundingClientRect();
    const scaleX = 500 / rect.width;
    const scaleY = 500 / rect.height;

    let x = (e.clientX - rect.left) * scaleX;
    let y = (e.clientY - rect.top) * scaleY;

    // Clamp to SVG limits
    x = Math.max(0, Math.min(500, x));
    y = Math.max(0, Math.min(500, y));

    queryPoint = { x: Math.round(x), y: Math.round(y) };
    update();
  }

  stage.addEventListener('mousedown', (e) => {
    isDragging = true;
    handlePointerMove(e);
  });

  window.addEventListener('mousemove', (e) => {
    if (isDragging) {
      handlePointerMove(e);
    }
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
  });

  // Touch support
  stage.addEventListener('touchstart', (e) => {
    isDragging = true;
    if (e.touches ? e.touches[0] : null) {
      handlePointerMove(e.touches[0]);
    }
  });

  window.addEventListener('touchmove', (e) => {
    if (isDragging && (e.touches ? e.touches[0] : null)) {
      handlePointerMove(e.touches[0]);
    }
  }, { passive: true });

  window.addEventListener('touchend', () => {
    isDragging = false;
  });

  // Controls Event Listeners
  const kSlider = document.getElementById('k-slider');
  const kVal = document.getElementById('k-val');
  kSlider.addEventListener('input', (e) => {
    kValue = parseInt(e.target.value);
    kVal.textContent = kValue;
    update();
  });

  const metricSelect = document.getElementById('metric-select');
  metricSelect.addEventListener('change', (e) => {
    distanceMetric = e.target.value;
    update();
  });

  const btnRandomize = document.getElementById('btn-randomize');
  btnRandomize.addEventListener('click', () => {
    seedPoints();
    update();
  });

  // Init
  seedPoints();
  update();
</script>
