<script>
  // 简易 SVM 序列最小优化算法 (SMO) 求解器实现
  class SVM {
    constructor(kernelType = 'linear', C = 1.0, options = {}) {
      this.kernelType = kernelType;
      this.C = C;
      this.gamma = options.gamma || 1.0;
      this.degree = options.degree || 3;
      this.alpha = [];
      this.b = 0;
      this.X = [];
      this.Y = [];
    }

    kernel(x1, x2) {
      if (this.kernelType === 'linear') {
        return x1[0] * x2[0] + x1[1] * x2[1];
      } else if (this.kernelType === 'rbf') {
        const distSq = Math.pow(x1[0] - x2[0], 2) + Math.pow(x1[1] - x2[1], 2);
        return Math.exp(-this.gamma * distSq);
      } else if (this.kernelType === 'poly') {
        return Math.pow(x1[0] * x2[0] + x1[1] * x2[1] + 1, this.degree);
      }
      return 0;
    }

    // 简化版 SMO 算法
    fit(X, Y, maxPasses = 20, tol = 1e-3) {
      this.X = X;
      this.Y = Y;
      const N = X.length;
      this.alpha = new Array(N).fill(0);
      this.b = 0;

      if (N === 0) return;

      let passes = 0;
      while (passes < maxPasses) {
        let numChangedAlphas = 0;
        for (let i = 0; i < N; i++) {
          const Ei = this.predictScore(X[i]) - Y[i];
          if ((Y[i] * Ei < -tol && this.alpha[i] < this.C) || (Y[i] * Ei > tol && this.alpha[i] > 0)) {
            let j = Math.floor(Math.random() * (N - 1));
            if (j >= i) j++;

            const Ej = this.predictScore(X[j]) - Y[j];
            const oldAlphaI = this.alpha[i];
            const oldAlphaJ = this.alpha[j];

            let L = 0, H = this.C;
            if (Y[i] !== Y[j]) {
              L = Math.max(0, this.alpha[j] - this.alpha[i]);
              H = Math.min(this.C, this.C + this.alpha[j] - this.alpha[i]);
            } else {
              L = Math.max(0, this.alpha[i] + this.alpha[j] - this.C);
              H = Math.min(this.C, this.alpha[i] + this.alpha[j]);
            }

            if (Math.abs(L - H) < 1e-5) continue;

            const eta = 2 * this.kernel(X[i], X[j]) - this.kernel(X[i], X[i]) - this.kernel(X[j], X[j]);
            if (eta >= 0) continue;

            let newAlphaJ = this.alpha[j] - (Y[j] * (Ei - Ej)) / eta;
            if (newAlphaJ > H) newAlphaJ = H;
            else if (newAlphaJ < L) newAlphaJ = L;

            if (Math.abs(newAlphaJ - this.alpha[j]) < 1e-5) continue;

            this.alpha[j] = newAlphaJ;
            this.alpha[i] = this.alpha[i] + Y[i] * Y[j] * (oldAlphaJ - this.alpha[j]);

            const b1 = this.b - Ei - Y[i] * (this.alpha[i] - oldAlphaI) * this.kernel(X[i], X[i]) - Y[j] * (this.alpha[j] - oldAlphaJ) * this.kernel(X[i], X[j]);
            const b2 = this.b - Ej - Y[i] * (this.alpha[i] - oldAlphaI) * this.kernel(X[i], X[j]) - Y[j] * (this.alpha[j] - oldAlphaJ) * this.kernel(X[j], X[j]);

            if (this.alpha[i] > 0 && this.alpha[i] < this.C) this.b = b1;
            else if (this.alpha[j] > 0 && this.alpha[j] < this.C) this.b = b2;
            else this.b = (b1 + b2) / 2;

            numChangedAlphas++;
          }
        }
        if (numChangedAlphas === 0) passes++;
        else passes = 0;
      }
    }

    predictScore(x) {
      let score = this.b;
      for (let i = 0; i < this.X.length; i++) {
        if (this.alpha[i] > 1e-5) {
          score += this.alpha[i] * this.Y[i] * this.kernel(this.X[i], x);
        }
      }
      return score;
    }
  }

  // 状态模型
