<script>
  const canvas = document.getElementById('svmCanvas');
  const ctx = canvas.getContext('2d');

  let points = [];
  let currentClass = 1; // 1 for Red, -1 for Blue
  let kernelType = 'linear';
  let paramC = 1.0;
  let paramGamma = 0.5;
  let paramDegree = 3;

  // SVM Solver State
  let alpha = [];
  let b = 0;

  // UI Elements
  const btnClassRed = document.getElementById('btnClassRed');
  const btnClassBlue = document.getElementById('btnClassBlue');
  const btnClear = document.getElementById('btnClear');
  const btnPreset = document.getElementById('btnPreset');
  const kernelLinear = document.getElementById('kernelLinear');
  const kernelRbf = document.getElementById('kernelRbf');
  const kernelPoly = document.getElementById('kernelPoly');
  const sliderC = document.getElementById('paramC');
  const valC = document.getElementById('valC');
  const sliderGamma = document.getElementById('paramGamma');
  const valGamma = document.getElementById('valGamma');
  const sliderDegree = document.getElementById('paramDegree');
  const valDegree = document.getElementById('valDegree');
  const gammaContainer = document.getElementById('gammaContainer');
  const degreeContainer = document.getElementById('degreeContainer');

  // Kernels
  function kernel(x1, x2) {
    if (kernelType === 'linear') {
      return x1[0] * x2[0] + x1[1] * x2[1];
    } else if (kernelType === 'rbf') {
      const distSq = Math.pow(x1[0] - x2[0], 2) + Math.pow(x1[1] - x2[1], 2);
      return Math.exp(-paramGamma * distSq);
    } else if (kernelType === 'poly') {
      return Math.pow(x1[0] * x2[0] + x1[1] * x2[1] + 1, paramDegree);
    }
    return 0;
  }

  // Simplified SMO Algorithm for SVM Training
  function trainSVM() {
    const N = points.length;
    alpha = new Array(N).fill(0);
    b = 0;
    if (N < 2) return;

    const maxPasses = 40;
    const tol = 1e-3;
    let passes = 0;

    // Precompute kernel matrix
    const K = Array.from({ length: N }, () => new Array(N));
    for (let i = 0; i < N; i++) {
      for (let j = 0; j < N; j++) {
        K[i][j] = kernel(points[i].coords, points[j].coords);
      }
    }

    while (passes < maxPasses) {
      let numChangedAlphas = 0;
      for (let i = 0; i < N; i++) {
        // Calculate Ei
        let f_i = 0;
        for (let k = 0; k < N; k++) {
          f_i += alpha[k] * points[k].label * K[k][i];
        }
        f_i += b;
        const Ei = f_i - points[i].label;

        if ((points[i].label * Ei < -tol && alpha[i] < paramC) || (points[i].label * Ei > tol && alpha[i] > 0)) {
          // Select j != i randomly
          let j = Math.floor(Math.random() * (N - 1));
          if (j >= i) j++;

          // Calculate Ej
          let f_j = 0;
          for (let k = 0; k < N; k++) {
            f_j += alpha[k] * points[k].label * K[k][j];
          }
          f_j += b;
          const Ej = f_j - points[j].label;

          const oldAlphaI = alpha[i];
          const oldAlphaJ = alpha[j];

          // Compute L and H
          let L, H;
          if (points[i].label !== points[j].label) {
            L = Math.max(0, alpha[j] - alpha[i]);
            H = Math.min(paramC, paramC + alpha[j] - alpha[i]);
          } else {
            L = Math.max(0, alpha[i] + alpha[j] - paramC);
            H = Math.min(paramC, alpha[i] + alpha[j]);
          }

          if (Math.abs(L - H) < 1e-5) continue;

          // Compute eta
          const eta = 2 * K[i][j] - K[i][i] - K[j][j];
          if (eta >= 0) continue;

          // Update alpha j
          let newAlphaJ = alpha[j] - (points[j].label * (Ei - Ej)) / eta;
          if (newAlphaJ > H) newAlphaJ = H;
          else if (newAlphaJ < L) newAlphaJ = L;

          if (Math.abs(newAlphaJ - alpha[j]) < 1e-5) continue;

          alpha[j] = newAlphaJ;

          // Update alpha i
          alpha[i] = alpha[i] + points[i].label * points[j].label * (oldAlphaJ - alpha[j]);

          // Update b
          const b1 = b - Ei - points[i].label * (alpha[i] - oldAlphaI) * K[i][i] - points[j].label * (alpha[j] - oldAlphaJ) * K[i][j];
          const b2 = b - Ej - points[i].label * (alpha[i] - oldAlphaI) * K[i][j] - points[j].label * (alpha[j] - oldAlphaJ) * K[j][j];

          if (alpha[i] > 0 && alpha[i] < paramC) b = b1;
          else if (alpha[j] > 0 && alpha[j] < paramC) b = b2;
          else b = (b1 + b2) / 2;

          numChangedAlphas++;
        }
      }
      if (numChangedAlphas === 0) {
        passes++;
      } else {
        passes = 0;
      }
    }
  }

  // Evaluate decision function at normalized coordinates (x, y)
  function decisionFunction(x, y) {
    let sum = 0;
    for (let i = 0; i < points.length; i++) {
      if (alpha[i] > 1e-4) {
        sum += alpha[i] * points[i].label * kernel([x, y], points[i].coords);
      }
    }
    return sum + b;
  }

  // Draw Scene
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Decision Boundary & Margins
    if (points.length >= 2) {
      const imgData = ctx.createImageData(canvas.width, canvas.height);
      const data = imgData.data;

      for (let y = 0; y < canvas.height; y++) {
        for (let x = 0; x < canvas.width; x++) {
          const nx = x / canvas.width;
          const ny = y / canvas.height;
          const val = decisionFunction(nx, ny);

          const idx = (y * canvas.width + x) * 4;

          // Color background based on decision value
