            // Red side
            data[idx] = 244;     // R
            data[idx + 1] = 114; // G
            data[idx + 2] = 182; // B
            data[idx + 3] = Math.min(100, Math.abs(val) * 40); // Alpha
          } else {
            // Blue side
            data[idx] = 34;      // R
            data[idx + 1] = 211; // G
            data[idx + 2] = 238; // B
            data[idx + 3] = Math.min(100, Math.abs(val) * 40); // Alpha
          }

          // Draw boundary lines (contour lines)
          const absVal = Math.abs(val);
          if (absVal < 0.04) {
            // Decision Boundary (val = 0)
            data[idx] = 255;
            data[idx + 1] = 255;
            data[idx + 2] = 255;
            data[idx + 3] = 255;
          } else if (Math.abs(absVal - 1.0) < 0.03) {
            // Margins (val = 1 or -1)
            data[idx] = 251;
            data[idx + 1] = 191;
            data[idx + 2] = 36;
            data[idx + 3] = 180;
          }
        }
      }
      ctx.putImageData(imgData, 0, 0);
    }

    // Draw Grid Lines
    ctx.strokeStyle = 'rgba(148, 163, 184, 0.05)';
    ctx.lineWidth = 1;
    for (let i = 40; i < canvas.width; i += 40) {
      ctx.beginPath();
      ctx.moveTo(i, 0);
      ctx.lineTo(i, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i);
      ctx.lineTo(canvas.width, i);
      ctx.stroke();
    }

    // Draw Points
    points.forEach((pt, index) => {
      const px = pt.coords[0] * canvas.width;
      const py = pt.coords[1] * canvas.height;

      // Highlight Support Vectors
      if (alpha[index] > 1e-4) {
        ctx.beginPath();
        ctx.arc(px, py, 11, 0, 2 * Math.PI);
        ctx.strokeStyle = '#FBBF24';
        ctx.lineWidth = 2;
        ctx.setLineDash([3, 2]);
        ctx.stroke();
        ctx.setLineDash([]);
      }

      ctx.beginPath();
      ctx.arc(px, py, 6, 0, 2 * Math.PI);
      if (pt.label === 1) {
        ctx.fillStyle = '#F472B6';
        ctx.shadowColor = '#F472B6';
      } else {
        ctx.fillStyle = '#22D3EE';
        ctx.shadowColor = '#22D3EE';
      }
      ctx.shadowBlur = 6;
      ctx.fill();
      ctx.shadowBlur = 0; // Reset shadow
    });
  }

  // Event Listeners
  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = (e.clientY - rect.top) / rect.height;

    points.push({ coords: [x, y], label: currentClass });
    trainSVM();
    draw();
  });

  btnClassRed.addEventListener('click', () => {
    currentClass = 1;
    btnClassRed.classList.add('active');
    btnClassBlue.classList.remove('active');
  });

  btnClassBlue.addEventListener('click', () => {
    currentClass = -1;
    btnClassBlue.classList.add('active');
    btnClassRed.classList.remove('active');
  });

  btnClear.addEventListener('click', () => {
    points = [];
    alpha = [];
    b = 0;
    draw();
  });

  function loadPreset() {
    points = [
      { coords: [0.25, 0.3], label: 1 },
      { coords: [0.3, 0.2], label: 1 },
      { coords: [0.2, 0.45], label: 1 },
      { coords: [0.4, 0.35], label: 1 },
      { coords: [0.7, 0.7], label: -1 },
      { coords: [0.8, 0.6], label: -1 },
      { coords: [0.65, 0.8], label: -1 },
      { coords: [0.75, 0.75], label: -1 }
    ];
    trainSVM();
    draw();
  }

  btnPreset.addEventListener('click', loadPreset);

  // Kernel Selection
  function setKernel(type) {
    kernelType = type;
    kernelLinear.classList.remove('active');
    kernelRbf.classList.remove('active');
    kernelPoly.classList.remove('active');

    gammaContainer.style.display = 'none';
    degreeContainer.style.display = 'none';

    if (type === 'linear') {
      kernelLinear.classList.add('active');
    } else if (type === 'rbf') {
      kernelRbf.classList.add('active');
      gammaContainer.style.display = 'block';
    } else if (type === 'poly') {
      kernelPoly.classList.add('active');
      degreeContainer.style.display = 'block';
    }
    trainSVM();
    draw();
  }

  kernelLinear.addEventListener('click', () => setKernel('linear'));
  kernelRbf.addEventListener('click', () => setKernel('rbf'));
  kernelPoly.addEventListener('click', () => setKernel('poly'));

  // Sliders
  sliderC.addEventListener('input', (e) => {
    paramC = parseFloat(e.target.value);
    valC.textContent = paramC.toFixed(1);
    trainSVM();
    draw();
  });

  sliderGamma.addEventListener('input', (e) => {
    paramGamma = parseFloat(e.target.value);
    valGamma.textContent = paramGamma.toFixed(1);
    trainSVM();
    draw();
  });

  sliderDegree.addEventListener('input', (e) => {
    paramDegree = parseInt(e.target.value);
    valDegree.textContent = paramDegree;
    trainSVM();
    draw();
  });

  // Initial Load
  loadPreset();
</script>
