      values: { efficiency: 0.9, equity: 0.5, democracy: 0.3, market: 0.1, collaboration: 0.2 },
      color: "#4A7C59"
    },
    NPM: {
      tag: "新公共管理 (NPM)",
      title: "新公共管理",
      period: "1980年代 - 1990年代",
      concept: "引入市场竞争机制与私营部门管理技术，强调结果导向、绩效评估、顾客至上与物有所值。",
      figures: "戴维·奥斯本 (David Osborne)、特德·盖布勒 (Ted Gaebler)、胡德 (Christopher Hood)",
      role: "“掌舵人”：政府负责制定政策与合同监管，将具体服务“外包”或引入私营部门竞争。",
      balance: 25, // Heavily tilted to efficiency
      indicatorPos: "90%",
      values: { efficiency: 0.95, equity: 0.2, democracy: 0.2, market: 0.9, collaboration: 0.4 },
      color: "#C85A32"
    },
    NPS: {
      tag: "新公共服务 (NPS)",
      title: "新公共服务",
      period: "2000年代初期",
      concept: "主张回归民主价值，强调服务而非掌舵，重视公民权、公共利益、社会公平与民主问责。",
      figures: "珍妮特·登哈特 (Janet Denhardt)、罗伯特·登哈特 (Robert Denhardt)",
      role: "“服务者”：政府扮演协调与服务角色，通过建立共享的价值观念，促进公共利益的实现。",
      balance: -20, // Tilted to social equity (negative)
      indicatorPos: "20%",
      values: { efficiency: 0.5, equity: 0.9, democracy: 0.95, market: 0.3, collaboration: 0.7 },
      color: "#3C3489"
    },
    COLLAB: {
      tag: "协同治理 (Collaborative)",
      title: "协同与网络治理",
      period: "2010年代 - 至今",
      concept: "强调政府、市场、社会组织及公民组成的多元网状伙伴关系，通过协商、共识与共同行动解决复杂问题。",
      figures: "克里斯·安塞尔 (Chris Ansell)、阿利森·加什 (Alison Gash)、奥斯特罗姆 (Elinor Ostrom)",
      role: "“元治理者/促进者”：政府作为网络的设计者、促进者与规则维护者，推动多方主体协同共治。",
      balance: -5, // Near balanced, slightly favoring equity/dialogue
      indicatorPos: "45%",
      values: { efficiency: 0.8, equity: 0.85, democracy: 0.9, market: 0.5, collaboration: 0.95 },
      color: "#0F6E56"
    }
  };

  const dimensions = [
    { key: "efficiency", label: "内部效率" },
    { key: "equity", label: "社会公平" },
    { key: "democracy", label: "民主参与" },
    { key: "market", label: "市场化程度" },
    { key: "collaboration", label: "协同网络" }
  ];

  // State Management
  let currentStage = "WPA";
  let compareMode = false;

  // SVG Radar Configuration
  const width = 360;
  const height = 330;
  const cx = width / 2;
  const cy = height / 2 - 10;
  const radius = 100;

  // Render Radar Chart Background and Axes once
  function initRadar() {
    const gridsGroup = document.getElementById("radar-grids");
    const axesGroup = document.getElementById("radar-axes");
    const labelsGroup = document.getElementById("radar-labels");

    // Clear previous
    gridsGroup.innerHTML = "";
    axesGroup.innerHTML = "";
    labelsGroup.innerHTML = "";

    // Draw background concentric pentagons
    const levels = 4;
    for (let l = 1; l <= levels; l++) {
      const r = (radius / levels) * l;
      const points = dimensions.map((_, i) => {
        const angle = (i * 2 * Math.PI) / dimensions.length - Math.PI / 2;
        return `${cx + r * Math.cos(angle)},${cy + r * Math.sin(angle)}`;
      }).join(" ");

      const polygon = document.createElementNS("http://www.w3.org/2000/svg", "polygon");
      polygon.setAttribute("points", points);
      polygon.setAttribute("class", "radar-grid");
      gridsGroup.appendChild(polygon);
    }

    // Draw Axes & Labels
    dimensions.forEach((dim, i) => {
      const angle = (i * 2 * Math.PI) / dimensions.length - Math.PI / 2;
      const ax = cx + radius * Math.cos(angle);
      const ay = cy + radius * Math.sin(angle);

      // Axis Line
      const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
      line.setAttribute("x1", cx);
      line.setAttribute("y1", cy);
      line.setAttribute("x2", ax);
      line.setAttribute("y2", ay);
      line.setAttribute("class", "radar-axis");
      axesGroup.appendChild(line);

      // Label
      const label = document.createElementNS("http://www.w3.org/2000/svg", "text");
      const lx = cx + (radius + 22) * Math.cos(angle);
      const ly = cy + (radius + 14) * Math.sin(angle) + 4;
      label.setAttribute("x", lx);
      label.setAttribute("y", ly);
      label.setAttribute("text-anchor", "middle");
      label.setAttribute("class", "radar-label");
      label.setAttribute("id", `label-${dim.key}`);
      label.textContent = dim.label;

      // Hover event on dimensions
      label.addEventListener("mouseover", () => highlightDimension(dim.key));
      label.addEventListener("mouseout", () => resetDimensionHighlight());

      labelsGroup.appendChild(label);
    });
  }

  // Calculate points for a stage
  function getStagePoints(stageKey) {
    const data = stages[stageKey].values;
    return dimensions.map((dim, i) => {
      const val = data[dim.key];
      const angle = (i * 2 * Math.PI) / dimensions.length - Math.PI / 2;
      const r = radius * val;
      return `${cx + r * Math.cos(angle)},${cy + r * Math.sin(angle)}`;
    }).join(" ");
  }

  // Update Radar Polygons based on current states
  function updateRadar() {
    const polyGroup = document.getElementById("radar-polygons");
    polyGroup.innerHTML = "";

    if (compareMode) {
      // Draw all stages with lower opacity, current stage highlighted
      Object.keys(stages).forEach((key) => {
        const isCurrent = key === currentStage;
        const poly = document.createElementNS("http://www.w3.org/2000/svg", "polygon");
        poly.setAttribute("points", getStagePoints(key));
        poly.setAttribute("class", "radar-polygon");
        poly.setAttribute("fill", stages[key].color);
        poly.setAttribute("fill-opacity", isCurrent ? "0.4" : "0.08");
        poly.setAttribute("stroke", stages[key].color);
        poly.setAttribute("stroke-width", isCurrent ? "3" : "1");
        if (isCurrent) {
          poly.setAttribute("filter", "url(#glow)");
        }
        polyGroup.appendChild(poly);
      });
    } else {
      // Just draw the current active stage polygon
      const stageData = stages[currentStage];
      const poly = document.createElementNS("http://www.w3.org/2000/svg", "polygon");
      poly.setAttribute("points", getStagePoints(currentStage));
      poly.setAttribute("class", "radar-polygon");
      poly.setAttribute("fill", stageData.color);
      poly.setAttribute("fill-opacity", "0.35");
      poly.setAttribute("stroke", stageData.color);
      poly.setAttribute("stroke-width", "3");
      poly.setAttribute("filter", "url(#glow)");
      polyGroup.appendChild(poly);
    }
  }

  // Dimension Highlighting
  function highlightDimension(dimKey) {
    document.getElementById(`label-${dimKey}`).classList.add("highlighted");
    const row = document.getElementById(`row-${dimKey}`);
    if (row) row.classList.add("matrix-row-highlight");
  }

  function resetDimensionHighlight() {
    dimensions.forEach(dim => {
      document.getElementById(`label-${dim.key}`).classList.remove("highlighted");
      const row = document.getElementById(`row-${dim.key}`);
      if (row) row.classList.remove("matrix-row-highlight");
    });
  }

  // Update Details Panel Elements
  function updateDetails() {
    const data = stages[currentStage];

    // Fade out/in effect
    const card = document.getElementById("details-card");
    card.style.opacity = 0.4;

    setTimeout(() => {
      document.getElementById("card-tag").textContent = data.tag;
      document.getElementById("card-tag").style.backgroundColor = data.color;
      document.getElementById("card-title").textContent = data.title;
      document.getElementById("card-period").textContent = data.period;
      document.getElementById("card-concept").textContent = data.concept;
      document.getElementById("card-figures").textContent = data.figures;
      document.getElementById("card-role").textContent = data.role;

      // Update Balance beam and indicator
      document.getElementById("balance-beam").style.transform = `rotate(${data.balance}deg)`;
      document.getElementById("balance-indicator").style.left = data.indicatorPos;

      card.style.opacity = 1;
    }, 150);
  }

  // Event Listeners
  document.querySelectorAll(".timeline-node").forEach((node) => {
    node.addEventListener("click", () => {
      document.querySelectorAll(".timeline-node").forEach(n => n.classList.remove("active"));
      node.classList.add("active");
      currentStage = node.getAttribute("data-stage");
      updateDetails();
      updateRadar();
    });
  });

  document.getElementById("compare-toggle").addEventListener("change", (e) => {
    compareMode = e.target.checked;
    updateRadar();
  });

  // Initial Paint
  initRadar();
  updateDetails();
  updateRadar();
</script>
