  <!-- 底部全维度对比矩阵 -->
  <div class="matrix-section">
    <div class="matrix-title">百年范式横向对比速览</div>
    <div class="matrix-grid">
      <div class="matrix-card active" id="card-WPA" onclick="setStage('WPA')">
        <div class="matrix-card-header">1. 传统公共行政 (WPA)</div>
        <div style="font-size: 12px; line-height: 1.6;">
          <strong>核心特征：</strong>政治行政二分法与官僚制。<br>
          <strong>效率观：</strong>强调内部程序与结构化效率。<br>
          <strong>局限性：</strong>机构臃肿，对公众需求反应迟钝。
        </div>
      </div>
      <div class="matrix-card" id="card-NPM" onclick="setStage('NPM')">
        <div class="matrix-card-header">2. 新公共管理 (NPM)</div>
        <div style="font-size: 12px; line-height: 1.6;">
          <strong>核心特征：</strong>引入市场竞争与企业化管理。<br>
          <strong>效率观：</strong>强调产出与“花最少的钱办最多的事”。<br>
          <strong>局限性：</strong>公共价值流失，导致社会碎片化。
        </div>
      </div>
      <div class="matrix-card" id="card-NPS" onclick="setStage('NPS')">
        <div class="matrix-card-header">3. 新公共服务 (NPS)</div>
        <div style="font-size: 12px; line-height: 1.6;">
          <strong>核心特征：</strong>服务而非掌舵，关注公民权。<br>
          <strong>效率观：</strong>强调公共利益与民主协商。<br>
          <strong>局限性：</strong>理想化程度高，落地机制复杂。
        </div>
      </div>
      <div class="matrix-card" id="card-COLLAB" onclick="setStage('COLLAB')">
        <div class="matrix-card-header">4. 协同治理 (Collab)</div>
        <div style="font-size: 12px; line-height: 1.6;">
          <strong>核心特征：</strong>多中心网络与跨界合作。<br>
          <strong>效率观：</strong>强调系统协同与共治效能。<br>
          <strong>优势：</strong>有效解决复杂、非结构化公共难题。
        </div>
      </div>
    </div>
  </div>
</div>

<script>
  // 阶段数据模型
  const stagesData = {
    WPA: {
      name: "传统公共行政 (WPA)",
      period: "1880s - 1970s",
      quote: "“行政管理是政治的延伸，必须像机器一样追求效率与科层秩序。”",
      figures: "伍德罗·威尔逊 (Woodrow Wilson)、马克斯·韦伯 (Max Weber)",
      gov: "掌舵者、科层制管理者、行政规则的绝对执行者",
      citizen: "被管理者、选民、消极的公共政策接受者",
      mechanism: "政治与行政二分、理性官僚制、自上而下的集权控制",
      value: "政治中立、程序性效率、体制稳定性与法治秩序",
      radar: { efficiency: 90, democracy: 30, market: 15, collaboration: 20, equity: 50 }
    },
    NPM: {
      name: "新公共管理 (NPM)",
      period: "1980s - 1990s",
      quote: "“政府应该掌舵而不是划桨，引入市场机制才能激发公共活力。”",
      figures: "戴维·奥斯本 (David Osborne)、特德·盖布勒 (Ted Gaebler)",
      gov: "催化者、合同外包方、企业家式政府",
      citizen: "顾客、消费者、公共服务的自主选择者",
      mechanism: "绩效评估、准市场竞争、合同外包、结果导向管理",
      value: "经济(Economy)、效率(Efficiency)、效益(Effectiveness)的“3E”原则",
      radar: { efficiency: 95, democracy: 40, market: 90, collaboration: 35, equity: 30 }
    },
    NPS: {
      name: "新公共服务 (NPS)",
      period: "2000s - 2010s",
      quote: "“政府的职责是服务而非掌舵，公共利益不是市场权衡的产物。”",
      figures: "珍妮特·登哈特 (Janet Denhardt)、罗伯特·登哈特 (Robert Denhardt)",
      gov: "服务者、民主对话的促进者、公共价值的捍卫者",
      citizen: "公民、国家的所有者、公共事务的积极参与者",
      mechanism: "民主协商、公民大会、公共价值共创、全面回应诉求",
      value: "民主、社会公平、公共利益、公民尊严与责任",
      radar: { efficiency: 60, democracy: 90, market: 25, collaboration: 75, equity: 90 }
    },
    COLLAB: {
      name: "协同治理 (Collaborative Governance)",
      period: "2010s 至今",
      quote: "“面对复杂社会难题，没有任何单一主体能独自解决，协同共治是必由之路。”",
      figures: "克里斯·安塞尔 (Chris Ansell)、艾莉森·加什 (Alison Gash)",
      gov: "元治理者、网络构建者、合作平台的搭建与维护者",
      citizen: "伙伴、共治主体、公共价值的协同创造者",
      mechanism: "跨界伙伴关系、多中心治理网络、信任构建与共识达成",
      value: "系统韧性、包容性、协同增效、社会共识",
      radar: { efficiency: 80, democracy: 85, market: 55, collaboration: 95, equity: 80 }
    }
  };

  const dimensions = {
    efficiency: { name: "效率效能", desc: "指公共组织在资源配置、决策执行及服务交付上的速度与成本效益。" },
    democracy: { name: "民主回应", desc: "指公众意志对行政决策的影响深度，以及政府对多元诉求的代表性与回应度。" },
    market: { name: "市场机制", desc: "指在公共服务中引入竞争、契约外包、绩效激励等类市场手段的程度。" },
    collaboration: { name: "协同网络", desc: "指政府、企业、社会组织与公民等多主体跨界合作、联合治理的深度。" },
    equity: { name: "社会公平", desc: "指公共服务分配的均等化程度，以及对弱势群体利益与社会正义的保障。" }
  };

  // 状态变量
  let currentStage = "WPA";
  let compareMode = false;

  // 雷达图几何计算
  const radarCenter = 110;
  const radarRadius = 80;
  const dimKeys = ["efficiency", "democracy", "market", "collaboration", "equity"];

  // 计算顶点角度 (5个维度均匀分布，顶部开始)
  const angles = dimKeys.reduce((acc, key, idx) => {
    acc[key] = (idx * 2 * Math.PI / 5) - (Math.PI / 2);
    return acc;
  }, {});

  function getRadarPoints(stageKey) {
    const stage = stagesData[stageKey];
    return dimKeys.map(key => {
      const val = stage.radar[key] / 100; // 归一化
      const r = val * radarRadius;
      const x = radarCenter + r * Math.cos(angles[key]);
      const y = radarCenter + r * Math.sin(angles[key]);
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    }).join(" ");
  }

  // 初始化雷达图轴线和标签
  function initRadar() {
    const axesGroup = document.getElementById("radar-axes");
    const labelsGroup = document.getElementById("radar-labels-group");

    axesGroup.innerHTML = "";
    labelsGroup.innerHTML = "";

    dimKeys.forEach(key => {
      const angle = angles[key];
      const xOuter = radarCenter + radarRadius * Math.cos(angle);
      const yOuter = radarCenter + radarRadius * Math.sin(angle);

      // 绘制轴线
      const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
      line.setAttribute("x1", radarCenter);
      line.setAttribute("y1", radarCenter);
      line.setAttribute("x2", xOuter);
      line.setAttribute("y2", yOuter);
      line.setAttribute("class", "radar-axis-line");
      axesGroup.appendChild(line);

      // 绘制文字标签
      const labelX = radarCenter + (radarRadius + 15) * Math.cos(angle);
      const labelY = radarCenter + (radarRadius + 12) * Math.sin(angle);

      const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
      text.setAttribute("x", labelX);
      text.setAttribute("y", labelY + 4); // 垂直微调
      text.setAttribute("text-anchor", "middle");
      text.setAttribute("class", "radar-label");
      text.setAttribute("id", `radar-label-${key}`);
      text.textContent = dimensions[key].name;

      // 交互事件
      text.addEventListener("mouseenter", () => showDimensionTip(key));
      text.addEventListener("click", () => showDimensionTip(key));

      labelsGroup.appendChild(text);
    });
  }

  // 显示维度详情
  function showDimensionTip(key) {
    const tipPanel = document.getElementById("dimension-tip");
    const tipText = document.getElementById("dimension-text");

    // 清除其他高亮
    dimKeys.forEach(k => {
      document.getElementById(`radar-label-${k}`).classList.remove("active");
    });

    document.getElementById(`radar-label-${key}`).classList.add("active");
    tipText.innerHTML = `<strong>${dimensions[key].name}</strong> — ${dimensions[key].desc}`;
    tipPanel.style.display = "block";
  }

  // 切换阶段
  function setStage(stageKey) {
    currentStage = stageKey;

    // 1. 更新控制条状态
    document.querySelectorAll(".timeline-node").forEach(node => node.classList.remove("active"));
    document.querySelectorAll(".timeline-label").forEach(label => label.classList.remove("active"));
    document.getElementById(`node-${stageKey}`).classList.add("active");
    document.getElementById(`label-${stageKey}`).classList.add("active");

    // 2. 更新右侧剖析卡片内容
    const data = stagesData[stageKey];
    document.getElementById("stage-period").textContent = data.period;
    document.getElementById("stage-name").textContent = data.name;
    document.getElementById("stage-quote").textContent = data.quote;
    document.getElementById("stage-figures").textContent = data.figures;
    document.getElementById("stage-gov").textContent = data.gov;
    document.getElementById("stage-citizen").textContent = data.citizen;
    document.getElementById("stage-mechanism").textContent = data.mechanism;
    document.getElementById("stage-value").textContent = data.value;

    // 3. 更新雷达多边形
    const activePoly = document.getElementById("radar-poly-active-elem");
    activePoly.setAttribute("points", getRadarPoints(stageKey));

    // 4. 更新底部对比卡高亮
    document.querySelectorAll(".matrix-card").forEach(card => card.classList.remove("active"));
    document.getElementById(`card-${stageKey}`).classList.add("active");
  }

  // 切换叠加对比
  function toggleCompare(checked) {
    compareMode = checked;
    const comparePoly = document.getElementById("radar-poly-compare-elem");
    if (compareMode) {
      // 始终将“协同治理”作为对比基准线
      comparePoly.setAttribute("points", getRadarPoints("COLLAB"));
      comparePoly.style.display = "block";
    } else {
      comparePoly.style.display = "none";
    }
  }

  // 初始化
  initRadar();
  setStage("WPA");
</script>
</widget_code>
